import { Book } from "@/lib/types";

export const genesis: Book = {
  id: "genesis",
  name: "1. Mose (Genesis)",
  shortName: "1. Mose",
  testament: "old",
  introduction: `Das Buch von den Anfängen\n**Das erste Buch der Bibel** wird auch Genesis (d.h. Ursprung oder Entstehung) genannt. Es zeigt uns den Anfang der Schöpfung, der Menschheitsgeschichte, des Volkes Israel und der Geschichte Gottes mit den Menschen überhaupt. Es ist grundlegend für das Verständnis der ganzen Bibel, denn alle späteren biblischen Bücher nehmen in irgendeiner Weise auf dieses Buch Bezug.\nDer Verfasser des Pentateuch, also aller fünf Mosebücher, ist nach biblischer Aussage Mose, der am ägyptischen Königshof erzogene Führer Israels. Er lebte wahrscheinlich von 1527-1407 v.Chr. Alle Versuche, den Text verschiedenen Quellen zuzuordnen und seine Entstehung in verschiedenen Schichten herauszuarbeiten, haben bisher nur zu Spekulation und Subjektivität geführt. Tatsächlich hätte niemand eine bessere Qualifikation zum Schreiben der Bücher gehabt als Mose.\n****Wie es mit der Welt, den Menschen und dem Volk Israel anfing.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Im Anfang schuf Gott* Himmel und Erde.", heading: "1-11: Die Urgeschichte\nDie Schöpfung (1-2)\nDer Anfang der Welt", footnotes: ["schuf Gott. Im Hebräischen steht das Verb bara (schuf) in der Einzahl, Gott und Himmel aber in der Mehrzahl. Bara im Sinn von \"schaffen\" wird im Alten Testament nur für das Schaffen Gottes verwendet. Nie wird dabei ein Stoff erwähnt, aus dem Gott schafft."] },
      { number: 2, text: "Die Erde war formlos und leer. Finsternis lag über der Tiefe, und der Geist Gottes schwebte über dem wogenden Wasser." },
      { number: 3, text: "Da sprach Gott: \"Es werde Licht!\" Und das Licht entstand." },
      { number: 4, text: "Gott sah es an: Es war gut. Da trennte Gott das Licht von der Finsternis." },
      { number: 5, text: "Das Licht nannte er \"Tag\" und die Finsternis \"Nacht\". Es wurde Abend und wieder Morgen – ein Tag." },
      { number: 6, text: "Dann sprach Gott: \"Im Wasser soll eine Wölbung* entstehen, eine Trennung zwischen den Wassermassen!\"", footnotes: ["Wölbung. Hebräisch rakia, wahrscheinlich etwas sehr Festes und sehr Dünnes; vielleicht das, was wir heute Atmosphäre nennen, siehe Vers 6-8."] },
      { number: 7, text: "So geschah es auch. Gott machte die Wölbung und trennte die Wassermassen unterhalb der Wölbung von denen darüber." },
      { number: 8, text: "Die Wölbung nannte Gott \"Himmel\". Es wurde Abend und wieder Morgen – zweiter Tag." },
      { number: 9, text: "Dann sprach Gott: \"Die Wassermassen unter dem Himmel sollen sich an einer Stelle sammeln. Das Land soll zum Vorschein kommen.\" So geschah es." },
      { number: 10, text: "Und Gott nannte das trockene Land \"Erde\". Die Ansammlung der Wasser aber nannte er \"Meer\". Gott sah alles an: Es war gut." },
      { number: 11, text: "Dann sprach Gott: \"Die Erde lasse Gras hervorsprießen. Pflanzen und Bäume jeder Art sollen wachsen und Samen und samenhaltige Früchte tragen.\" So geschah es." },
      { number: 12, text: "Die Erde brachte frisches Grün hervor, alle Sorten samentragender Pflanzen und jede Art von Bäumen mit samenhaltigen Früchten. Gott sah es an: Es war gut." },
      { number: 13, text: "Es wurde Abend und wieder Morgen – dritter Tag." },
      { number: 14, text: "Dann sprach Gott: \"An der Wölbung des Himmels sollen Lichter entstehen. Sie sollen Tag und Nacht voneinander trennen, und als leuchtende Zeichen sollen sie die Zeiten bestimmen: Tage, Feste und Jahre." },
      { number: 15, text: "Außerdem sollen sie als Lichter am Himmelsgewölbe die Erde beleuchten.\" So geschah es." },
      { number: 16, text: "Gott machte die beiden großen Lichter: das größere, das den Tag regiert, und das kleinere für die Nacht; und dazu die Sterne." },
      { number: 17, text: "Er setzte sie an das Himmelsgewölbe, damit sie über die Erde leuchten." },
      { number: 18, text: "Sie sollten den Tag und die Nacht regieren und Licht und Finsternis voneinander trennen. Gott sah es an: Es war gut." },
      { number: 19, text: "Es wurde Abend und wieder Morgen – vierter Tag." },
      { number: 20, text: "Dann sprach Gott: \"Im Wasser soll es von Lebewesen aller Art wimmeln und am Himmel sollen Vögel fliegen!\"" },
      { number: 21, text: "Da schuf Gott die großen Seeungeheuer und Wesen aller Art, von denen die Wasser wimmeln, dazu alle Arten von geflügelten Tieren. Gott sah es an. Es war gut." },
      { number: 22, text: "Da segnete Gott seine Geschöpfe: \"Seid fruchtbar und vermehrt euch und füllt das Wasser in den Meeren! Und auch ihr Vögel, vermehrt euch auf der Erde!\"" },
      { number: 23, text: "Es wurde Abend und wieder Morgen – fünfter Tag." },
      { number: 24, text: "Dann sprach Gott: \"Die Erde soll alle Arten von Lebewesen hervorbringen: Herdenvieh und wilde Tiere und alles, was kriecht!\" So geschah es." },
      { number: 25, text: "Gott machte alle Arten von wilden Tieren, von Herdenvieh und von allem, was sich auf der Erde regt. Gott sah es an: Es war gut." },
      { number: 26, text: "Dann sprach Gott: \"Lasst uns* Menschen* machen als Abbild von uns, uns ähnlich*. Sie sollen über die Fische im Meer herrschen, über die Vögel am Himmel und über die Landtiere, über die ganze Erde und alles, was auf ihr kriecht!\"", footnotes: ["uns. Die Mehrzahl könnte hier schon ein erster Hinweis auf die Dreieinheit Gottes sein.", "Menschen. Hebräisch adam (= der vom Erdboden [adamah] Genommene) bedeutet Mensch im Allgemeinen und ist zugleich der Name des ersten Menschen. Das Wort wird nur in der Einzahl gebraucht, auch wenn von mehreren Menschen die Rede ist.", "ähnlich. Das deutet eine personale und wesensmäßige Ähnlichkeit an, wie sie auch zwischen Adam und seinem Sohn Set sichtbar wurde (siehe 1. Mose 5,3)."] },
      { number: 27, text: "Da schuf Gott den Menschen nach seinem Bild, als sein Ebenbild schuf er ihn. Er schuf sie als Mann und Frau.*", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Matthäus 19,4; Markus 10,6."] },
      { number: 28, text: "Gott segnete sie dann und sagte zu ihnen: \"Seid fruchtbar und vermehrt euch!* Füllt die Erde und macht sie euch untertan! Herrscht über die Fische im Meer, über die Vögel am Himmel und über alle Tiere, die auf der Erde leben!\"", footnotes: ["vermehrt euch. Nach jüdischer Tradition ist dies das erste der 613 Gebote."] },
      { number: 29, text: "Gott sagte: \"Zur Nahrung gebe ich euch alle samentragenden Pflanzen und alle samenhaltigen Früchte von Bäumen – überall auf der Erde." },
      { number: 30, text: "Allen Landtieren, allen Vögeln und allen Lebewesen, die auf dem Boden kriechen, gebe ich Gras und Blätter zur Nahrung.\" So geschah es." },
      { number: 31, text: "Gott sah alles an, was er gemacht hatte: Es war sehr gut. Es wurde Abend und wieder Morgen – der sechste Tag." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "So entstanden Himmel und Erde mit all ihren Lebewesen." },
      { number: 2, text: "Am siebten Tag hatte Gott das Werk vollendet und ruhte von seiner Arbeit.*", footnotes: ["Wird im Neuen Testament zitiert: Hebräer 4,4."] },
      { number: 3, text: "Gott segnete ihn und machte ihn zu einem besonderen Tag, denn an diesem Tag ruhte Gott, nachdem er sein Schöpfungswerk vollendet hatte." },
      { number: 4, text: "Es folgt die Fortsetzung* der Geschichte von Himmel und Erde, wie Gott sie geschaffen hat: Als Jahwe*, Gott, Himmel und Erde machte,", heading: "Die Menschen nach Adam (2-5)\nDer Anfang der Geschichte", footnotes: ["Fortsetzung. Das hebräische toledot bedeutet Weiterentwicklung aus Vorhandenem, es zeigt, wie die Geschichte weitergeht (oder nennt weitere Einzelheiten). Es handelt sich hier also nicht um die Nahtstelle zu einem zweiten Schöpfungsbericht. Toledot wird immer als Überschrift gebraucht, siehe 1. Mose 5,1; 6,9; 10,1; 11,10.27; 25,12.19; 36,1; 37,2.", "Jahwe ist der Name Gottes, der besonders die Gegenwart Gottes dem Menschen gegenüber ausdrückt. Siehe Vorwort des Übersetzers, sowie Fußnote zu 2. Mose 6,3."] },
      { number: 5, text: "gab es zunächst weder Sträucher noch Feldpflanzen auf dem Erdboden, denn Jahwe, Gott, hatte es noch nicht regnen lassen. Es gab auch noch keinen Menschen, der das Land bearbeiten konnte." },
      { number: 6, text: "Grundwasser stieg in der Erde auf und befeuchtete den Boden." },
      { number: 7, text: "Dann formte Jahwe, Gott, den Menschen aus loser Erde vom Ackerboden und hauchte Lebensatem in sein Gesicht*. So wurde der Mensch ein lebendes Wesen*.", footnotes: ["sein Gesicht. Das hebräische appaw bedeutet nicht nur seine Nase, sondern sein Gesicht im Allgemeinen. Je nach Zusammenhang sind Nase, Wangen oder Mund gemeint.", "Wesen oder: Seele. Der gleiche Ausdruck wird 1. Mose 1,20.24; 2,19 auf die Tiere bezogen. Der Mensch hat durchaus körperliche Ähnlichkeiten mit Säugetieren. Doch als sein Ebenbild stellte Gott den Menschen über alle anderen Lebewesen. Es ist auch zu beachten, dass hier nicht steht: Ein Lebewesen wurde Mensch. Der Mensch ist eine gesonderte Schöpfung Gottes und geht nicht aus vormenschlichem Leben hervor. Wird im Neuen Testament von Paulus zitiert: 1. Korinther 15,45."] },
      { number: 8, text: "Nun hatte Jahwe, Gott, im Osten, in Eden*, einen Garten angelegt. Dorthin versetzte er den von ihm gebildeten Menschen.", footnotes: ["Eden bedeutet Wonne. Gott hatte ein Land der Wonne für den Menschen geschaffen."] },
      { number: 9, text: "Aus dem Erdboden hatte er verschiedenartige Bäume wachsen lassen. Sie sahen prachtvoll aus und trugen wohlschmeckende Früchte. Mitten im Garten stand der Baum des Lebens und der Baum, der Gut und Böse erkennen ließ." },
      { number: 10, text: "In Eden entsprang auch ein Strom, der den Garten bewässerte und sich dann in vier Arme teilte." },
      { number: 11, text: "Der erste davon heißt Pischon. Er umfließt das ganze Land Hawila*, wo das Gold vorkommt,", footnotes: ["Hawila. Bisher sind keine Belege über ein solches Land mit dem Fluss Pischon gefunden worden."] },
      { number: 12, text: "– das Gold dieses Landes ist besonders rein – das Bedolach-Harz und der Schoham-Stein*.", footnotes: ["Bedolach ist ein kostbares, wohlriechendes Harz. Schoham ein Edelstein, vielleicht Onyx oder Karneol."] },
      { number: 13, text: "Der zweite Strom heißt Gihon. Er umfließt das Land Kusch*.", footnotes: ["Kusch. Es könnte sich um das Land der Kassiten handeln, ein Gebiet in den Bergen östlich von Mesopotamien, was auch zu 1. Mose 10,8-12 passen würde. Dann müsste der Fluss Gihon östlich des Tigris zu finden sein. Doch ein Fluss mit diesem Namen ist bisher in der antiken Literatur nicht gefunden worden."] },
      { number: 14, text: "Der dritte Strom heißt Tigris. Er fließt östlich von Assyrien. Der vierte Strom ist der Euphrat." },
      { number: 15, text: "Jahwe, Gott, brachte also den Menschen in den Garten Eden, damit er diesen bearbeite und beschütze," },
      { number: 16, text: "und wies ihn an: \"Von allen Bäumen im Garten darfst du nach Belieben essen," },
      { number: 17, text: "nur nicht von dem Baum, der dich Gut und Böse erkennen lässt. Sobald du davon isst, musst du sterben.\"" },
      { number: 18, text: "Dann sagte Jahwe, Gott: \"Es ist nicht gut, dass der Mensch so allein ist. Ich will ihm eine Hilfe machen, die ihm genau entspricht.\"" },
      { number: 19, text: "Jahwe, Gott, hatte nämlich alle Landtiere und Vögel, die er aus dem Erdboden geformt hatte, zum Menschen gebracht, um zu sehen, wie er sie nennen würde. Genauso sollten all die Lebewesen dann heißen." },
      { number: 20, text: "So hatte der Mensch dem Herdenvieh, den Vögeln und allen Landtieren Namen gegeben. Aber für sich selbst fand er nichts, was ihm als Hilfe entsprochen hätte." },
      { number: 21, text: "Da ließ Jahwe, Gott, einen Tiefschlaf über den Menschen kommen. Er nahm eine seiner beiden Seiten heraus und verschloss die Stelle mit Fleisch." },
      { number: 22, text: "Aus der Seite baute er eine Frau und brachte sie zum Menschen." },
      { number: 23, text: "Da rief der Mensch:\"Diesmal ist sie es! / Sie ist genau wie ich, / und sie gehört zu mir, / sie ist ein Stück von mir! / Sie soll Isch-scha heißen, Frau, / denn sie kam vom Isch, dem Mann.\"" },
      { number: 24, text: "Aus diesem Grund verlässt ein Mann seinen Vater und seine Mutter, verbindet sich mit seiner Frau und wird völlig eins mit ihr.*", footnotes: ["Wird im Neuen Testament von Jesus Christus und Paulus zitiert: Matthäus 19,5; Markus 10,7-8; 1. Korinther 6,16; Epheser 5,31."] },
      { number: 25, text: "Der Mann und seine Frau waren nackt, aber sie schämten sich nicht voreinander." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Die Schlange war listiger als all die Tiere, die Jahwe, Gott, gemacht hatte. Sie fragte die Frau: \"Hat Gott wirklich gesagt, dass ihr von keinem Baum im Garten essen dürft?\"", heading: "Die erste Sünde und ihre Folgen" },
      { number: 2, text: "\"Natürlich essen wir von den Früchten\", entgegnete die Frau," },
      { number: 3, text: "\"nur von den Früchten des Baumes in der Mitte des Gartens hat Gott gesagt: 'Davon dürft ihr nicht essen – sie nicht einmal berühren – sonst müsst ihr sterben.'\"" },
      { number: 4, text: "\"Sterben?\", widersprach die Schlange, \"sterben werdet ihr nicht." },
      { number: 5, text: "Aber Gott weiß genau, dass euch die Augen aufgehen, wenn ihr davon esst. Ihr werdet wissen, was Gut und Böse ist, und werdet sein wie Gott.\"" },
      { number: 6, text: "Als die Frau nun sah, wie gut von dem Baum zu essen wäre, was für eine Augenweide er war und wie viel Einsicht er versprach, da nahm sie eine Frucht und aß. Sie gab auch ihrem Mann davon, der neben ihr stand. Auch er aß." },
      { number: 7, text: "Da gingen beiden die Augen auf. Sie merkten auf einmal, dass sie nackt waren. Deshalb machten sie sich Lendenschurze aus zusammengehefteten Feigenblättern." },
      { number: 8, text: "Am Abend, als es kühler wurde, hörten sie Gott durch den Garten gehen. Da versteckten sich der Mann und seine Frau vor Gott zwischen den Bäumen." },
      { number: 9, text: "Doch Jahwe, Gott, rief den Menschen*: \"Wo bist du?\"", footnotes: ["Mensch. Siehe Fußnote zu Vers 17."] },
      { number: 10, text: "Der antwortete: \"Ich hörte dich durch den Garten gehen und bekam Angst, weil ich nackt bin. Deshalb habe ich mich versteckt.\"" },
      { number: 11, text: "\"Wer hat dir gesagt, dass du nackt bist?\", fragte Gott. \"Hast du etwa von dem verbotenen Baum gegessen?\"" },
      { number: 12, text: "Der Mensch erwiderte: \"Die Frau, die du mir zur Seite gestellt hast, gab mir etwas davon; da habe ich gegessen.\"" },
      { number: 13, text: "\"Was hast du da getan?\", fragte Jahwe, Gott, die Frau. \"Die Schlange hat mich verführt\", entgegnete sie." },
      { number: 14, text: "Da sagte Jahwe, Gott, zur Schlange:\"Weil du das getan hast, / sei mehr verflucht als alles Herdenvieh / und mehr als alle wilden Tiere! / Kriech auf dem Bauch / und friss den Staub* dein Leben lang!", footnotes: ["Das heißt nicht, dass sie sich vom Staub ernähren muss, sondern durch ihre Fortbewegungsart wird sie immer auch Staub aufnehmen müssen."] },
      { number: 15, text: "Ich stelle Feindschaft zwischen dich und die Frau, / deinem Nachwuchs und ihrem. / Er wird dir den Kopf zertreten, / und du wirst ihm die Ferse zerbeißen.\"" },
      { number: 16, text: "Zur Frau sagte er:\"Viele Beschwerden werden über dich kommen, / und dazu noch deine Schwangerschaft. / Die Kinder wirst du mit Schmerzen gebären. / Und wenn du versuchst, deinen Mann zu regieren*, / wird er doch über dich herrschen.\"", footnotes: ["regieren. Der hebräische Begriff meint die Anstrengung, jemand zu beherrschen; sich jemandes bemächtigen."] },
      { number: 17, text: "Zu Adam* sagte er: \"Weil du auf deine Frau gehört und von dem Baum gegessen hast, obwohl ich dir das ausdrücklich verboten habe, vernimm das Folgende:'Wegen dir sei der Acker verflucht! / Um dich von ihm zu ernähren, / musst du dich lebenslang mühen.", footnotes: ["Adam ist das hebräische Wort für Mensch und kann gleichzeitig als Eigenname des ersten Menschen verstanden werden."] },
      { number: 18, text: "Dornen und Disteln werden dort wachsen, / doch du bist angewiesen auf die Frucht." },
      { number: 19, text: "Mit Schweiß wirst du dein Brot verdienen, / bis du zurückkehrst zur Erde*, / von der du genommen bist. / Denn Staub bist du, / und zu Staub wirst du werden.'\"", footnotes: ["Erde. Aus dem hebräischen Wort für den Erdboden Adama ist Adam abgeleitet."] },
      { number: 20, text: "Adam gab seiner Frau den Namen Eva, Leben, denn sie sollte die Mutter aller lebenden Menschen werden." },
      { number: 21, text: "Dann bekleidete Jahwe, Gott, Adam und seine Frau mit Gewändern aus Fell" },
      { number: 22, text: "und sagte: \"Nun ist der Mensch wie einer von uns geworden. Er erkennt Gut und Böse. Auf keinen Fall darf er jetzt auch noch vom Baum des Lebens essen, um ewig zu leben.\"" },
      { number: 23, text: "Deshalb schickte Jahwe, Gott, ihn aus dem Garten Eden hinaus. Er sollte den Ackerboden bearbeiten, von dem er genommen war." },
      { number: 24, text: "So vertrieb er den Menschen. Östlich vom Garten Eden stellte er Cherubim auf, Engelwesen mit Flammenschwertern, die den Weg zum Baum des Lebens bewachen." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Adam hatte mit seiner Frau Eva geschlafen. Nun wurde sie schwanger und gebar Kain. Da sagte sie: \"Ich habe einen Mann erworben*, Jahwe*.\"", heading: "Der erste Mord und was dann kam", footnotes: ["erworben. Hebräisch: qanah. Wortspiel mit Kain (qajin).", "Jahwe. Die meisten ergänzen: (Mit Hilfe) Jahwes. Doch vielleicht gibt Eva ihrem Erstgeborenen den Gottesnamen Jahwe, weil sie hofft, dass er der verheißene Mann sein würde, der der Schlange den Kopf zertritt."] },
      { number: 2, text: "Danach bekam sie seinen Bruder Abel*. Abel wurde ein Schafhirt*, Kain ein Landwirt.", footnotes: ["Abel. Hebräisch: habäl. Der Name klingt an Hauch, Nichtigkeit an (häbäl).", "Schafhirt. Eigentlich Kleinviehhirt. Kleinvieh meinte Schafe und Ziegen."] },
      { number: 3, text: "Nach geraumer Zeit brachte Kain vom Ertrag seines Feldes Jahwe ein Opfer." },
      { number: 4, text: "Auch Abel brachte ihm eine Opfergabe, das Beste von den erstgeborenen Lämmern seiner Herde. Jahwe sah freundlich auf Abel und sein Opfer." },
      { number: 5, text: "Aber auf Kain und seine Opfergabe achtete er nicht. Da geriet Kain in heftigen Zorn und senkte finster sein Gesicht." },
      { number: 6, text: "Jahwe fragte ihn:\"Warum bist du so zornig? / Was soll dein finsterer Blick? / Hast du Gutes im Sinn, / dann heb den Kopf hoch!" },
      { number: 7, text: "Wenn aber nicht, / dann lauert die Sünde vor der Tür / und will dich verschlingen. / Aber du, du musst sie bezwingen.\"" },
      { number: 8, text: "Doch Kain sprach seinen Bruder an.* Und als sie auf dem Feld waren, fiel er über Abel her und schlug ihn tot.", footnotes: ["sprach ... an. Eine hebräische Handschrift und einige alte Übersetzungen fügen hier ein: Lass uns aufs Feld gehen!"] },
      { number: 9, text: "Da sagte Jahwe zu Kain: \"Wo ist Abel, dein Bruder?\" Der entgegnete: \"Ich weiß nicht. Bin ich etwa sein Aufpasser?\" – \"Was hast du da getan!\", erwiderte Gott," },
      { number: 10, text: "\"Hörst du nicht das Blut deines Bruders aus dem Ackerboden zu mir schreien?" },
      { number: 11, text: "Verflucht sollst du sein, verbannt vom Ackerboden! Denn du hast ihn mit dem Blut deines Bruders getränkt." },
      { number: 12, text: "Wenn du ihn künftig bebaust, wird er dir keinen Ertrag mehr bringen. Als ruheloser Flüchtling wirst du auf der Erde umherirren.\"" },
      { number: 13, text: "Da sagte Kain zu Jahwe: \"Diese Strafe ist zu schwer für mich. Ich werde sie nicht ertragen können." },
      { number: 14, text: "Du vertreibst mich vom fruchtbaren Land, und auch vor dir muss ich mich verstecken. Als ruheloser Flüchtling werde ich umherirren, und jeder, der mich sieht,* kann mich ungestraft töten.\"", footnotes: ["jeder, der mich sieht. Das meint natürlich jüngere Verwandte von ihm (siehe Kapitel 5,4), die ihm wegen der Langlebigkeit der ersten Generationen noch gefährlich werden konnten. Die damalige Weltbevölkerung vermehrte sich enorm schnell."] },
      { number: 15, text: "\"Nein\", erwiderte Jahwe, \"ich ordne an: Wer Kain erschlägt, wird siebenfach bestraft!\" Und er machte ein Zeichen an Kain, damit niemand es wagen würde, ihn zu erschlagen, wenn er ihm begegnete." },
      { number: 16, text: "So verließ Kain die Nähe Jahwes und siedelte sich östlich von Eden an, im Land der Heimatlosigkeit, in Nod." },
      { number: 17, text: "Als Kain mit seiner Frau schlief, wurde sie schwanger und gebar Henoch. Und als Kain dann eine Stadt gründete, benannte er sie nach seinem Sohn Henoch." },
      { number: 18, text: "Dem Henoch wurde Irad geboren. Irad zeugte Mehujael und der wiederum Metuschael. Metuschael wurde der Vater von Lamech." },
      { number: 19, text: "Lamech aber nahm sich zwei Frauen: Eine hieß Ada, die andere Zilla." },
      { number: 20, text: "Ada gebar ihm Jabal. Das wurde sozusagen der Stammvater aller Nomaden, die in Zelten wohnen und mit ihren Herden umherziehen." },
      { number: 21, text: "Sein Bruder hieß Jubal. Er war der erste aller späteren Zither- und Flötenspieler." },
      { number: 22, text: "Auch Zilla bekam einen Sohn, Tubal-Kain, den Schmied. Er war der erste, der Kupfer und Eisen bearbeitete. Seine Schwester hieß Naama." },
      { number: 23, text: "Lamech sagte zu seinen Frauen:\"Ada und Zilla, hört meine Rede! / Lamechs Frauen, lauscht meinem Spruch! / Ich habe den Mann erschlagen, der mich verwundet hat, / und den Jungen getötet, der mich berührte." },
      { number: 24, text: "Wird Kain siebenfach gerächt, / dann Lamech siebenundsiebzigfach!\"" },
      { number: 25, text: "Nachdem Adam wieder mit seiner Frau Eva geschlafen hatte, gebar sie ihm einen Sohn und nannte ihn Set, Setzling. \"Gott hat mir wieder einen Sprössling geschenkt\", sagte sie, \"anstelle von Abel, weil Kain ihn erschlug.\"" },
      { number: 26, text: "Auch Set wurde ein Sohn geboren. Enosch, Menschlein, nannte er ihn. Damals fing man an, den Namen Jahwes anzurufen*.", footnotes: ["anzurufen. Oder: auszurufen. Das heißt, zu ihm zu beten, oder von ihm zu predigen."] },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Es folgt das Verzeichnis der Nachkommen* Adams.Als Gott den Menschen schuf, gestaltete er ihn nach seinem Abbild.", heading: "Wie es nach Adam weiterging", footnotes: ["Wörtlich: Buch der Geschlechterfolge (Hebräisch: sefer toledot, siehe 1. Mose 2,4)."] },
      { number: 2, text: "Er schuf ihn als Mann und Frau.* Dann segnete er sie und gab ihnen noch am Tag ihrer Erschaffung den Namen \"Mensch\".", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Matthäus 19,4; Markus 10,6."] },
      { number: 3, text: "Als Adam 130 Jahre gelebt hatte, zeugte er einen Sohn namens Set, der ihm wie sein Ebenbild ähnlich war." },
      { number: 4, text: "Nach der Geburt Sets lebte Adam noch 800 Jahre und zeugte weitere Söhne und Töchter," },
      { number: 5, text: "bis er im Alter von 930 Jahren starb." },
      { number: 6, text: "Set war 105 Jahre alt, als er Enosch zeugte." },
      { number: 7, text: "Nach dessen Geburt lebte er noch 807 Jahre und zeugte weitere Söhne und Töchter," },
      { number: 8, text: "bis er im Alter von 912 Jahren starb." },
      { number: 9, text: "Als Enosch 90 Jahre gelebt hatte, zeugte er Kenan." },
      { number: 10, text: "Nach dessen Geburt lebte er noch 815 Jahre und zeugte weitere Söhne und Töchter," },
      { number: 11, text: "bis er im Alter von 905 Jahren starb." },
      { number: 12, text: "Kenan war 70 Jahre alt, als er Mahalalel zeugte." },
      { number: 13, text: "Nach dessen Geburt lebte er noch 840 Jahre und zeugte weitere Söhne und Töchter," },
      { number: 14, text: "bis er im Alter von 910 Jahren starb." },
      { number: 15, text: "Als Mahalalel 65 Jahre alt war, zeugte er Jered." },
      { number: 16, text: "Nach dessen Geburt lebte er noch 830 Jahre und zeugte weitere Söhne und Töchter," },
      { number: 17, text: "bis er im Alter von 895 Jahren starb." },
      { number: 18, text: "Jered war 162 Jahre alt, als er Henoch zeugte." },
      { number: 19, text: "Nach dessen Geburt lebte er noch 800 Jahre und zeugte weitere Söhne und Töchter," },
      { number: 20, text: "bis er im Alter von 962 Jahren starb." },
      { number: 21, text: "Als Henoch 65 Jahre alt war, zeugte er Metuschelach*.", footnotes: ["Metuschelach. Der Mensch, der offenbar am längsten auf der Erde gelebt hat, siehe Vers 26. Als Methusalem ist er sprichwörtlich geworden."] },
      { number: 22, text: "Nach dessen Geburt lebte er noch 300 Jahre mit Gott und zeugte weitere Söhne und Töchter," },
      { number: 23, text: "bis er 365 Jahre alt war.*", footnotes: ["bis er 365 Jahre alt war. Das war im Jahr 987 nach Adams Erschaffung."] },
      { number: 24, text: "Henoch hatte beständig mit Gott gelebt, und dann war er plötzlich nicht mehr da, weil Gott ihn weggenommen hatte.*", footnotes: ["Wird im Neuen Testament zitiert: Hebräer 11,5."] },
      { number: 25, text: "Metuschelach war 187 Jahre alt, als er Lamech zeugte." },
      { number: 26, text: "Nach dessen Geburt lebte er noch 782 Jahre und zeugte weitere Söhne und Töchter," },
      { number: 27, text: "bis er im Alter von 969 Jahren starb*.", footnotes: ["im Alter von 969 Jahren. Das war im Jahr 1656 nach Adam, im Jahr der Sintflut."] },
      { number: 28, text: "Als Lamech 182 Jahre alt war*, zeugte er einen Sohn,", footnotes: ["182 Jahre alt war. Das Geburtsjahr Noahs wäre also das Jahr 1056 nach Adam."] },
      { number: 29, text: "den er Noah, Tröster, nannte, und sagte: \"Der wird uns Trost verschaffen bei der harten Arbeit auf dem Ackerboden, den Jahwe verflucht hat.\"" },
      { number: 30, text: "Nach Noahs Geburt lebte Lamech noch 595 Jahre und zeugte weitere Söhne und Töchter," },
      { number: 31, text: "bis er im Alter von 777 Jahren starb." },
      { number: 32, text: "Von seinem 500. Lebensjahr an zeugte Noah Sem, Ham und Jafet.*", footnotes: ["Sem, Ham und Jafet. Die Namen sind nach ihrer Bedeutung geordnet. Nach 1. Mose 11,10 kann man das Geburtsjahr Sems mit 1558 nach Adam berechnen, das entspricht dem 502. Jahr Noahs. Nach 1. Mose 9,24 war Ham der jüngste Sohn Noahs. Demnach wird Jafet als der Älteste im 500. Jahr Noahs geboren worden sein. Siehe Fußnote zu 1. Mose 10,21."] },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Als die Menschen immer zahlreicher wurden und sich auf der Erde ausbreiteten,", heading: "Die Menschen nach Noah (6-11)\nNoah vor der großen Flut" },
      { number: 2, text: "sahen die Gottessöhne*, wie schön die Töchter der Menschen waren, und nahmen sich die zu Frauen, die ihnen gefielen.", footnotes: ["Gottessöhne. Der Begriff kann in der Bibel sowohl Engelwesen als auch Menschen bezeichnen. Vielleicht bezieht er sich hier auf damalige despotische Herrscher, die sich Städte bauen ließen und den Lebensstil und die Grausamkeit Lamechs nachahmten. Sie fingen an, sich Göttersöhne zu nennen und hatten Umgang mit dämonischen Mächten (vergleiche Hesekiel 28,11-15; Daniel 10,13). Gegen die Deutung, dass es sich bei ihnen um Engel handeln würde, spricht Matthäus 22,30 und Judas 6-7. Außerdem wären dann Menschen für das bestraft worden, was Engel verschuldet haben. Gegen die Deutung Menschen der Linie Set spricht, dass sie sich eben nicht Töchter Kains, sondern Töchter der Menschen nahmen."] },
      { number: 3, text: "Da sagte Jahwe: \"Mein Geist soll nicht für immer in diesen sterblichen Menschen bleiben. Ich gebe ihnen noch eine Frist* von 120 Jahren.\"", footnotes: ["Frist. Manche Übersetzungen beziehen die 120 Jahre auf das Lebensalter. Das ist aber nicht sinnvoll, weil auch nach der Flut Menschen noch viel älter wurden und Gott ja auch nicht androhte, das Lebensalter zu verringern, sondern die Menschen zu vernichten. Die 120 Jahre beziehen sich eher auf die Zeit bis zur Flut."] },
      { number: 4, text: "Damals lebten die Riesen auf der Erde und auch dann noch, als die Gottessöhne Kinder mit den Menschentöchtern hatten. Das wurden die Helden der Vorzeit, berühmte Männer." },
      { number: 5, text: "Jahwe aber sah, wie groß die Bosheit der Menschen auf der Erde war. Ihr ganzes Denken und Streben, alles, was aus ihrem Herzen kam, war immer nur böse." },
      { number: 6, text: "Jahwe bekümmerte es, den Menschen erschaffen zu haben, und es schmerzte ihn bis in sein Innerstes hinein." },
      { number: 7, text: "Er beschloss: \"Ich werde den Menschen, den ich geschaffen habe, vom Erdboden wegwischen, samt dem Vieh, den Kriechtieren und Vögeln, denn ich bedaure, sie gemacht zu haben.\"" },
      { number: 8, text: "Nur Noah fand Gnade vor Jahwe." },
      { number: 9, text: "Es folgt die Geschichte* Noahs. Noah war ein gerechter* Mann. Seine Zeitgenossen fanden nichts Tadelnswertes an ihm. Er lebte beständig mit Gott.", footnotes: ["Geschichte. Hebräisch toledot, siehe 1. Mose 2,4.", "Der Gerechte im Alten Testament ist ein Mensch, der mit Gott und Menschen im richtigen Verhältnis lebt und sich nach Gottes Geboten richtet. Er steht im Gegensatz zu dem, der sich an Gott und Menschen schuldig macht, dem Gottlosen, dem Frevler."] },
      { number: 10, text: "Drei Söhne hatte er: Sem, Ham und Jafet." },
      { number: 11, text: "Die Erde aber verdarb vor Gott und füllte sich mit Verbrechen." },
      { number: 12, text: "Gott sah sich das an: Die Erde war vollkommen verdorben, denn alle Menschen waren vom rechten Weg abgekommen." },
      { number: 13, text: "Da sagte Gott zu Noah: \"Ich habe beschlossen, Mensch und Tier zu vernichten, denn durch sie ist die Erde von Gewalttat erfüllt." },
      { number: 14, text: "Baue dir eine Arche, einen Kasten aus Tannenholz! Teile ihn in mehrere Räume ein und dichte ihn innen und außen mit Asphalt* ab!", footnotes: ["Asphalt. Siehe Fußnote zu 1. Mose 14,10."] },
      { number: 15, text: "Er soll 150 Meter* lang sein, 25 Meter breit und 15 Meter hoch.", footnotes: ["150 Meter. Wörtlich: dreihundert Ellen. Weil die für eine Elle angegebenen Maße zwischen 44,42 und 52,45 cm schwanken, gehen wir für die meisten Umrechnungen von 50 cm aus. Dadurch werden auch die Proportionen deutlicher."] },
      { number: 16, text: "Sorge auch für eine Lichtöffnung! Sie darf bis zu einem halben Meter unter den Dachrand reichen. Setze eine Tür in die Mitte ihrer Längsseite. Drei Stockwerke soll die Arche insgesamt haben." },
      { number: 17, text: "Denn ich, ich werde die Flut kommen lassen, eine Wasserflut über die Erde. Alles Lebendige soll darin umkommen, alle Menschen und Tiere." },
      { number: 18, text: "Mit dir aber schließe ich folgenden Bund: Du sollst mit deiner Frau, deinen Söhnen und ihren Frauen in die Arche gehen." },
      { number: 19, text: "Und von allen Tieren sollst du je ein Männchen und ein Weibchen in die Arche bringen, damit sie zusammen mit dir am Leben bleiben." },
      { number: 20, text: "Von jeder Art der Vögel, der Land- und Kriechtiere soll je ein Pärchen in die Arche kommen, damit sie überleben können." },
      { number: 21, text: "Lege ausreichend Vorräte an, dass ihr und die Tiere damit versorgt werden können.\"" },
      { number: 22, text: "Noah machte alles genauso, wie Gott es ihm befohlen hatte." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Dann sagte Jahwe zu Noah: \"Komm du mit deiner ganzen Familie in die Arche, denn du bist der einzige Gerechte in dieser Generation.", heading: "Die große Flut kommt über die Erde" },
      { number: 2, text: "Nimm dir von allen reinen* Tieren je sieben Männchen und Weibchen mit, von den unreinen aber nur je ein Pärchen.", footnotes: ["Was reine und unreine Tiere sind, wird in 3. Mose 11 definiert. Reine Tiere waren für das Volk Israel zur Speise freigegeben."] },
      { number: 3, text: "Auch von den Vögeln bringe je sieben Männchen und Weibchen mit, dass jede Art auf der ganzen Erde erhalten bleibt und sich vermehren kann." },
      { number: 4, text: "In sieben Tagen werde ich einen Regen über die Erde kommen lassen, der 40 Tage lang, Tag und Nacht, andauern wird. So werde ich alles Bestehende, alles, was ich gemacht habe, von der Erdoberfläche wegwischen.\"" },
      { number: 5, text: "Noah machte alles genauso, wie Jahwe es ihm befohlen hatte." },
      { number: 6, text: "Als die Flut über die Erde hereinbrach, war Noah 600 Jahre alt." },
      { number: 7, text: "Er ging also mit seiner Frau, seinen Söhnen und deren Frauen in die Arche, um sich vor den Wassermassen in Sicherheit zu bringen." },
      { number: 8, text: "Alle reinen und unreinen Tiere, die Vögel und die Kriechtiere" },
      { number: 9, text: "kamen paarweise in die Arche, je ein Männchen und ein Weibchen, wie Gott es Noah befohlen hatte." },
      { number: 10, text: "Sieben Tage später kamen die Fluten über die Erde." },
      { number: 11, text: "Im 600. Lebensjahr Noahs, am 17. Tag des zweiten Monats, wurden die Schleusen des Himmels geöffnet, und alle Quellen der großen Tiefe* brachen auf.", footnotes: ["Tiefe. Dasselbe Wort wie 1. Mose 1,2."] },
      { number: 12, text: "Es regnete in Strömen 40 Tage lang, Tag und Nacht." },
      { number: 13, text: "An dem oben genannten Tag also war Noah mit seinen Söhnen Sem, Ham und Jafet, mit seiner Frau und den Frauen seiner Söhne in die Arche gegangen" },
      { number: 14, text: "und mit allen Arten von Wildtieren und Herdenvieh, Kriechtieren und vielfältig gefiederten Vögeln." },
      { number: 15, text: "Alle Lebewesen, alle, die Atem in sich hatten, waren paarweise zu Noah in die Arche gekommen." },
      { number: 16, text: "Es waren immer ein Männchen und ein Weibchen, wie Gott es Noah befohlen hatte. Dann schloss Jahwe hinter ihm zu." },
      { number: 17, text: "40 Tage lang ergoss sich die Flut über die Erde." },
      { number: 18, text: "Das Wasser stieg und hob die Arche vom Boden ab." },
      { number: 19, text: "Es stieg immer höher und höher, bis alle hohen Berge auf der Erde zugedeckt waren." },
      { number: 20, text: "Mehr als sieben Meter hoch* deckte das Wasser die Berge zu.", footnotes: ["sieben Meter hoch. Das könnte der Tiefgang der Arche gewesen sein."] },
      { number: 21, text: "Da ging alles zugrunde, was auf der Erde lebte und sich regte: Vögel, Herdenvieh und wilde Tiere und alle Menschen." },
      { number: 22, text: "Alles, was einen Lebenshauch in sich trug und auf dem Festland lebte, ging zugrunde." },
      { number: 23, text: "So löschte Gott alles aus, was auf dem Erdboden bestand: vom Menschen bis zum Herdenvieh, von den Vögeln bis zu den Kriechtieren. Alle fanden den Tod. Nur Noah und alle, die mit ihm in der Arche waren, blieben übrig." },
      { number: 24, text: "150 Tage lang überflutete das Wasser die Erde." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Gott dachte an Noah und an all die Wildtiere und das Herdenvieh, das mit ihm in der Arche war, und er ließ einen Wind über die Erde wehen. Da zog sich das Wasser zurück,", heading: "Das Ende der Flut" },
      { number: 2, text: "die Quellen der Tiefe und die Schleusen des Himmels wurden verschlossen und der Regen zurückgehalten." },
      { number: 3, text: "Allmählich verliefen sich die Wassermassen. Im Lauf von 150 Tagen nahmen sie immer mehr ab," },
      { number: 4, text: "und am 17. Tag des siebten Monats setzte die Arche irgendwo auf dem Gebirge Ararat auf." },
      { number: 5, text: "Das Wasser nahm immer weiter ab, sodass man am ersten Tag des zehnten Monats die Bergspitzen sehen konnte." },
      { number: 6, text: "40 Tage später öffnete Noah das Fenster, das er in die Arche eingelassen hatte, und ließ einen Raben hinaus." },
      { number: 7, text: "Der flog hin und zurück, immer wieder, bis die Erde trocken war." },
      { number: 8, text: "Später ließ Noah eine Taube fliegen, um zu sehen, ob sich das Wasser vom Erdboden verlaufen hätte." },
      { number: 9, text: "Doch die Taube fand keinen Ruheplatz für sich, überall stand noch Wasser auf der Erde. Da kehrte sie zu ihm zurück. Er langte mit dem Arm hinaus und holte sie wieder in die Arche." },
      { number: 10, text: "Dann wartete er weitere sieben Tage und ließ sie noch einmal fliegen." },
      { number: 11, text: "Gegen Abend kam die Taube. Im Schnabel hatte sie ein frisch abgerissenes Olivenblatt. Noah erkannte jetzt, dass sich das Wasser von der Erde verlaufen hatte." },
      { number: 12, text: "Er wartete noch einmal sieben Tage und ließ die Taube wieder hinaus. Jetzt kehrte sie nicht mehr zu ihm zurück." },
      { number: 13, text: "Im 601. Lebensjahr Noahs, am ersten Tag des ersten Monats, war das Wasser von der Erde abgetrocknet. Als Noah jetzt das Dach der Arche entfernte und Ausschau hielt, sah er, dass kein Wasser mehr auf der Erde stand." },
      { number: 14, text: "Am 27. Tag des zweiten Monats war die Erde trocken." },
      { number: 15, text: "Da sagte Gott zu Noah:" },
      { number: 16, text: "\"Verlass jetzt die Arche mit deiner Frau, deinen Söhnen und ihren Frauen." },
      { number: 17, text: "Und lass alle Tiere, die bei dir sind, mit hinausziehen: die Vögel, das Herdenvieh und alles, was sich auf der Erde regt. Sie sollen fruchtbar sein und sich vermehren. Auf der Erde soll es wieder wimmeln von ihnen.\"" },
      { number: 18, text: "Da ging Noah mit seinen Söhnen, seiner Frau und seinen Schwiegertöchtern ins Freie." },
      { number: 19, text: "Auch alle Arten von Tieren, alles, was kriecht und fliegt und sich auf der Erde regt, zog aus der Arche." },
      { number: 20, text: "Dann baute Noah Jahwe einen Altar. Dort opferte er ihm einige von den reinen Tieren und Vögeln als Brandopfer." },
      { number: 21, text: "Jahwe roch den angenehmen Duft und sagte sich: \"Nicht noch einmal werde ich nur wegen des Menschen den Erdboden verfluchen. Alles, was aus seinem Herzen kommt, ist ja böse – von seiner frühesten Jugend an. Nicht noch einmal werde ich alles Lebendige auslöschen, wie ich es tat." },
      { number: 22, text: "Von jetzt an, / solange die Erde besteht, / soll nicht aufhören: / Saat und Ernte, / Frost und Hitze, / Sommer und Winter, / Tag und Nacht.\"" },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Dann segnete Gott Noah und seine Söhne. Er sagte: \"Seid fruchtbar, vermehrt euch und füllt die Erde.", heading: "Gottes Bund mit Noah und mit allen Menschen" },
      { number: 2, text: "Alle Tiere, alle Vögel, alles, was sich auf der Erde regt, und auch alle Fische sind in eure Gewalt gegeben. Sie werden vor euch erschrecken und sich fürchten." },
      { number: 3, text: "Und alles, was da lebt und sich regt, soll euch wie die Pflanzen zur Nahrung dienen." },
      { number: 4, text: "Nur das Fleisch, das sein Lebensblut noch in sich hat, dürft ihr nicht essen." },
      { number: 5, text: "Euer eigenes Blut darf auf keinen Fall vergossen werden, denn ich wache darüber und werde es wieder einfordern, vom Tier genauso wie vom Menschen. Ich werde Rechenschaft für das Leben jedes Menschen fordern." },
      { number: 6, text: "Wer das Blut von Menschen vergießt – durch Menschen werde vergossen sein Blut! / Denn der Mensch ist zum Abbild Gottes gemacht." },
      { number: 7, text: "Und ihr, seht zu, dass ihr viele Nachkommen habt! Bevölkert die Erde!\"" },
      { number: 8, text: "Und dann sagte Gott zu Noah und seinen Söhnen:" },
      { number: 9, text: "\"Ich schließe diesen Bund mit euch und euren Nachkommen" },
      { number: 10, text: "und auch mit allen Lebewesen bei euch, mit den Tieren, die in der Arche waren." },
      { number: 11, text: "Und ich sichere euch zu: Nie wieder werde ich das Leben durch eine Wasserflut vernichten. Nie mehr wird eine Flut die Erde zerstören." },
      { number: 12, text: "Dieser Bund zwischen mir und euch gilt jeder kommenden Generation und jedem Lebewesen bei euch." },
      { number: 13, text: "Und als Zeichen dafür setze ich meinen Bogen in die Wolken." },
      { number: 14, text: "Jedes Mal, wenn ich Wolken über der Erde zusammenziehe und wenn dann der Bogen erscheint," },
      { number: 15, text: "werde ich an mein Versprechen denken, das ich euch und allen Lebewesen gegeben habe: Nie mehr sollen die Wassermassen zu einer Flut werden, die alles Leben vernichtet." },
      { number: 16, text: "Der Regenbogen wird in den Wolken stehen, und ich werde ihn ansehen und an den ewigen Bund denken, den ich mit euch und allen Lebewesen auf der Erde geschlossen habe." },
      { number: 17, text: "Und dieser Bogen\", sagte Gott zu Noah, \"ist das Zeichen für den gültigen Bund.\"" },
      { number: 18, text: "Zusammen mit Noah hatten auch Sem, Ham und Jafet die Arche verlassen. Ham war übrigens der Stammvater von Kanaan." },
      { number: 19, text: "Von diesen drei Söhnen Noahs stammen alle Völker der Erde ab." },
      { number: 20, text: "Noah begann als Ackerbauer und legte auch Weinberge an." },
      { number: 21, text: "Eines Tages trank er so viel von seinem Wein, dass er betrunken wurde und entblößt in seinem Zelt lag." },
      { number: 22, text: "Ham, der Stammvater Kanaans, sah ihn in seiner Nacktheit daliegen und erzählte es seinen Brüdern draußen." },
      { number: 23, text: "Aber Sem und Jafet nahmen einen Mantel, hielten ihn zwischen ihre Schultern und gingen rückwärts ins Zelt. Das Gesicht abgewandt deckten sie ihren Vater zu, denn sie wollten seine Nacktheit nicht sehen." },
      { number: 24, text: "Als Noah seinen Rausch ausgeschlafen hatte, erfuhr er von dem beschämenden Verhalten seines jüngsten Sohnes" },
      { number: 25, text: "und sagte über einen von dessen Nachkommen:\"Verflucht sei Kanaan! / Der niedrigste Sklave wird er seinen Brüdern sein!" },
      { number: 26, text: "Doch gepriesen sei Jahwe, Sems Gott! / Und Kanaan sei ein Sklave von Sem!" },
      { number: 27, text: "Gott kehre ein* zu Jafet / und wohne in den Zelten von Sem! / Und Kanaan wird auch sein Sklave sein.\"", footnotes: ["Gott kehre ein. Hebräisch jaft, was an Jafet anklingt. Das Verb kann noch nicht befriedigend erklärt werden. Es wird hier in Anlehnung an das arabische fata mit einkehren wiedergegeben."] },
      { number: 28, text: "Nach der Flut lebte Noah noch 350 Jahre." },
      { number: 29, text: "Er starb im Alter von insgesamt 950 Jahren." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Es folgt das Verzeichnis der Nachkommen* von Sem, Ham und Jafet, den Söhnen Noahs, deren Söhne aber erst nach der großen Flut geboren wurden.", footnotes: ["Verzeichnis der Nachkommen. Hebräisch toledot, siehe 1. Mose 2,4. Hier in Kapitel 10, das auch mit \"Völkertafel\" überschrieben ist, werden insgesamt 70 Namen aufgeführt. Deshalb symbolisiert die Zahl 70 in der Theologie der Rabbinen die Völkerwelt."] },
      { number: 2, text: "Die Söhne Jafets waren Gomer, Magog, Madai, Jawan, Tubal, Meschech und Tiras.", heading: "Die Jafetiten" },
      { number: 3, text: "Gomers Söhne waren Aschkenas, Rifat und Togarma." },
      { number: 4, text: "Die Nachkommen Jawans waren Elischa und Tarschisch, außerdem die Kittäer und die Rodaniter." },
      { number: 5, text: "Jawans Nachkommen breiteten sich in den Küstenländern bis zum Rand der Erde aus. Sie wuchsen zu Völkern mit eigenen Sprachen heran und lebten in ihren Gebieten in Sippen zusammen." },
      { number: 6, text: "Die Söhne Hams waren Kusch, Mizrajim, Put und Kanaan.", heading: "Die Hamiten" },
      { number: 7, text: "Von Kusch stammen Seba, Hawila, Sabta, Ragma und Sabtecha ab. Ragmas Söhne waren Saba und Dedan." },
      { number: 8, text: "Kusch war auch der Vater von Nimrod, dem ersten Gewaltherrscher auf der Erde." },
      { number: 9, text: "Der war ein kühner Jäger. Deshalb sagt man heute noch* sprichwörtlich: \"Er ist ein gewaltiger Jäger vor Jahwe wie Nimrod.\"", footnotes: ["heute noch. Das meint den Zeitpunkt, als das Buch verfasst wurde."] },
      { number: 10, text: "Zuerst herrschte er über die Städte Babel, Erech* und Akkad, die im Gebiet von Schinar* liegen.", footnotes: ["Babel, Erech. Die Städte lagen im Umkreis von 100 km um Babylon. Erech (o. Uruk, heute: Warka) war eine der wichtigsten Städte im alten Mesopotamien.", "Schinar. Anderer Name für Babylonien."] },
      { number: 11, text: "Von da aus zog er in das Land Assur und gründete dort Ninive mit seinen weiten offenen Plätzen* und Kelach*", footnotes: ["offenen Plätzen. Hebräisch: Rehobot-Ir. Das ist wahrscheinlich eine nähere Beschreibung von Ninive.", "Kelach. Die Städte liegen etwa 500 km nördlich von Babel. Kelach (heute: Nimrud) befindet sich 40 km südlich von Ninive am Ostufer des Tigris."] },
      { number: 12, text: "sowie Resen zwischen Ninive und Kelach. Das war das große Städtezentrum." },
      { number: 13, text: "Von Mizrajim stammen die Luditer, Anamiter, Lehabiter und Naftuhiter," },
      { number: 14, text: "die Patrusiter und die Kasluhiter, von denen die Philister herkommen, und die Kaftoriter." },
      { number: 15, text: "Kanaan war der Vater von Sidon und Het. Sidon war sein Erstgeborener." },
      { number: 16, text: "Außerdem stammen von ihm die Jebusiter, die Amoriter und die Girgaschiter ab," },
      { number: 17, text: "die Hiwiter, Arkiter, Siniter," },
      { number: 18, text: "Arwaditer, Zemariter und Hamatiter. Später haben sich die Sippen der Kanaaniter weiter ausgebreitet," },
      { number: 19, text: "sodass ihr Gebiet von Sidon* bis nach Gerar und Gaza* reichte und ostwärts bis nach Sodom und Gomorra, Adma, Zebojim und Lescha*.", footnotes: ["Sidon war eine Stadt in Phönizien, heute Saida im Libanon.", "Gaza. Das Gebiet, in dem sich später die Philister ansiedelten. 300 km südlich von Sidon.", "Lescha. Fünf kanaanäische Stadtstaaten, die in dem Gebiet lagen, das heute vom südlichen Teil des Toten Meeres bedeckt wird."] },
      { number: 20, text: "Die Nachkommen Hams wuchsen zu Völkern mit eigenen Sprachen heran und lebten in ihren Gebieten in Sippen zusammen." },
      { number: 21, text: "Auch Sem, dem Bruder des älteren Jafet*, wurden Söhne geboren. Er ist der Stammvater aller Nachkommen Ebers.", heading: "Die Semiten", footnotes: ["älteren Jafet. Kann theoretisch auch übersetzt werden: älteren Bruder Jafets. Doch wegen 1. Mose 9,24; 11,10 wird Jafet der Älteste gewesen sein. Siehe Fußnote zu 1. Mose 5,32!"] },
      { number: 22, text: "Die Söhne Sems waren Elam, Assur, Arpachschad, Lud und Aram." },
      { number: 23, text: "Arams Söhne hießen Uz, Hul, Geter und Masch." },
      { number: 24, text: "Arpachschad war der Vater von Schelach und Schelach der Vater von Eber." },
      { number: 25, text: "Eber wurden zwei Söhne geboren. Der eine hieß Peleg, Teilung, weil zu seiner Zeit die Erde geteilt wurde,* und der andere Joktan.", footnotes: ["geteilt wurde. Das könnte man im Sinn einer Aufteilung der Erdoberfläche unter die Völker verstehen wie sie in 1. Mose 11 berichtet ist. Manche sehen hier aber auch einen Hinweis auf den Beginn der Kontinentalverschiebung, was geologisch allerdings sehr problematisch ist."] },
      { number: 26, text: "Joktans Söhne waren Almodad, Schelef, Hazarmawet und Jerach," },
      { number: 27, text: "Hadoram, Usal und Dikla," },
      { number: 28, text: "Obal, Abimael und Saba," },
      { number: 29, text: "Ofir, Hawila und Jobab. Das waren also die Nachkommen Joktans." },
      { number: 30, text: "Ihr Gebiet reicht von Mescha über Sefar bis an das Gebirge im Osten.*", footnotes: ["Gebiet ... im Osten. Das Gebiet lag vermutlich in Arabien, südlich von Israel."] },
      { number: 31, text: "Die Nachkommen Sems wuchsen zu Völkern mit eigenen Sprachen heran und lebten in ihren Gebieten in Sippen zusammen." },
      { number: 32, text: "Diese Sippen sind Nachkommen der Söhne Noahs. Von ihnen stammen alle Völker ab, die sich nach der Flut auf der ganzen Erde ausgebreitet haben." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Die Menschen hatten damals alle noch dieselbe Sprache und dieselben Wörter.", heading: "Der Turm von Babel" },
      { number: 2, text: "Als sie nach Osten zogen, fanden sie eine Ebene im Land Schinar und ließen sich dort nieder." },
      { number: 3, text: "Sie sagten zueinander: \"Los! Wir machen Ziegel aus Lehm und brennen sie zu Stein!\" Die Ziegel wollten sie als Bausteine verwenden und Asphalt als Mörtel." },
      { number: 4, text: "Dann sagten sie: \"Los! Bauen wir eine Stadt und einen Turm, der bis an den Himmel reicht! So werden wir uns einen Namen machen und verhindern, dass wir uns über die ganze Erde zerstreuen.\"" },
      { number: 5, text: "Jahwe kam herab, um sich anzusehen, was die Menschen da bauten – eine Stadt mit einem Turm!" },
      { number: 6, text: "Da sagte er: \"Es ist offensichtlich: Sie sind ein einziges Volk und sprechen nur eine Sprache. Und was sie jetzt begonnen haben, zeigt, dass ihnen künftig nichts unmöglich sein wird. Sie werden alles tun, was sie sich ausdenken." },
      { number: 7, text: "Los! Steigen wir hinunter und verwirren ihre Sprache, dass keiner mehr den anderen versteht!\"" },
      { number: 8, text: "So zerstreute Jahwe die Menschen von dort aus über die ganze Erde, und sie mussten aufhören, die Stadt zu bauen." },
      { number: 9, text: "Deswegen gab man der Stadt den Namen Babel, Verwirrung, denn Jahwe hatte dort die Sprache der Menschen verwirrt und sie von diesem Ort aus über die ganze Erde zerstreut." },
      { number: 10, text: "Es folgt das Verzeichnis der Nachkommen Sems: Zwei Jahre nach der Flut wurde Sem der Vater von Arpachschad. Er war damals 100 Jahre alt", heading: "Von Sem bis Abram" },
      { number: 11, text: "und lebte noch 500 Jahre, in denen er weitere Söhne und Töchter zeugte." },
      { number: 12, text: "Arpachschad wurde mit 35 Jahren der Vater von Schelach" },
      { number: 13, text: "und lebte noch 403 Jahre, in denen er ebenfalls weitere Söhne und Töchter zeugte." },
      { number: 14, text: "Mit 30 Jahren zeugte Schelach Eber" },
      { number: 15, text: "und lebte danach noch 403 Jahre, in denen ihm weitere Söhne und Töchter geboren wurden." },
      { number: 16, text: "Eber war 34 Jahre alt, als er Peleg zeugte," },
      { number: 17, text: "und lebte dann noch 430 Jahre, in denen er weitere Söhne und Töchter zeugte." },
      { number: 18, text: "Peleg wurde mit 30 Jahren der Vater von Regu." },
      { number: 19, text: "Er lebte noch 209 Jahre, in denen er ebenfalls weitere Söhne und Töchter zeugte." },
      { number: 20, text: "Regu zeugte mit 32 Jahren Serug" },
      { number: 21, text: "und lebte dann noch 207 Jahre, in denen er Söhne und Töchter zeugte." },
      { number: 22, text: "Mit 30 Jahren wurde Serug der Vater von Nahor" },
      { number: 23, text: "und lebte dann noch 119 Jahre, in denen er weitere Söhne und Töchter zeugte." },
      { number: 24, text: "Mit 29 Jahren wurde Nahor der Vater von Terach." },
      { number: 25, text: "Danach lebte er noch 119 Jahre und bekam weitere Söhne und Töchter." },
      { number: 26, text: "Von seinem 70. Lebensjahr an zeugte Terach Abram, Nahor und Haran.*", footnotes: ["Die Namen sind wie in Vers 27 nach ihrer Bedeutung geordnet. Abram wurde erst im 130. Jahr Terachs geboren (siehe Vers 32; 1. Mose 12,4; Apostelgeschichte 7,4)."] },
      { number: 27, text: "Es folgt das Verzeichnis der Nachkommen Terachs. Terach wurde der Vater von Abram, Nahor und Haran. Haran war der Vater Lots" },
      { number: 28, text: "und starb noch zu Lebzeiten seines Vaters Terach in seiner Heimatstadt Ur* in Chaldäa*.", footnotes: ["Ur war wohl die bedeutendste Stadt im südlichen Zweistromland (Mesopotamien). Nach Ausgrabungen zu urteilen hatte sie schon vor Abrams Zeit eine hohe Kulturstufe erreicht.", "Chaldäa. So wurde das Gebiet des südlichen Zweistromlandes bezeichnet. Der Begriff konnte später auch für ganz Babylonien stehen."] },
      { number: 29, text: "Abram und Nahor heirateten dann. Abrams Frau hieß Sarai*, Nahors Frau Milka. Sie war die Tochter Harans* und Schwester von Jiska.", footnotes: ["Sarai. Nach 1. Mose 20,12 war das seine Halbschwester. Im Gesetz Moses wurde das später verboten (vergleiche 3. Mose 18,9; 20,17; 5. Mose 27,22).", "Tochter Harans. Nahor heiratete also seine Nichte, was auch später im Gesetz des Mose nicht verboten war."] },
      { number: 30, text: "Doch Sarai konnte keine Kinder bekommen." },
      { number: 31, text: "Terach brach aus Ur in Chaldäa auf, um nach Kanaan* zu ziehen. Er nahm seinen Sohn Abram, seinen Enkel Lot und seine Schwiegertochter Sarai mit. Doch als sie nach Haran* gekommen waren, ließen sie sich dort nieder.", footnotes: ["Kanaan. Das Land Kanaan umfasste etwa das Gebiet des heutigen Libanon und Israel.", "In Haran wurde genauso wie in Ur der Mondgott verehrt. Die Stadt lag aber noch 800 km von Kanaan entfernt."] },
      { number: 32, text: "Dort starb auch Terach im Alter von 205 Jahren." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Da sagte Jahwe zu Abram: \"Zieh aus deinem Land weg! Verlass deine Sippe und auch die Familie deines Vaters und geh in das Land, das ich dir zeigen werde!*", heading: "12-50: Die Vätergeschichte\nDas Leben Abrahams (12-24)\nAbrams Berufung", footnotes: ["Wird im Neuen Testament von Stephanus zitiert: Apostelgeschichte 7,3."] },
      { number: 2, text: "Ich will dich zu einem großen Volk werden lassen; ich werde dich segnen und deinen Namen bekannt machen. Du wirst ein Segen für andere sein." },
      { number: 3, text: "Ich will segnen, die dich segnen, und verfluchen, die dir fluchen. Alle Sippen der Erde werden durch dich gesegnet sein.\"*", footnotes: ["Wird im Neuen Testament mit 1. Mose 18,18 von Paulus zitiert: Galater 3,8."] },
      { number: 4, text: "Abram gehorchte dem Befehl Jahwes und brach auf. Lot zog mit ihm. Abram war 75 Jahre alt, als er Haran verließ.", heading: "Abram in Kanaan" },
      { number: 5, text: "Seine Frau Sarai und sein Neffe Lot begleiteten ihn. Sie nahmen alle Menschen, die sie in Haran erworben hatten, und ihren ganzen Besitz mit. So zogen sie nach Kanaan." },
      { number: 6, text: "Abram durchzog das Land bis zu einem Platz bei Sichem* in der Nähe des Wahrsagebaums*. Damals waren ja noch die Kanaaniter im Land.", footnotes: ["Sichem war eine strategisch und religiös bedeutende Stadt auf dem Pass (Sichem = Schulter) zwischen den Bergen Ebal im Norden und Garizim im Süden.", "Wahrsagebaum. Wörtlich: Orakelterebinthe. Unter solchen Bäumen vernahmen die Wahrsager angeblich die Stimme Gottes im Rauschen der Zweige."] },
      { number: 7, text: "Dort ließ sich Jahwe von Abram sehen* und sagte zu ihm: \"Dieses Land will ich deinen Nachkommen geben!\" Da baute Abram an dieser Stelle einen Altar für Jahwe, der ihm erschienen war.", footnotes: ["Jahwe ... sehen. Bei dieser und anderen Gotteserscheinungen lässt Jahwe sich von Menschen (manchmal von mehreren gleichzeitig) in einer Art und Weise sehen, die diese (oft gerade noch) ertragen und verstehen können. Nie offenbart er sich in ganzer Herrlichkeit, denn das wäre für jeden Menschen tödlich (2. Mose 33,20). Vergleiche auch die Fußnote zu 1. Mose 15,1!"] },
      { number: 8, text: "Später zog er in das Bergland östlich von Bet-El und schlug seine Zelte so auf, dass er Bet-El im Westen und Ai im Osten hatte. Auch dort baute er Jahwe einen Altar und machte so den Namen Jahwes bekannt*.", footnotes: ["machte bekannt. Das hebräische Wort kann anrufen (=beten) oder ausrufen (=bekannt machen) bedeuten."] },
      { number: 9, text: "Dann brach er wieder auf und zog immer weiter in den Negev* hinein.", footnotes: ["Negev bezeichnet das Südland Kanaans."] },
      { number: 10, text: "Als eine schwere Hungersnot im Land ausbrach, suchte Abram Zuflucht in Ägypten.", heading: "Abram und Sarai in Ägypten" },
      { number: 11, text: "Kurz vor der ägyptischen Grenze sagte er zu seiner Frau Sarai: \"Ich weiß, dass du eine sehr schöne Frau bist." },
      { number: 12, text: "Wenn die Ägypter dich sehen, werden sie sagen: 'Das ist seine Frau!', und sie werden mich totschlagen, um dich zu bekommen." },
      { number: 13, text: "Sag doch, dass du meine Schwester bist, dann werden sie mich deinetwegen gut behandeln und am Leben lassen!\"" },
      { number: 14, text: "Tatsächlich geschah es so, als Abram nach Ägypten kam. Überall fiel seine Frau durch ihre Schönheit auf." },
      { number: 15, text: "Die Hofleute rühmten sie vor dem Pharao, und der ließ sie in seinen Palast holen." },
      { number: 16, text: "Ihretwegen überhäufte er Abram mit Geschenken. Er ließ ihm Schafe, Ziegen, Rinder und Esel zukommen, Sklaven und Sklavinnen, Eselstuten und Kamele." },
      { number: 17, text: "Doch weil der Pharao Abrams Frau zu sich genommen hatte, schlug Jahwe ihn und seine Familie mit schweren Krankheiten." },
      { number: 18, text: "Da ließ der Pharao Abram zu sich rufen. \"Was hast du mir da angetan?\", warf er ihm vor. \"Warum hast du mir nicht gesagt, dass sie deine Frau ist?" },
      { number: 19, text: "Du hast sie als deine Schwester ausgegeben, und nur deshalb habe ich sie mir zur Frau genommen! Nun, hier ist deine Frau! Nimm sie und geh!\"" },
      { number: 20, text: "Dann gab der Pharao seinen Männern Befehl, Abram und seinen Besitz sicher aus dem Land zu bringen." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Von Ägypten kehrte Abram mit seiner Frau, seinem Besitz und seinem Neffen Lot wieder in den Negev zurück.", heading: "Abram und Lot" },
      { number: 2, text: "Abram war sehr reich. Eine Menge Vieh und Silber und Gold gehörten ihm." },
      { number: 3, text: "Er zog von einem Lagerplatz zum anderen, bis er wieder an die Stelle kam, wo sein Zelt zuerst gestanden hatte, zwischen Bet-El und Ai," },
      { number: 4, text: "wo er früher den Altar gebaut hatte. Dort rief er den Namen Jahwes an." },
      { number: 5, text: "Auch Lot, der mit Abram gezogen war, besaß Kleinvieh, Rinder und Zelte." },
      { number: 6, text: "Doch das Weideland reichte nicht für beide aus. Ihr Herdenbesitz war zu groß. So konnten sie unmöglich beisammen bleiben." },
      { number: 7, text: "Es gab immer Streit zwischen den Hirten von Abrams und Lots Vieh. Damals wohnten ja auch noch die Kanaaniter und Perisiter* im Land.", footnotes: ["Perisiter.Bewohner Kanaans; manche verstehen sie nicht als eigenen Stamm, sondern als die Dorfbewohner."] },
      { number: 8, text: "Abram besprach das mit Lot. Er sagte: \"Es soll kein Streit zwischen uns sein, auch nicht zwischen unseren Hirten. Wir sind doch Brüder!" },
      { number: 9, text: "Steht dir nicht das ganze Land offen? Trenn dich doch von mir! Willst du nach links, dann gehe ich nach rechts, und willst du nach rechts, dann gehe ich nach links.\"" },
      { number: 10, text: "Lot schaute sich um und sah, dass es in der Jordanebene reichlich Wasser gab. Bevor Jahwe nämlich Sodom und Gomorra zerstörte, war diese Gegend bis nach Zoar* hin wie der Garten Jahwes und wie Ägypten.", footnotes: ["Zoar. Stadt am Südende des Toten Meeres, die beim Gericht über Sodom und Gomorra wegen Lot verschont wurde."] },
      { number: 11, text: "Deshalb entschied sich Lot für die Jordangegend und zog nach Osten. So trennten sich beide:" },
      { number: 12, text: "Abram blieb im Land Kanaan, Lot zog ins Gebiet der Jordanstädte und kam mit seinen Zelten bis nach Sodom." },
      { number: 13, text: "Doch die Einwohner von Sodom waren sehr böse und sündigten schwer gegen Jahwe." },
      { number: 14, text: "Nachdem Lot weggezogen war, sagte Jahwe zu Abram: \"Blick auf und schau dich nach allen Seiten gründlich um!" },
      { number: 15, text: "Das ganze Land, das du siehst, will ich dir und deinen Nachkommen* für immer geben.", footnotes: ["deinen Nachkommen. Wörtlich: deinem Samen (Singular). Wird im Neuen Testament von Paulus zitiert: Galater 3,16."] },
      { number: 16, text: "Und deine Nachkommen werde ich zahlreich machen wie den Staub der Erde. Nur wenn jemand die Staubkörner zählen könnte, können auch deine Nachkommen gezählt werden." },
      { number: 17, text: "Mach dich auf, und durchziehe das Land nach allen Richtungen! Denn dir will ich es geben.\"" },
      { number: 18, text: "Abram zog mit seinen Zelten weiter und nahm seinen Wohnsitz unter den Terebinthen* von Mamre* bei Hebron. Dort baute er Jahwe einen Altar.", footnotes: ["Terbinthe. Belaubter Baum mit breitem Wipfel, der nicht mehr als 7 Meter hoch und als Schattenspender geschätzt wird.", "Mamre liegt dem heutigen Hebron gegenüber. Damals hat es dort wenigstens einen Brunnen und einen Hain von Terebinthen gegeben."] },
    ] },
    { number: 14, verses: [
      { number: 1, text: "In dieser Zeit führten die Könige Amrafel von Schinar, Arjoch von Ellasar, Kedor-Laomer von Elam sowie der Völkerkönig Tidal*", footnotes: ["Tidal. Es handelt sich offenbar um Könige aus dem syrisch-babylonischen Raum."] },
      { number: 2, text: "Krieg gegen die Könige Bera von Sodom, Birscha von Gomorra, Schinab von Adma, Schemeber von Zebojim und den König von Bela, das heute Zoar heißt.*", footnotes: ["Zoar heißt. Die Namen der Stadtkönige aus dem Tal des Toten Meeres sind amoritisch."] },
      { number: 3, text: "Diese fünf hatten sich verbündet und waren in das Tal Siddim gezogen, wo heute das Salzmeer* ist.", footnotes: ["Salzmeer. Gemeint ist das Tote Meer, das einen Salzgehalt von 25% hat, sodass kein Fisch darin leben kann."] },
      { number: 4, text: "Zwölf Jahre waren sie Kedor-Laomer untertan gewesen, doch im dreizehnten hatten sie gegen seine Herrschaft rebelliert." },
      { number: 5, text: "Jetzt im vierzehnten Jahr rückten Kedor-Laomer und die mit ihm verbündeten Könige heran. Zuerst besiegten sie die Refaïter bei Aschterot-Karnajim*, die Susiter bei Ham*, die Emiter in der Ebene von Kirjatajim*", footnotes: ["Aschterot und Karnajim lagen etwa 35 km östlich des Sees Gennesaret.", "Ham liegt etwa 65 km nördlich von Amman im Ostjordanland.", "Die Ebene von Kirjatajim liegt vermutlich östlich vom Toten Meer."] },
      { number: 6, text: "und die Horiter, die im Bergland von Seïr* bis nach El-Paran am Rand der Wüste lebten.", footnotes: ["Das Bergland von Seïr erstreckt sich östlich der Araba bis nach Elat (El-Paran) am Roten Meer."] },
      { number: 7, text: "Dann zogen sie in nordwestlicher Richtung bis nach En-Mischpat, das jetzt Kadesch* heißt, und verwüsteten das ganze Gebiet der Amalekiter und auch die Gegend von Hazezon-Tamar*, die von Amoritern* besiedelt war.", footnotes: ["Kadesch (Kadesch-Barnea) lag an der Südgrenze von Kanaan, etwa 80 km südwestlich von Beerscheba.", "Hazezon-Tamar liegt etwa 43 km südwestlich vom Toten Meer.", "Amoriter kann sowohl für einen einzelnen Stamm als auch für alle Bewohner Kanaans stehen. Es waren semitische Einwanderer aus der Arabischen Wüste, die um 2000 v.Chr. ins Kulturland eindrangen."] },
      { number: 8, text: "Im Tal Siddim stellten sich ihnen die fünf Stadtkönige entgegen" },
      { number: 9, text: "und kämpften gegen die vier angreifenden Könige." },
      { number: 10, text: "Nun war das Siddimtal voll von Asphaltgruben*, und als die Könige von Sodom und Gomorra flohen, gerieten sie da hinein. Die anderen Könige flohen ins Gebirge.", footnotes: ["Asphaltgruben. Asphalt entsteht auch auf natürliche Weise aus Erdöl, das durch Verdunstung und Oxidation zu Bitumen wird und sich dabei mit Mineralstoffen vermischt. Es wurde als Mörtel und zum Abdichten von Schiffen und Gefäßen verwendet."] },
      { number: 11, text: "Die Sieger plünderten Sodom und Gomorra und nahmen alle Lebensmittelvorräte mit." },
      { number: 12, text: "Auch Abrams Neffen Lot, der inzwischen in Sodom wohnte, schleppten sie mit und dazu seinen ganzen Besitz." },
      { number: 13, text: "Einer von denen, die entkommen konnten, berichtete dem Hebräer* Abram, was geschehen war. Abram wohnte damals noch unter den Terebinthen des Amoriters Mamre. Das war ein Bruder von Eschkol und Aner, Abrams Verbündeten.", footnotes: ["Hebräer. In der Bibel wird der Begriff meist von Nichtisraeliten als herabsetzende Bezeichnung für die Nachkommen Abrahams gebraucht."] },
      { number: 14, text: "Als Abram hörte, dass sein Brudersohn in Gefangenschaft geraten war, rief er die kampferprobten Leute zusammen, die in seinen Zelten geboren worden waren, 318 Mann*. Mit ihnen verfolgte er den Heerhaufen. In Dan* holte er sie ein", footnotes: ["318 Mann. Wenn Abram so viel kriegstüchtige Männer von seinen hausgeborenen Sklaven aufbieten konnte, muss er über einen Hausstand von mindestens 1000 Mann verfügt haben.", "Die Stadt Dan lag an der Nordgrenze Israels, am Fuß des Berges Hermon, etwa 250 km von Abrams Siedlungsplatz entfernt."] },
      { number: 15, text: "und überfiel sie in der Nacht. Er hatte seine Männer in zwei Gruppen geteilt. So schlug er sie in die Flucht und verfolgte sie noch bis nach Hoba*, das nördlich von Damaskus liegt.", footnotes: ["Die genaue Lage von Hoba ist unbekannt, die Stadt muss etwa 80 km nordöstlich von Dan gelegen haben."] },
      { number: 16, text: "Er nahm ihnen die ganze Beute ab und befreite seinen Neffen Lot, die Frauen und alle anderen Gefangenen." },
      { number: 17, text: "Als Abram nach seinem Sieg über Kedor-Laomer und die anderen Könige zurückkehrte, zog ihm der König von Sodom entgegen ins Schawetal, das heute Königstal* heißt.", footnotes: ["Königstal. Zur Zeit der Niederschrift des 1. Buches Mose und mindestens bis zur Zeit Abschaloms (vergleiche 2. Samuel 18,18) hieß das Kidrontal, das auf der Ostseite von Jerusalem liegt, Königstal."] },
      { number: 18, text: "Auch Melchisedek*, der König von Salem*, kam dorthin und brachte Brot und Wein mit. Er war Priester Gottes, des Höchsten,", footnotes: ["Melchisedek bedeutet: \"Mein König ist Gerechtigkeit\", vergleiche Hebräer 7,2.", "Salem ist eine Kurzform von Jerusalem, vergleiche Psalm 76,3, und klingt an das hebräische Wort für \"Frieden\" an, vergleiche Hebräer 7,2."] },
      { number: 19, text: "und segnete Abram. Er sagte: \"Gesegnet sei Abram von Gott, dem Höchsten, dem Himmel und Erde gehört." },
      { number: 20, text: "Und gepriesen sei Gott, der Höchste, der deine Feinde dir ausgeliefert hat.\"Abram gab ihm den zehnten Teil von aller Beute." },
      { number: 21, text: "Da sagte der König von Sodom zu Abram: \"Gib mir meine Leute zurück, alles andere kannst du behalten!\"" },
      { number: 22, text: "Doch Abram erwiderte: \"Ich schwöre bei Jahwe, bei Gott, dem Höchsten, dem Himmel und Erde gehört:" },
      { number: 23, text: "Nicht einen Faden oder Schuhriemen werde ich von dem behalten, was dir gehört! Du sollst niemals sagen können: 'Ich habe Abram reich gemacht.'" },
      { number: 24, text: "Ich nehme nichts für mich. Nur das behalte ich, was meine Männer verzehrt haben und was meinen Bundesgenossen Aner, Eschkol und Mamre zusteht. Die sollen ihren Anteil an der Beute erhalten.\"" },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Nach diesen Ereignissen empfing Abram folgende Botschaft Jahwes in einer Vision*: \"Hab keine Angst, Abram! Ich selbst bin dein Schutz. Du wirst reich belohnt werden.\"", heading: "Gottes Bund mit Abram", footnotes: ["Vision. Übernatürliche visuell-akustische Erfahrung eines einzelnen Menschen, durch die ihm Gott eine Botschaft mitteilt. Sie unterscheidet sich deutlich von einem Traum. Vergleiche auch die Fußnote zu 1. Mose 12,17!"] },
      { number: 2, text: "Da erwiderte Abram: \"Jahwe, mein Herr, was willst du mir denn geben? Ich werde ja kinderlos sterben, und meinen Besitz erbt Eliëser von Damaskus*.", footnotes: ["Eliëser von Damaskus war offenbar der oberste Verwalter von Abrams Besitztümern, siehe 1. Mose 24,2. Abram hatte ihn nach damaligem Recht als Wahlerbe eingesetzt, der allerdings zurücktreten musste, wenn doch noch ein Sohn geboren wurde."] },
      { number: 3, text: "Du hast mir doch keinen Sohn gegeben. Der Sklave, der in meinem Haus geboren wurde, wird mich beerben.\"" },
      { number: 4, text: "Da kam das Wort Jahwes zu ihm: \"Nein, er wird nicht dein Erbe sein, sondern einer, den du zeugen wirst, der soll dich beerben.\"" },
      { number: 5, text: "Darauf führte er ihn ins Freie und sagte: \"Blick doch zum Himmel auf und zähle die Sterne*, wenn du es kannst!\" Und fügte hinzu: \"So wird deine Nachkommenschaft sein!\"*", footnotes: ["Sterne. Siehe Fußnote zu 1. Mose 22,7.", "Wird im Neuen Testament von Paulus zitiert: Römer 4,18."] },
      { number: 6, text: "Abram glaubte Jahwe, und das rechnete er ihm als Gerechtigkeit an.*", footnotes: ["Wird im Neuen Testament von Paulus und Jakobus zitiert: Römer 4,3; Galater 3,6; Jakobus 2,23."] },
      { number: 7, text: "Dann sagte er: \"Ich, Jahwe, habe dich aus Ur in Chaldäa geführt, um dir dieses Land als Eigentum zu geben.\"" },
      { number: 8, text: "\"Jahwe, mein Herr\", erwiderte Abram, \"woran könnte ich erkennen, dass ich es je besitzen werde?\"" },
      { number: 9, text: "Da sagte er: \"Bring mir eine dreijährige Kuh, eine dreijährige Ziege, einen dreijährigen Schafbock, eine Turteltaube und eine junge Taube!\"" },
      { number: 10, text: "Abram holte die Tiere, zerteilte jedes in zwei Hälften und legte die Teile einander gegenüber.* Nur die Vögel zerteilte er nicht.", footnotes: ["zerteilte ... gegenüber. Damit wurde ein feierlich beschworener Vertrag vorbereitet. Die Vertragspartner gingen dann mit einer brennenden Fackel zwischen den zerschnittenen Tierkörpern hindurch. Damit erklärten sie: Im Fall eines Meineides soll es mir so wie diesen Tieren ergehen."] },
      { number: 11, text: "Da fielen Raubvögel über die Fleischstücke her, doch Abram verscheuchte sie." },
      { number: 12, text: "Als nun die Sonne unterging, fiel ein Tiefschlaf auf Abram, und eine unheimliche, erdrückende Angst legte sich auf ihn." },
      { number: 13, text: "Da sagte Jahwe zu ihm: \"Du sollst jetzt erfahren, dass deine Nachkommen als Fremde in einem Land leben werden, das ihnen nicht gehört. Dort werden sie unterdrückt und zu Sklavendiensten gezwungen – vierhundert Jahre lang.*", footnotes: ["Wird im Neuen Testament von Stephanus zitiert: Apostelgeschichte 7,6-7. Es handelt sich um eine runde Zahl, siehe 2. Mose 12,40."] },
      { number: 14, text: "Aber auch das Volk, dem sie dienen müssen, wird mein Strafgericht treffen. Und dann werden sie mit großem Besitz von dort wegziehen." },
      { number: 15, text: "Du selbst wirst ein hohes Alter erreichen und in Frieden sterben und begraben werden." },
      { number: 16, text: "Erst die vierte Generation wird hierher zurückkehren, denn die Schuld der Amoriter* hat noch nicht ihr volles Maß erreicht.\"", footnotes: ["Schuld der Amoriter. Vergleiche 1. Mose 14,7."] },
      { number: 17, text: "Als dann die Sonne untergegangen und es ganz finster geworden war, fuhr auf einmal etwas zwischen den zerteilten Tieren hindurch, das wie ein rauchender Schmelzofen aussah und wie eine brennende Fackel." },
      { number: 18, text: "So schloss Jahwe damals einen Bund mit Abram und versprach ihm: \"Deinen Nachkommen gebe ich dieses Land, vom Strom Ägyptens bis an den Euphrat," },
      { number: 19, text: "das ganze Gebiet der Keniter, Kenasiter und Kadmoniter," },
      { number: 20, text: "der Hetiter, Perisiter und Refaïter," },
      { number: 21, text: "der Amoriter, Kanaaniter, Girgaschiter und Jebusiter.\"" },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Doch Abrams Frau Sarai blieb kinderlos. Nun hatte sie eine ägyptische Sklavin, namens Hagar.", heading: "Hagar und Ismaël" },
      { number: 2, text: "Da sagte sie zu Abram: \"Du siehst, dass Jahwe mich keine Kinder bekommen lässt. Wenn du dich jedoch mit meiner Sklavin einlässt, komme ich vielleicht durch sie zu einem Kind.\" Abram war einverstanden." },
      { number: 3, text: "Da gab Sarai ihm ihre ägyptische Sklavin zur Frau. Abram lebte damals schon zehn Jahre im Land Kanaan." },
      { number: 4, text: "Er schlief mit Hagar, und sie wurde schwanger. Als sie merkte, dass sie schwanger war, begann sie, auf ihre Herrin herabzusehen." },
      { number: 5, text: "Da sagte Sarai zu Abram: \"Du sollst das Unrecht tragen, das mir geschieht! Ich habe dir meine Sklavin überlassen. Kaum merkt sie, dass sie schwanger ist, verachtet sie mich. Jahwe richte zwischen dir und mir!*\"", footnotes: ["richte zwischen dir und mir. Ein Ausdruck von Feindschaft oder Misstrauen."] },
      { number: 6, text: "Abram erwiderte: \"Hier ist deine Sklavin. Mach mit ihr, was du willst!\" Da behandelte Sarai sie so hart, dass sie ihr davonlief." },
      { number: 7, text: "Doch der Engel Jahwes* fand sie an einer Wasserstelle in der Wüste, bei dem Brunnen, der am Weg nach Schur* liegt,", footnotes: ["Engel Jahwes. Hebräisch Malach Jahwe. Das war kein gewöhnlicher Engel, sondern eine Erscheinung Gottes.", "Die Wüste Schur liegt zwischen dem \"Bach Ägyptens\" und dem heutigen Suez-Kanal. Der Ort Schur war eventuell das heutige Tell Fara, ein Vorposten der Ägypter. Hagar war also auf dem Weg nach Ägypten."] },
      { number: 8, text: "und fragte sie: \"Hagar, Sklavin Sarais! Wo kommst du her, und wo willst du hin?\" – \"Ich bin meiner Herrin davongelaufen\", erwiderte sie." },
      { number: 9, text: "Da sagte der Engel Jahwes zu ihr: \"Geh zu deiner Herrin zurück und ertrage ihre harte Behandlung!" },
      { number: 10, text: "Ich werde dir so viele Nachkommen schenken, dass man sie nicht mehr zählen kann.\"" },
      { number: 11, text: "Dann fügte er hinzu: \"Du bist schwanger und wirst einen Sohn bekommen, den du Ismaël, 'Gott hört', nennen sollst, denn Jahwe hat dein Jammern gehört." },
      { number: 12, text: "Er wird ein Wildesel von Mann sein, im Streit mit allen und von allen bekämpft. Und er wird seinen Brüdern auf der Nase herumtanzen.\"" },
      { number: 13, text: "Da rief Hagar den Namen Jahwes an, der mit ihr geredet hatte. \"Du bist der Gott des Schauens!\", sagte sie und rief: \"Habe ich denn wirklich dem nachgeschaut, der nach mir schaute?\"" },
      { number: 14, text: "Darum nennt man den Brunnen jetzt Beer-Lahai-Roi, 'Brunnen des Lebendigen, der nach mir schaut'. Er liegt zwischen Kadesch und Bered." },
      { number: 15, text: "Hagar gebar Abram einen Sohn und Abram nannte ihn Ismaël." },
      { number: 16, text: "Abram war damals 86 Jahre alt." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Als Abram 99 Jahre alt war, erschien ihm Jahwe und sagte: \"Ich bin El-Schaddai, 'Gott, der Allmächtige', geh deinen Weg vor mir und halte dich ganz an mich!", heading: "Gottes Bund mit Abraham" },
      { number: 2, text: "Ich schließe meinen Bund mit dir und werde dir unermesslich viele Nachkommen geben.\"" },
      { number: 3, text: "Da warf sich Abram vor Gott nieder mit dem Gesicht auf die Erde, und Gott sagte zu ihm:" },
      { number: 4, text: "\"Pass auf! Mein Bund sieht so aus: Du wirst zum Vater vieler Völker werden." },
      { number: 5, text: "Deshalb sollst du auch nicht mehr Abram* heißen, sondern Abraham*! Denn ich habe dich zum Vater vieler Völker bestimmt.*", footnotes: ["Abram heißt: Gott, der Vater, ist erhaben. Es war ein Bekenntnis von Abrams Eltern zu Gott.", "Abraham heißt: Vater einer großen Menge. Das war ein Bekenntnis Gottes zu Abraham.", "Wird im Neuen Testament von Paulus zitiert: Römer 4,17."] },
      { number: 6, text: "Ich werde dich überaus fruchtbar machen, sodass deine Nachkommen zu ganzen Völkern werden. Selbst Könige werden von dir abstammen." },
      { number: 7, text: "Ich richte meinen Bund zwischen mir und dir und deinen Nachkommen* auf durch alle Generationen hindurch, einen ewigen Bund, um dein und deiner Nachkommen Gott zu sein.", footnotes: ["deinen Nachkommen. Wörtlich: deinem Samen (Singular). Wird im Neuen Testament von Paulus zitiert: Galater 3,16."] },
      { number: 8, text: "Ich werde euch das ganze Land Kanaan geben, in dem du jetzt als Fremder lebst. Es wird deinen Nachkommen für immer gehören. Und ich werde ihr Gott sein.\"" },
      { number: 9, text: "Weiter sagte Gott: \"Doch du, du sollst meinen Bund halten, du und deine Nachkommen, durch alle Generationen hindurch!" },
      { number: 10, text: "Eure Verpflichtung mir gegenüber besteht darin, dass ihr jeden Mann und jeden eurer männlichen Nachkommen beschneiden müsst." },
      { number: 11, text: "Bei allen müsst ihr die Vorhaut am Geschlechtsteil entfernen. Das ist das Zeichen für den Bund zwischen mir und euch." },
      { number: 12, text: "Am achten Tag muss jeder männliche Neugeborene beschnitten werden. Das gilt auch für die Sklaven, die bei euch geboren werden oder die ihr von Fremden kauft, auch dann, wenn sie nicht zu deiner Nachkommenschaft gehören." },
      { number: 13, text: "Sie müssen unbedingt beschnitten werden! Ihr sollt das Zeichen meines Bundes am Körper tragen, denn mein Bund gilt für alle Zeit." },
      { number: 14, text: "Ein Unbeschnittener, ein Mann, bei dem die Vorhaut nicht entfernt wurde, muss von seinem Stammesverband beseitigt* werden. Er hat meinen Bund gebrochen.\"", footnotes: ["beseitigt. Entweder durch Verbannung oder Tod."] },
      { number: 15, text: "Dann sagte Gott zu Abraham: \"Sarai, deine Frau, sollst du nicht mehr Sarai nennen. Von jetzt an soll sie Sara heißen*.", footnotes: ["Sarai bedeutet \"meine Fürstin\", Sara \"Fürstin\", oder \"Prinzessin\", was offenbar eine umfassendere Bedeutung hat, denn von ihr würden Könige abstammen."] },
      { number: 16, text: "Ich werde sie segnen und dir einen Sohn von ihr schenken. Ich segne sie so, dass sie die Mutter ganzer Völker wird, selbst Könige werden von ihr stammen.\"" },
      { number: 17, text: "Da warf sich Abraham vor Gott nieder und lachte innerlich. Er dachte: \"Einem Hundertjährigen soll noch ein Sohn geboren werden, und eine Neunzigjährige soll noch ein Kind bekommen?\"" },
      { number: 18, text: "Dann sagte er zu Gott: \"Wenn nur Ismaël vor dir leben kann!\"" },
      { number: 19, text: "Aber Gott sagte: \"Nein, deine Frau Sara wird dir einen Sohn gebären, den du Isaak, Lacher, nennen sollst. Ihm und seinen Nachkommen gilt mein Bund für alle Zeiten." },
      { number: 20, text: "Doch auch wegen Ismaël habe ich dich erhört. Ich werde ihn segnen und fruchtbar machen, und er wird sehr viele Nachkommen haben. Zwölf Fürsten wird er zeugen, und ich mache ihn zum Vater eines großen Volkes." },
      { number: 21, text: "Aber meinen Bund richte ich mit Isaak auf, den Sara dir im nächsten Jahr um diese Zeit schenken wird.\"" },
      { number: 22, text: "Als Gott das Gespräch mit Abraham beendet hatte, fuhr er wieder in den Himmel auf." },
      { number: 23, text: "Noch am gleichen Tag beschnitt Abraham seinen Sohn Ismaël und alle Sklaven, die in seinem Haus geboren oder bei Fremden gekauft worden waren, wie Gott es ihm gesagt hatte." },
      { number: 24, text: "Auch er selbst ließ sich beschneiden. Damals war er 99 Jahre alt," },
      { number: 25, text: "und sein Sohn Ismaël war dreizehn." },
      { number: 26, text: "Abraham und Ismaël wurden also am gleichen Tag beschnitten" },
      { number: 27, text: "zusammen mit allen Männern, die zu Abrahams Haushalt gehörten." },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Dann erschien Jahwe Abraham bei den Terebinthen von Mamre, als dieser in der Mittagshitze gerade am Eingang seines Zeltes saß.", heading: "Jahwes Besuch bei Abraham" },
      { number: 2, text: "Abraham blickte hoch und sah auf einmal drei Männer vor sich stehen. Sofort sprang er auf, verneigte sich vor ihnen bis zur Erde" },
      { number: 3, text: "und sagte zu dem, der voranging: \"Mein Herr, wenn ich Gnade vor dir gefunden habe, dann geh doch nicht an deinem Diener vorüber!" },
      { number: 4, text: "Man wird gleich ein wenig Wasser bringen, damit ihr euch die Füße waschen könnt. Dann macht es euch bequem unter dem Baum." },
      { number: 5, text: "Ich hole inzwischen einen Bissen Brot, damit ihr euch stärken und dann euren Weg fortsetzen könnt. Wozu seid ihr sonst bei eurem Diener vorbeigekommen?\" – \"Tu, was du vorhast\", sagten die Männer." },
      { number: 6, text: "Da eilte Abraham zu Sara ins Zelt und rief: \"Schnell, drei Maß* vom feinsten Mehl! Mach Teig und back Fladenbrot*!\"", footnotes: ["drei Maß. Hebräisch: Sea. 1 Sea = 1/3 Epha = 7 Liter = 4 Kilogramm. Ein Maß Mehl wäre mehr als genug für alle gewesen.", "Fladenbrote wurden auf heißen Steinen gebacken, sie waren bis zu 1 Zentimeter dick und hatten einen Durchmesser von 20-30 Zentimeter."] },
      { number: 7, text: "Er lief weiter zum Vieh, suchte ein schönes, zartes Kalb heraus und befahl seinem Sklaven, es schnell zuzubereiten." },
      { number: 8, text: "Dann holte er saure und süße Milch, nahm das gekochte Fleisch und setzte alles seinen Gästen vor. Während sie aßen, stand er unter dem Baum und bediente sie." },
      { number: 9, text: "Dann fragten sie ihn: \"Wo ist deine Frau Sara?\" – \"Im Zelt\", erwiderte er." },
      { number: 10, text: "Da sagte Jahwe: \"Nächstes Jahr um diese Zeit komme ich wieder zu dir, dann wird deine Frau Sara einen Sohn haben.\"* Sara horchte am Zelteingang hinter Abraham.", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 9,9."] },
      { number: 11, text: "Beide waren damals schon alt, und Sara war lange über die Wechseljahre hinaus." },
      { number: 12, text: "Da lachte Sara innerlich und dachte: \"Jetzt, wo ich verwelkt bin, soll ich noch Liebeslust haben? Und mein Ehemann ist ja auch alt.\"" },
      { number: 13, text: "Da sagte Jahwe zu Abraham: \"Warum hat Sara denn gelacht und denkt: 'Soll ich alte Frau wirklich noch Mutter werden können?'" },
      { number: 14, text: "Sollte für Jahwe denn irgendetwas unmöglich sein? Nächstes Jahr, zur genannten Zeit, komme ich wieder, dann hat Sara einen Sohn.\"" },
      { number: 15, text: "\"Ich habe doch nicht gelacht\", leugnete Sara, denn sie hatte Angst bekommen. Aber er sagte: \"Doch, du hast gelacht.\"" },
      { number: 16, text: "Dann brachen die Männer auf. Abraham begleitete sie. Als sie die Ebene von Sodom unter sich liegen sahen,", heading: "Abraham bittet für Sodom" },
      { number: 17, text: "dachte Jahwe: \"Soll ich Abraham verheimlichen, was ich vorhabe?" },
      { number: 18, text: "Er soll doch der Vater eines großen und mächtigen Volkes werden, und durch ihn sollen alle Völker der Erde Segen empfangen.*", footnotes: ["Wird mit 1. Mose 12,3 im Neuen Testament von Paulus zitiert: Galater 3,8."] },
      { number: 19, text: "Denn mit ihm habe ich Verbindung aufgenommen, damit er seinen Söhnen und seinen weiteren Nachkommen aufträgt, den Geboten Jahwes zu folgen, das Recht zu achten und Gerechtigkeit zu üben. So kann Jahwe auch seine Zusage an ihn einlösen.\"" },
      { number: 20, text: "Jahwe sagte also: \"Schwere Klagen sind über Sodom und Gomorra zu mir gedrungen. Ihre Sünde ist offenbar gewaltig groß." },
      { number: 21, text: "Darum will ich hinabsteigen und sehen, ob ihr Tun wirklich dem Schreien entspricht, das zu mir gedrungen ist. Ich will wissen, ob es so ist oder nicht.\"" },
      { number: 22, text: "Da wandten sich die Männer ab und gingen nach Sodom, während Abraham noch bei Jahwe stehen blieb." },
      { number: 23, text: "Nun trat Abraham vor und sagte: \"Willst du wirklich den Gerechten mit dem Gottlosen umbringen?" },
      { number: 24, text: "Vielleicht gibt es 50 Gerechte in der Stadt. Willst du die mit umkommen lassen und den Ort nicht wegen der 50 verschonen?" },
      { number: 25, text: "Du kannst doch den Gerechten nicht mit dem Gottlosen töten und die einen nicht genauso wie die anderen behandeln! Das kannst du auf keinen Fall tun! Sollte sich der Richter der ganzen Welt nicht selbst an das Recht halten?\"" },
      { number: 26, text: "\"Wenn ich 50 Gerechte in der Stadt finde\", erwiderte Jahwe, \"werde ich ihretwegen dem ganzen Ort vergeben.\"" },
      { number: 27, text: "Da nahm Abraham wieder das Wort: \"Ich habe mich nun einmal vorgewagt, zu meinem Herrn zu reden, obwohl ich nur Staub und Asche bin." },
      { number: 28, text: "Vielleicht fehlen an den 50 Gerechten nur fünf. Willst du wegen dieser fünf die ganze Stadt vernichten?\" – \"Nein, ich werde sie nicht vernichten, wenn ich 45 dort finde\", erwiderte er." },
      { number: 29, text: "Abraham fuhr fort: \"Und wenn es nur 40 sind?\" – \"Dann verschone ich sie wegen der 40\", erwiderte er." },
      { number: 30, text: "\"Bitte, mein Herr\", sagte Abraham, \"werde nicht zornig, wenn ich weiterrede! Vielleicht finden sich nur 30?\" – \"Dann verschone ich sie wegen der 30.\"" },
      { number: 31, text: "Da fing er wieder an: \"Ich habe es nun einmal gewagt, zu meinem Herrn zu reden: Vielleicht finden sich 20 dort.\" – \"Auch wenn es nur 20 sind, vernichte ich sie nicht.\"" },
      { number: 32, text: "\"Bitte, werde nicht zornig, Herr!\", sagte Abraham. \"Ich will nur noch einmal reden: Vielleicht findet man auch nur zehn.\" – \"Ich verschone sie auch wegen der zehn\", antwortete Jahwe." },
      { number: 33, text: "Dann brach er das Gespräch ab und ging weg. Abraham kehrte nach Hause zurück." },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Am Abend trafen die beiden Gottesboten in Sodom ein. Lot saß gerade im Tor* der Stadt. Als er sie kommen sah, ging er ihnen entgegen und warf sich nieder mit dem Gesicht zur Erde.", heading: "Gottes Gericht über Sodom und Gomorra", footnotes: ["Der Platz im Tor ist der geräumige Durchgang der turmartigen Torbefestigungen und der anschließende Platz. Tagsüber wurde hier Markt gehalten und Recht gesprochen, abends trafen sich die Männer dort."] },
      { number: 2, text: "\"Meine Herren\", sagte er, \"ich bin euer Diener. Mein Haus steht euch offen. Ihr könnt eure Füße waschen und bei mir übernachten. Und morgen früh könnt ihr weiterziehen.\" – \"Nein, auf keinen Fall!\", erwiderten sie. \"Wir wollen hier auf dem Platz übernachten.\"" },
      { number: 3, text: "Er redete ihnen aber so lange zu, bis sie in sein Haus mitkamen. Dann machte er ihnen etwas zu essen und backte ungesäuertes Fladenbrot für sie. Nach der Mahlzeit" },
      { number: 4, text: "wollten sie sich gerade niederlegen, da kamen die Männer von Sodom herbei und umstellten das Haus. Es waren alle Männer der Stadt, alte und junge." },
      { number: 5, text: "Sie schrien nach Lot und riefen: \"Wo sind die Männer, die heute Abend zu dir gekommen sind? Los, gib sie heraus! Wir wollen es ihnen besorgen!\"*", footnotes: ["es ihnen besorgen. Die Männer Sodoms wollten ihre homosexuelle Gier befriedigen."] },
      { number: 6, text: "Da trat Lot vor die Tür und schloss sie hinter sich zu." },
      { number: 7, text: "\"Ach, meine Brüder!\", rief er. \"Tut doch nicht so etwas Böses!" },
      { number: 8, text: "Seht, ich habe zwei Töchter, die noch kein Mann berührt hat; die will ich zu euch herausbringen. Macht mit ihnen, was ihr wollt, aber tut diesen Männern nichts. Sie sind meine Gäste und stehen unter meinem Schutz.\"" },
      { number: 9, text: "Doch sie schrien: \"Weg mit dir! Da kommt dieser Fremde hierher und spielt sich schon als Richter auf! Pass mal auf, wir werden es mit dir noch schlimmer treiben, als mit denen!\" Sie fielen über Lot her und versuchten, die Tür aufzubrechen." },
      { number: 10, text: "Da zogen die beiden Männer Lot zurück ins Haus und verschlossen die Tür." },
      { number: 11, text: "Und all die Männer draußen schlugen sie mit Blindheit, sodass diese es schließlich aufgaben, den Eingang zu suchen." },
      { number: 12, text: "Die Männer sagten zu Lot: \"Hast du noch andere Verwandte hier – einen Schwiegersohn, Söhne, Töchter? Wer auch immer zu dir gehört, schaff sie aus der Stadt hinaus!" },
      { number: 13, text: "Denn wir werden diesen Ort vernichten. Dazu hat Jahwe uns nämlich geschickt, denn über seine Bewohner sind schwere Klagen vor ihn gekommen.\"" },
      { number: 14, text: "Da ging Lot zu seinen künftigen Schwiegersöhnen* und sagte: \"Schnell, ihr müsst diese Stadt verlassen! Jahwe wird den Ort vernichten!\" Aber sie nahmen ihn nicht ernst, sie dachten nur, er mache Spaß.", footnotes: ["künftige Schwiegersöhne. Die Sprachform lässt auch zu, hier an schon verheiratete Schwiegersöhne zu denken. Dann hätte Lot wenigstens vier Töchter gehabt."] },
      { number: 15, text: "Im Morgengrauen drängten die Männer Lot zur Eile: \"Schnell, nimm deine Frau und deine beiden Töchter hier, sonst wird die Schuld der Stadt auch euch umbringen!\"" },
      { number: 16, text: "Als er immer noch zögerte, packten die Männer Lot bei der Hand, dazu seine Frau und seine Töchter, und führten ihn aus dem Ort. Erst draußen ließen sie ihn wieder los, weil Jahwe ihn verschonen wollte." },
      { number: 17, text: "Als sie dann auf dem freien Feld waren, sagte er: \"Lauf, so schnell du kannst! Es geht um dein Leben! Bleib nicht stehen und schaue dich nicht um! Rette dich auf die Berge, sonst bist du verloren!\"" },
      { number: 18, text: "Aber Lot sagte: \"Ach nein, mein Herr!" },
      { number: 19, text: "Du warst so gnädig zu deinem Diener, und du hast mir die Gunst erwiesen, dass ich am Leben bleiben kann. Aber ich kann nicht auf die Berge fliehen, sonst erreicht mich das Unheil doch noch und ich müsste sterben." },
      { number: 20, text: "Sieh doch, diese Stadt ist ganz in der Nähe. Bis dahin könnten wir es schaffen, und sie ist ja nur so klein. Dürfen wir uns nicht dorthin retten, um am Leben zu bleiben? Es ist doch nur eine kleine Stadt.\"" },
      { number: 21, text: "\"Gut\", sagte er, \"auch das will ich dir gewähren. Ich vernichte die Stadt nicht." },
      { number: 22, text: "Schnell, rette dich dorthin! Denn ich kann nichts tun, bevor du da bist.\" Deshalb nennt man die Stadt Zoar*.", footnotes: ["Zoar bedeutet so viel wie \"Winzig\" und liegt etwa 8 km vom Süd-Ende des Toten Meeres entfernt in der Tiefebene. Zum Gebirge wäre es kaum weiter gewesen."] },
      { number: 23, text: "Die Sonne ging gerade auf, als Lot nach Zoar kam." },
      { number: 24, text: "Da ließ Jahwe Feuer und Schwefel auf Sodom und Gomorra regnen. Es kam von ihm, vom Himmel herab," },
      { number: 25, text: "und verwüstete die Städte und ihre ganze Umgebung. Alle Menschen dort kamen um, und alles, was auf den Feldern wuchs, wurde vernichtet." },
      { number: 26, text: "Lots Frau aber hatte sich hinter seinem Rücken umgeschaut und war zu einer Salzsäule erstarrt." },
      { number: 27, text: "Früh am nächsten Morgen ging Abraham wieder an die Stelle, wo er vor Jahwe gestanden hatte," },
      { number: 28, text: "und schaute auf die Tiefebene mit Sodom und Gomorra herab. Da sah er eine Rauchwolke vom Land aufsteigen wie von einem Schmelzofen." },
      { number: 29, text: "Aber Gott hatte an Abraham gedacht, als er die Städte in der Ebene vernichtete. Er sorgte dafür, dass Lot, der mitten in diesen Städten gewohnt hatte, der Katastrophe entging." },
      { number: 30, text: "Aber Lot hatte Angst, in Zoar zu bleiben. Deshalb zog er mit seinen beiden Töchtern ins Gebirge und wohnte in einer Höhle.", heading: "Lot und seine Töchter" },
      { number: 31, text: "Eines Tages sagte die ältere Tochter zur jüngeren: \"Unser Vater ist alt, und es gibt weit und breit keinen Mann, der mit uns schlafen könnte, wie es überall gemacht wird." },
      { number: 32, text: "Komm, wir geben unserem Vater Wein zu trinken und legen uns dann zu ihm, damit wir von ihm Kinder bekommen.\"" },
      { number: 33, text: "Noch am selben Abend machten sie ihren Vater betrunken. Dann legte sich die Ältere zu ihm. Doch ihr Vater merkte nichts davon, weder wie sie zu ihm kam noch wie sie von ihm aufstand." },
      { number: 34, text: "Am Morgen sagte sie zu ihrer Schwester: \"Siehst du, ich habe heute Nacht mit unserem Vater geschlafen. Wir wollen ihn auch heute Abend mit Wein betrunken machen, und dann legst du dich zu ihm, damit wir von ihm Kinder bekommen.\"" },
      { number: 35, text: "Am Abend machten sie ihren Vater wieder betrunken. Dann legte sich die Jüngere zu ihm. Doch ihr Vater merkte wieder nichts davon, weder wie sie zu ihm kam noch wie sie von ihm aufstand." },
      { number: 36, text: "So wurden die beiden Töchter Lots von ihrem eigenen Vater schwanger." },
      { number: 37, text: "Die Ältere bekam einen Sohn und nannte ihn Moab, \"Vom Vater\". Er gilt bis heute als der Stammvater der Moabiter." },
      { number: 38, text: "Als auch die Jüngere einen Sohn bekam, nannte sie ihn Ben-Ammi, \"Sohn meiner Leute\". Er gilt bis heute als der Stammvater der Ammoniter." },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Abraham brach nun von Mamre auf und zog weiter in den Negev. Er schlug sein Lager zwischen Kadesch und Schur* auf und lebte dann eine Zeitlang in Gerar*.", heading: "Abraham bei Abimelech", footnotes: ["Kadesch und Schur. Vergleiche die Anmerkungen zu Kapitel 14,7 und 16,7.", "Gerar liegt in der Nähe von Gaza, 27 km nordwestlich von Beerscheba."] },
      { number: 2, text: "Dort gab er seine Frau Sara wieder als seine Schwester aus. Da ließ Abimelech*, der König von Gerar, Sara zu sich holen.", footnotes: ["Abimelech heißt \"mein Vater ist König\". Das war der Titel vieler kanaanäischer Stadtkönige."] },
      { number: 3, text: "Aber in der Nacht kam Gott im Traum zu Abimelech und sagte: \"Du musst sterben, weil du diese Frau genommen hast, denn sie ist verheiratet und gehört einem anderen.\"" },
      { number: 4, text: "Abimelech hatte sie noch nicht berührt und erwiderte: \"Herr, willst du denn unschuldige Leute umbringen?" },
      { number: 5, text: "Er hat doch selbst zu mir gesagt: 'Sie ist meine Schwester.' Und auch sie hat das bestätigt und mir gesagt: 'Er ist mein Bruder.' Ich habe das mit reinem Gewissen und unschuldigen Händen getan.\"" },
      { number: 6, text: "\"Das weiß ich auch\", sagte Gott im Traum zu ihm. \"Ja, du hast das mit reinem Gewissen getan. Deshalb habe ich dich auch davon abgehalten, vor mir schuldig zu werden, und dir nicht gestattet, sie zu berühren." },
      { number: 7, text: "Doch jetzt gib die Frau dem Mann zurück! Er ist nämlich ein Prophet und wird für dich beten, damit du am Leben bleibst. Wenn du sie aber behältst, wirst du sterben, du und alles, was zu dir gehört.\"" },
      { number: 8, text: "Am nächsten Morgen stand Abimelech früh auf, rief seine Leute zusammen und berichtete ihnen, was geschehen war. Da bekamen es alle mit der Angst zu tun." },
      { number: 9, text: "Abimelech ließ Abraham rufen und sagte zu ihm: \"Was hast du uns da angetan? Womit habe ich mich an dir versündigt, dass du mich und mein Volk in diese schwere Schuld gestürzt hast? Du hast mir etwas angetan, was man einfach nicht tun darf!" },
      { number: 10, text: "Was hast du dir dabei nur gedacht?\"" },
      { number: 11, text: "Abraham entgegnete: \"Ich dachte, an diesem Ort hat man bestimmt keine Ehrfurcht vor Gott, und man wird mich umbringen wegen meiner Frau." },
      { number: 12, text: "Außerdem ist sie wirklich meine Schwester. Sie ist die Tochter meines Vaters, hat aber eine andere Mutter. Darum konnte ich sie heiraten." },
      { number: 13, text: "Als Gott mich dann aus meiner Heimat in die Fremde schickte, sagte ich zu ihr: 'Tu mir den Gefallen und gib mich überall, wo wir hinkommen, als deinen Bruder aus!'\"" },
      { number: 14, text: "Da machte Abimelech Abraham ein Geschenk und ließ Kleinvieh, Rinder, Sklaven und Sklavinnen zu ihm bringen. Auch seine Frau Sara gab er ihm zurück." },
      { number: 15, text: "Dabei sagte er: \"Mein ganzes Land steht dir offen. Du kannst dich niederlassen, wo es dir gefällt.\"" },
      { number: 16, text: "Und an Sara gewandt, sagte er: \"Ich gebe deinem Bruder 1000 Silberstücke. Damit sei vor allen Leuten bestätigt, dass deine Ehre nicht angetastet worden ist und niemand dir etwas nachsagen kann.\"" },
      { number: 17, text: "Nun betete Abraham zu Gott. Daraufhin nahm Gott die Strafe von Abimelech, seiner Frau und allen seinen Sklavinnen weg, dass sie wieder Kinder bekommen konnten." },
      { number: 18, text: "Denn wegen Abrahams Frau Sara hatte Jahwe im ganzen Haushalt Abimelechs jeden Mutterleib verschlossen." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Jahwe dachte an Sara und tat an ihr, was er zugesagt hatte.", heading: "Das Leben Isaaks (21-26)\nDie Geburt Isaaks" },
      { number: 2, text: "Sie wurde schwanger und gebar Abraham in seinem Alter noch einen Sohn. Es war genau zu der Zeit, die Gott angegeben hatte." },
      { number: 3, text: "Abraham nannte den Sohn, den Sara ihm geboren hatte, Isaak." },
      { number: 4, text: "Als sein Sohn acht Tage alt geworden war, beschnitt Abraham ihn, wie Gott es angeordnet hatte." },
      { number: 5, text: "Hundert Jahre alt war er bei der Geburt Isaaks." },
      { number: 6, text: "Sara sagte: \"Gott hat mir ein Lachen geschenkt! Jeder, der es hört, wird mit mir lachen." },
      { number: 7, text: "Wer hätte Abraham je zugeraunt: 'Sara wird ein Söhnchen stillen!' Und doch habe ich ihm in seinem Alter noch einen Sohn geboren!\"" },
      { number: 8, text: "Das Kind wuchs heran. Als es von der Mutterbrust entwöhnt wurde, feierte Abraham ein großes Fest." },
      { number: 9, text: "Eines Tages bemerkte Sara, wie Ismaël, der Sohn der Ägypterin Hagar, den diese Abraham geboren hatte, herumtollte.", heading: "Hagar und Ismaël müssen fort" },
      { number: 10, text: "Da sagte sie zu Abraham: \"Jag mir die Sklavin und ihren Sohn weg! Der Sohn dieser Sklavin darf nicht gemeinsam mit meinem Sohn Isaak das Erbe antreten!\"*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Galater 4,30."] },
      { number: 11, text: "Abraham missfiel das sehr, denn Ismaël war sein Sohn." },
      { number: 12, text: "Aber Gott sagte zu ihm: \"Gräm dich nicht wegen des Jungen und wegen deiner Sklavin. Hör auf alles, was Sara dir sagt! Denn Isaaks Nachkommen werden dein genannt werden.*", footnotes: ["Wird im Neuen Testament von Paulus und im Hebräerbrief zitiert: Römer 9,7; Hebräer 11,18."] },
      { number: 13, text: "Doch auch den Sohn der Sklavin mache ich zu einem Volk, weil er von dir abstammt.\"" },
      { number: 14, text: "Am frühen Morgen stand Abraham auf, nahm Brot und einen Schlauch mit Wasser, packte Hagar alles auf die Schulter, übergab ihr das Kind und schickte sie fort. Hagar ging weg, doch verirrte sie sich in der Wüste von Beerscheba*.", footnotes: ["Beerscheba wurde später die wichtigste Stadt im Negev und liegt etwa 40 km südwestlich von Hebron."] },
      { number: 15, text: "Als ihnen das Wasser im Schlauch ausgegangen war, legte sie den Jungen unter einen Strauch" },
      { number: 16, text: "und setzte sich einen Bogenschuss weit entfernt auf die Erde. Denn sie sagte sich: \"Ich kann es nicht mit ansehen, wie der Junge stirbt!\" So saß sie ihm dort gegenüber und weinte." },
      { number: 17, text: "Aber Gott hörte den Jungen. Da rief der Engel Gottes Hagar vom Himmel aus zu: \"Was ist mit dir, Hagar? Hab keine Angst! Gott hat den Jungen gehört, wo er jetzt liegt." },
      { number: 18, text: "Steh auf und nimm ihn bei der Hand! Ich werde ihn zu einem großen Volk werden lassen.\"" },
      { number: 19, text: "Dann öffnete Gott ihr die Augen, und sie sah einen Wasserbrunnen. Da ging sie hin, füllte den Schlauch mit Wasser und gab dem Jungen zu trinken." },
      { number: 20, text: "Gott kümmerte sich auch weiter um ihn. Er wuchs in der Wüste heran und wurde ein Bogenschütze." },
      { number: 21, text: "Es war die Wüste Paran*, in der er lebte und wo seine Mutter ihm eine Ägypterin zur Frau gab.", footnotes: ["Die Wüste Paran hat man vermutlich in der nördlichen Sinaihalbinsel westlich der Araba zu suchen."] },
      { number: 22, text: "Um diese Zeit kam Abimelech mit seinem Heerführer Pichol zu Abraham und sagte zu ihm: \"Gott ist mit dir und lässt dir alles gelingen, was du tust.", heading: "Der Vertrag mit Abimelech" },
      { number: 23, text: "So schwöre mir jetzt bei Gott, dass du weder mich noch meine Kinder und Kindeskinder betrügen wirst. Ich habe dir nur Gutes erwiesen. Handle du ebenso an mir und dem Land, in dem du als Fremder lebst!\"" },
      { number: 24, text: "\"Ja, ich schwöre es\", sagte Abraham." },
      { number: 25, text: "Er beklagte sich aber bei Abimelech, dass dessen Leute ihm gewaltsam einen Brunnen weggenommen hatten." },
      { number: 26, text: "\"Ich weiß nicht, wer das war\", sagte Abimelech. \"Du hast mir bis heute nichts davon gesagt, und ich habe auch sonst noch nichts davon gehört.\"" },
      { number: 27, text: "Da übergab Abraham Abimelech eine Anzahl Kleinvieh und Rinder, und die beiden schlossen einen Bund." },
      { number: 28, text: "Abraham hatte aber noch sieben Schaflämmer aus seiner Herde ausgesondert." },
      { number: 29, text: "\"Was sollen diese sieben Lämmer?\", fragte Abimelech." },
      { number: 30, text: "Abraham erwiderte: \"Die musst du extra von mir annehmen, damit du auf diese Weise bestätigst, dass der Brunnen mir gehört.\"" },
      { number: 31, text: "Deshalb nennt man diesen Ort Beerscheba, 'Brunnen des Siebenschwurs', weil beide dort ihren Vertrag beschworen hatten." },
      { number: 32, text: "Nachdem sie so einen Bund in Beerscheba geschlossen hatten, kehrten Abimelech und sein Heerführer Pichol ins Land der Philister zurück." },
      { number: 33, text: "Abraham aber pflanzte eine Tamariske* und rief dort den Namen Jahwes, des ewigen Gottes, an.", footnotes: ["Die Tamariske ist ein reich verzweigter immergrüner Baum, der bis zu 10 Meter hoch wird. Er ist im Sandgebiet des Negev verbreitet."] },
      { number: 34, text: "Er hielt sich noch lange als Fremder im Land der Philister auf." },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Einige Zeit danach* stellte Gott Abraham auf die Probe. \"Abraham\", sagte er zu ihm. \"Ja?\", antwortete er.", heading: "Abrahams Opfergang", footnotes: ["Zeit danach. Nach biblischer Chronologie (Erklärungen im Vorwort zur Bibel) wurde Isaak im Jahr 2066 v.Chr. geboren, als Abraham 100 Jahre alt war (1. Mose 21,5). Frühestmöglicher Zeitpunkt von Abrahams Opfergang wäre 2057 v.Chr. (Isaak neun Jahre alt), spätestmöglicher das Todesjahr Saras 2029 v.Chr. (Isaak 37 Jahre alt)."] },
      { number: 2, text: "\"Nimm deinen Sohn, deinen einzigen, den du lieb hast, den Isaak! Zieh ins Land Morija und opfere ihn als Brandopfer auf dem Berg, den ich dir zeigen werde!\"*", footnotes: ["Berg. Nach 2. Chronik 3,1 ist das der Tempelberg in Jerusalem. Das Land Morija meint dann die Gegend um den Berg herum. Der Berg lag damals außerhalb der alten Jebusiterstadt."] },
      { number: 3, text: "Am nächsten Morgen stand Abraham früh auf. Er spaltete Holz für das Brandopfer und sattelte seinen Esel. Dann nahm er zwei seiner Leute und seinen Sohn Isaak und machte sich mit ihnen auf den Weg zu dem Ort, den Gott ihm genannt hatte." },
      { number: 4, text: "Am dritten Tag erblickte er den Berg aus der Ferne." },
      { number: 5, text: "Da sagte er zu seinen Leuten: \"Ihr bleibt mit dem Esel hier! Ich werde mit dem Jungen dort hinaufgehen, um anzubeten. Dann kommen wir wieder zurück.\"" },
      { number: 6, text: "Abraham lud seinem Sohn die Holzscheite auf den Rücken. Er selbst nahm den Topf mit den glühenden Kohlen und das Messer. So gingen beide miteinander." },
      { number: 7, text: "Da sagte Isaak: \"Vater!\" – \"Ja, mein Sohn?\" – \"Schau, wir haben Feuer und Holz. Aber wo ist das Lamm zum Brandopfer?\"" },
      { number: 8, text: "\"Gott wird schon für ein Lamm sorgen, mein Sohn.\" So gingen beide miteinander." },
      { number: 9, text: "Als sie die Stelle erreichten, die Gott ihm genannt hatte, baute Abraham den Altar. Dann schichtete er das Holz auf, fesselte seinen Sohn Isaak und legte ihn auf den Altar, oben auf das Holz." },
      { number: 10, text: "Und dann griff er nach dem Messer, um seinen Sohn zu schlachten." },
      { number: 11, text: "Da rief der Engel Jahwes vom Himmel her: \"Abraham! Abraham!\" – \"Ja?\", erwiderte er." },
      { number: 12, text: "\"Halt ein! Tu dem Jungen nichts zuleide! Jetzt weiß ich, dass du Gott gehorchst, denn du hast mir deinen einzigen Sohn nicht verweigert.\"" },
      { number: 13, text: "Als Abraham dann aufblickte, sah er einen Schafbock, der sich mit seinen Hörnern im Gebüsch hinter ihm verfangen hatte. Abraham holte das Tier und opferte es anstelle seines Sohnes auf dem Altar." },
      { number: 14, text: "Abraham nannte den Ort \"Jahwe sorgt vor\". Noch heute sagt man: \"Auf dem Berg Jahwes ist vorgesorgt.\"" },
      { number: 15, text: "Noch einmal rief der Engel Jahwes Abraham vom Himmel herab zu:" },
      { number: 16, text: "\"Ich schwöre bei mir selbst, sagt Jahwe: Weil du das getan und mir deinen einzigen Sohn nicht verweigert hast," },
      { number: 17, text: "werde ich dich mit Segen überschütten und deine Nachkommen überaus zahlreich machen,* so wie die Sterne am Himmel und die Sandkörner* am Strand. Sie werden ihre Feinde besiegen und ihre Städte erobern.", footnotes: ["Wird im Neuen Testament zitiert: Hebräer 6,13-14.", "Sterne … Sandkörner. Die Zahl der Sterne, die man mit bloßem Auge erkennen kann, beträgt etwa 5000. Die Gesamtzahl der Sterne, die man prinzipiell mit modernen Teleskopen sichtbar machen kann, schätzt man heute auf 70 Trilliarden. Das entspricht der Zahl Sieben mit 22 Nullen. Die Zahl aller Sandkörner der Erde dürfte nach neueren Abschätzungen noch weit höher sein."] },
      { number: 18, text: "Und durch deinen Nachkommen werden alle Völker der Erde gesegnet sein,* weil du mir gehorcht hast.\"", footnotes: ["Wird im Neuen Testament von Petrus zitiert: Apostelgeschichte 3,25."] },
      { number: 19, text: "Abraham kehrte wieder zu seinen Leuten zurück, und sie gingen miteinander nach Beerscheba. Dort blieb Abraham wohnen." },
      { number: 20, text: "Einige Zeit später erhielt Abraham die Nachricht: \"Milka hat deinem Bruder Nahor Söhne geboren!\"", heading: "Die Nachkommen Nahors" },
      { number: 21, text: "Es waren Uz, sein Erstgeborener, dann Bus und Kemuël, von dem die Syrer abstammen," },
      { number: 22, text: "Kesed und Haso, Pildasch, Jidlaf und Betuël, der Vater von Rebekka." },
      { number: 23, text: "Diese acht Söhne hatte Milka Nahor, dem Bruder Abrahams, geboren." },
      { number: 24, text: "Auch von seiner Nebenfrau Rëuma hatte Nahor Kinder: Tebach, Gaham, Tahasch und Maacha." },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Sara wurde 127 Jahre alt,", heading: "Saras Tod und Begräbnis" },
      { number: 2, text: "dann starb sie* in Kirjat-Arba, dem späteren Hebron, im Land Kanaan. Abraham trauerte um sie und hielt die Totenklage.", footnotes: ["dann starb sie. Nach biblischer Chronologie 2029 v.Chr."] },
      { number: 3, text: "Dann ging er von seiner Toten weg und redete mit den Hetitern:" },
      { number: 4, text: "\"Ich bin ein Ausländer und lebe nur als Gast unter euch. Verkauft mir ein Stück Land als Grabstätte für meine Familie, dass ich meine Tote dort bestatten kann.\"" },
      { number: 5, text: "Die Hetiter erwiderten Abraham:" },
      { number: 6, text: "\"Hör uns an, Herr! Du bist ein Fürst Gottes unter uns. Bestatte deine Tote im vornehmsten unserer Gräber! Keiner von uns wird dir sein Grab verweigern, damit du deine Tote begraben kannst.\"" },
      { number: 7, text: "Da stand Abraham auf, verneigte sich vor den Leuten des Landes" },
      { number: 8, text: "und sagte: \"Wenn ihr also damit einverstanden seid, dass ich meine Tote hier bei euch bestatte, dann legt bitte bei Efron Ben-Zohar ein Wort für mich ein." },
      { number: 9, text: "Ich bitte ihn um die Höhle Machpela, die am Rand seines Grundbesitzes liegt. Ich bezahle ihm dafür, was er verlangt, damit ich ein Familiengrab unter euch bekomme.\"" },
      { number: 10, text: "Efron saß selbst unter den Hetitern, die sich im Tor ihrer Stadt versammelt hatten. In ihrer Gegenwart sagte er zu Abraham:" },
      { number: 11, text: "\"Nein, mein Herr, hör mir zu! Ich schenke dir das Grundstück und die Höhle! Hier vor meinen Landsleuten schenke ich sie dir, damit du deine Tote bestatten kannst!\"" },
      { number: 12, text: "Da verneigte sich Abraham vor den Leuten des Landes" },
      { number: 13, text: "und sagte in ihrer Gegenwart zu Efron: \"Bitte, hör mich doch an! Ich zahle dir den Preis für das Land. Nimm ihn von mir an, damit ich meine Tote dort bestatten kann.\"" },
      { number: 14, text: "Efron erwiderte:" },
      { number: 15, text: "\"Hör mich an, Herr! Was bedeutet schon ein Stück Land zwischen dir und mir, das 400 Silberstücke* wert ist? Du kannst deine Tote dort bestatten.\"", footnotes: ["400 Silberstücke. Das war ein sehr hoher Preis. Vergleiche 1. Könige 16,24; Jeremia 32,9!"] },
      { number: 16, text: "Abraham ging darauf ein und wog dem Efron die Menge Silber ab, von der dieser gesprochen hatte, 400 Silberstücke nach dem bei den Händlern üblichen Gewicht." },
      { number: 17, text: "So ging das Grundstück Efrons, das bei Machpela gegenüber von Mamre liegt, in den Besitz Abrahams über: die Höhle und das dazugehörende Land mit allen Bäumen darauf." },
      { number: 18, text: "Vor den Augen aller Männer, die im Tor versammelt waren, wurde es als Eigentum Abrahams bestätigt." },
      { number: 19, text: "Dort in der Höhle von Machpela gegenüber von Mamre bei Hebron im Land Kanaan begrub Abraham seine Frau Sara." },
      { number: 20, text: "So kam das Feld und die Höhle der Hetiter als Grabstätte für seine Familie in den Besitz Abrahams." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Abraham war inzwischen sehr alt geworden, und Jahwe hatte ihn in jeder Hinsicht gesegnet.", heading: "Eine Braut für Isaak" },
      { number: 2, text: "Da sagte Abraham zu seinem ältesten Diener, der alles verwaltete, was er besaß: \"Schwöre bei meiner Nachkommenschaft!*", footnotes: ["Schwöre ... Nachkommenschaft. Wörtlich: Lege deine Hand unter meine Hüfte. Das ist offenbar symbolisch gemeint – nicht als Berührung des Geschlechtsteils wie in heidnischen Fruchtbarkeitsriten. Solch eine Vorstellung ist dem Alten Testament fremd. Die Schwurgeste bestand in der erhobenen Hand, vergleiche 1. Mose 14,22."] },
      { number: 3, text: "Ich will dich schwören lassen bei Jahwe, dem Gott des Himmels und der Erde, dass du meinem Sohn keine Frau auswählst, die hier aus dem Land Kanaan stammt." },
      { number: 4, text: "Du sollst in meine Heimat gehen und dort unter meiner Verwandtschaft eine Frau für meinen Sohn Isaak suchen!\"" },
      { number: 5, text: "Der Diener erwiderte: \"Was soll ich aber tun, wenn die Frau mir nicht in dieses Land hier folgen will? Soll ich dann deinen Sohn in deine Heimat zurückbringen?\"" },
      { number: 6, text: "\"Auf keinen Fall!\", sagte Abraham. \"Mein Sohn soll niemals dorthin zurück!" },
      { number: 7, text: "Jahwe, der Gott des Himmels, der mich aus meiner Sippe und Heimat geholt, der mir geschworen hat, meinen Nachkommen* dieses Land hier zu geben, der wird seinen Engel vor dir herschicken, dass du eine Frau für meinen Sohn von dort holen kannst.", footnotes: ["meinen Nachkommen. Wörtlich: deinem Samen (Singular). Wird im Neuen Testament von Paulus zitiert: Galater 3,16."] },
      { number: 8, text: "Wenn die Frau dir nicht folgen will, bist du von dem Schwur frei. Aber meinen Sohn darfst du nicht dorthin zurückbringen!\"" },
      { number: 9, text: "Da schwor der Diener bei der Nachkommenschaft Abrahams, seines Herrn, so zu handeln." },
      { number: 10, text: "Dann nahm er zehn von den Kamelen seines Herrn und machte sich mit allerlei kostbaren Geschenken aus dem Besitz seines Herrn auf den Weg. Er reiste nach Mesopotamien in die Stadt Nahors." },
      { number: 11, text: "In der Nähe des Brunnens vor der Stadt ließ er die Kamele niederknien. Es war gegen Abend um die Zeit, wenn die Frauen zum Wasserholen herauskommen." },
      { number: 12, text: "Dann betete er: \"Jahwe, Gott meines Herrn Abraham, lass es mir doch heute gelingen und erfülle den Wunsch meines Herrn!" },
      { number: 13, text: "Du siehst, ich stehe hier an der Quelle und gleich kommen die jungen Frauen aus der Stadt, um Wasser zu holen." },
      { number: 14, text: "Dann will ich eine von ihnen bitten: 'Neige doch deinen Krug, dass ich trinken kann!' Wenn sie dann sagt: 'Trink nur! Ich will auch deine Kamele tränken!', dann lass es die sein, die du für deinen Diener Isaak bestimmt hast. Daran werde ich erkennen, dass du meinem Herrn gnädig bist.\"" },
      { number: 15, text: "Er hatte noch nicht zu Ende gebetet, als Rebekka mit einem Wasserkrug auf der Schulter aus der Stadt kam. Sie war die Tochter von Betuël und Enkelin von Milka, der Frau von Abrahams Bruder Nahor." },
      { number: 16, text: "Rebekka war sehr schön, eine unberührte junge Frau; noch hatte kein Mann mit ihr geschlafen. Sie stieg die Stufen zur Quelle hinunter, füllte ihren Krug und kam wieder herauf." },
      { number: 17, text: "Da lief der Diener ihr entgegen und sagte: \"Lass mich doch ein wenig Wasser aus deinem Krug schlürfen!\"" },
      { number: 18, text: "\"Trink nur, Herr!\", sagte sie, nahm den Krug von der Schulter in die Hand und ließ ihn trinken." },
      { number: 19, text: "Als er genug getrunken hatte, sagte sie: \"Ich will auch für deine Kamele schöpfen, bis sie ausreichend getränkt sind.\"" },
      { number: 20, text: "Schnell goss sie ihren Krug in die Tränkrinne aus und eilte zur Quelle zurück. Sie schöpfte so lange, bis alle Kamele genug hatten." },
      { number: 21, text: "Der Mann beobachtete sie, schwieg aber, um zu sehen, ob Jahwe seine Reise gelingen lassen würde." },
      { number: 22, text: "Als alle Kamele genug hatten, holte er einen kostbaren* goldenen Nasenring heraus, sowie zwei schwere* goldene Armreifen", footnotes: ["kostbaren. Wörtlich: von einem halben Schekel Gewicht, etwa 6 Gramm.", "schwere. Wörtlich: mit einem Gewicht von 10 Schekel, etwa 115 Gramm, wenn man von einem Schekelgewicht von 11,5 Gramm ausgeht."] },
      { number: 23, text: "und fragte sie: \"Wessen Tochter bist du? Und gibt es vielleicht im Haus deines Vaters einen Platz zum Übernachten für uns?\"" },
      { number: 24, text: "\"Ich bin die Tochter von Betuël\", erwiderte sie, \"den Milka dem Nahor geboren hat." },
      { number: 25, text: "Wir haben jede Menge Stroh und Futter und auch Platz zum Übernachten.\"" },
      { number: 26, text: "Da kniete sich der Mann hin, verbeugte sich vor Jahwe" },
      { number: 27, text: "und betete: \"Gepriesen sei Jahwe, der Gott meines Herrn Abraham! Er hat ihm seine Güte und Treue nicht entzogen, denn er hat mich zum Haus der Verwandten meines Herrn geführt.\"" },
      { number: 28, text: "Das Mädchen war inzwischen ins Haus ihrer Mutter gelaufen und hatte alles erzählt." },
      { number: 29, text: "Nun hatte Rebekka einen Bruder namens Laban. Der lief gleich zu dem Mann an die Quelle hinaus," },
      { number: 30, text: "denn er hatte den Nasenring und die Armreifen an seiner Schwester gesehen und gehört, was sie von ihm erzählt hatte. Als er hinauskam, stand der Mann tatsächlich noch bei den Kamelen an der Quelle." },
      { number: 31, text: "\"Komm herein zu uns!\", rief Laban. \"Du bist von Jahwe gesegnet. Warum bleibst du draußen? Ich habe schon alles herrichten lassen, und auch für die Kamele ist Platz!\"" },
      { number: 32, text: "Da ging der Mann mit ins Haus. Man sattelte die Kamele ab, gab ihnen Stroh und Futter und brachte ihm und seinen Männern Wasser, damit sie sich die Füße waschen konnten." },
      { number: 33, text: "Dann wurde ihm zu essen vorgesetzt. Doch er sagte: \"Ich will nicht essen, bevor ich meine Botschaft ausgerichtet habe.\" – \"Sprich!\", sagte Laban." },
      { number: 34, text: "Er begann: \"Ich bin Abrahams Diener." },
      { number: 35, text: "Jahwe hat meinen Herrn reich gesegnet und ihm ein großes Vermögen geschenkt. Er gab ihm Kleinvieh und Rinder, Silber und Gold, Sklaven und Sklavinnen, Kamele und Esel." },
      { number: 36, text: "Dazu hat Sara, die Frau meines Herrn, ihm noch im Alter einen Sohn geschenkt. Ihm hat er seinen ganzen Besitz vermacht." },
      { number: 37, text: "Nun hat mein Herr mich schwören lassen und mir aufgetragen: 'Du darfst meinem Sohn keine Frau auswählen, die hier aus dem Land Kanaan stammt," },
      { number: 38, text: "sondern du sollst zur Familie meines Vaters gehen und dort unter meiner Verwandtschaft eine Frau für meinen Sohn suchen!'" },
      { number: 39, text: "Als ich einwandte, dass die Frau mir vielleicht nicht folgen will," },
      { number: 40, text: "sagte er zu mir: 'Jahwe, vor dem ich lebe, wird seinen Engel mit dir schicken und deine Reise gelingen lassen, dass du eine Frau für meinen Sohn aus meiner Verwandtschaft, der Familie meines Vaters, holen kannst." },
      { number: 41, text: "Wenn meine Verwandten dir die Frau nicht geben, bist du von dem Schwur frei.'" },
      { number: 42, text: "So kam ich heute zu der Quelle und betete: 'Jahwe, Gott meines Herrn Abraham, lass doch meine Reise gelingen!" },
      { number: 43, text: "Du siehst, ich stehe hier an der Quelle, lass es doch bitte geschehen, dass die junge Frau, die herauskommt, um Wasser zu holen, und die ich um einen Schluck Wasser aus ihrem Krug bitte," },
      { number: 44, text: "dass sie dann sagt: 'Trink nur! Ich will auch deine Kamele tränken!', dass es die ist, die du für deinen Diener Isaak bestimmt hast." },
      { number: 45, text: "Ich hatte in meinem Herzen noch nicht zu Ende gebetet, als Rebekka mit einem Wasserkrug auf der Schulter herauskam, zur Quelle hinunterstieg und Wasser schöpfte. Da sagte ich zu ihr: 'Gib mir doch etwas zu trinken!'" },
      { number: 46, text: "Da nahm sie gleich den Krug von der Schulter und sagte: 'Trink nur, ich werde auch deine Kamele tränken!' Ich trank, und sie tränkte auch die Kamele." },
      { number: 47, text: "Als ich sie fragte, wessen Tochter sie sei, sagte sie: 'Ich bin die Tochter von Betuël, den Milka dem Nahor geboren hat.' Da legte ich den Ring an ihre Nase und die Reifen an ihre Arme." },
      { number: 48, text: "Dann kniete ich mich hin und verbeugte mich vor Jahwe. Ich dankte Jahwe, dem Gott meines Herrn Abraham, dass er mich in Treue den Weg geführt hat, dass ich die Tochter vom Bruder meines Herrn als Frau für seinen Sohn erbitten kann." },
      { number: 49, text: "Wenn ihr nun meinem Herrn Gunst und Vertrauen schenken wollt, sagt es mir! Und wenn nicht, sagt es mir auch! Dann werde ich anderswo suchen.\"" },
      { number: 50, text: "Da antworteten Laban und Betuël: \"Das hat Jahwe gefügt! Wir können weder Ja noch Nein dazu sagen." },
      { number: 51, text: "Hier ist Rebekka, nimm sie mit! Sie soll den Sohn deines Herrn heiraten, wie es Jahwe gefügt hat.\"" },
      { number: 52, text: "Als Abrahams Diener das hörte, warf er sich auf die Erde und huldigte Jahwe." },
      { number: 53, text: "Dann packte er Silber- und Goldschmuck aus, holte festliche Kleider hervor und schenkte alles Rebekka. Auch ihrem Bruder und ihrer Mutter gab er kostbare Geschenke." },
      { number: 54, text: "Dann aß und trank er zusammen mit seinen Männern, und sie legten sich schlafen.Am nächsten Morgen sagte Abrahams Diener: \"Lasst mich nun zu meinem Herrn zurückkehren!\"" },
      { number: 55, text: "Doch Rebekkas Bruder und ihre Mutter sagten: \"Lass das Mädchen doch noch zehn Tage oder so bei uns bleiben, dann mag sie mit dir gehen!\"" },
      { number: 56, text: "Doch er erwiderte: \"Haltet mich nicht auf, nachdem Jahwe meine Reise hat gelingen lassen. Lasst mich zu meinem Herrn zurückkehren!\"" },
      { number: 57, text: "Da sagten sie: \"Wir rufen das Mädchen und fragen sie selbst!\"" },
      { number: 58, text: "Sie riefen Rebekka und fragten: \"Willst du mit diesem Mann reisen?\" – \"Ja, das will ich\", erwiderte sie." },
      { number: 59, text: "So verabschiedeten sie ihre Schwester Rebekka mit ihrer Amme und den Diener Abrahams mit seinen Männern." },
      { number: 60, text: "Sie segneten Rebekka mit den Worten: \"Du, unsere Schwester, werde zu tausendmal Tausenden! Deine Nachkommen sollen siegreich sein und das Tor ihrer Feinde besetzen!\"" },
      { number: 61, text: "So brach Rebekka mit ihren Dienerinnen auf. Sie bestiegen die Kamele und folgten dem Mann. Der Diener nahm Rebekka mit und trat die Rückreise an." },
      { number: 62, text: "Isaak kam gerade von einem Gang zum Brunnen Lahai-Roi*, denn er wohnte zu dieser Zeit im Negev.", footnotes: ["Lahai-Roi. Vergleiche 1. Mose 16,14."] },
      { number: 63, text: "Am späten Nachmittag war er hinausgegangen, um mit seinen Gedanken allein zu sein. Da sah er auf einmal Kamele kommen." },
      { number: 64, text: "Auch Rebekka hatte Isaak erblickt. Sie glitt vom Kamel herab und fragte den Diener:" },
      { number: 65, text: "\"Wer ist der Mann, der uns dort entgegenkommt?\" – \"Das ist mein Herr\", erwiderte dieser. Da nahm sie den Schleier und verhüllte sich." },
      { number: 66, text: "Der Diener erzählte Isaak, wie alles gegangen war," },
      { number: 67, text: "und Isaak führte Rebekka ins Zelt seiner Mutter Sara. Er nahm sie zur Frau und gewann sie lieb und tröstete sich über den Verlust seiner Mutter." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Auch Abraham heiratete wieder. Seine Frau hieß Ketura.", heading: "Weitere Nachkommen Abrahams" },
      { number: 2, text: "Sie gebar ihm Simran, Jokschan, Medan, Midian, Jischbak und Schuach." },
      { number: 3, text: "Jokschan zeugte Saba und Dedan. Von Dedan stammen die Aschuriter, die Letuschiter und die Lëummiter ab." },
      { number: 4, text: "Midians Söhne waren Efa, Efer, Henoch, Abida und Eldaga. Sie alle waren Nachkommen von Ketura." },
      { number: 5, text: "Abraham hatte Isaak seinen ganzen Besitz vermacht." },
      { number: 6, text: "Den Söhnen seiner Nebenfrauen gab er eine Abfindung und schickte sie noch zu seinen Lebzeiten von Isaak weg, ostwärts ins Ostland." },
      { number: 7, text: "Abraham wurde 175 Jahre alt.", heading: "Abrahams Tod" },
      { number: 8, text: "Er starb* nach einem erfüllten Leben und wurde im Tod mit seinen Stammesgenossen vereint.", footnotes: ["starb. Nach biblischer Chronologie 1991 v.Chr."] },
      { number: 9, text: "Seine Söhne Isaak und Ismaël bestatteten ihn in der Höhle Machpela. Sie liegt auf dem Grundstück, das Efron Ben-Zohar gehört hatte, gegenüber von Mamre," },
      { number: 10, text: "das Abraham damals von den Hetitern gekauft hatte. Dort also sind Abraham und seine Frau Sara bestattet." },
      { number: 11, text: "Nach Abrahams Tod segnete Gott dessen Sohn Isaak, der sich beim Brunnen Lahai-Roi niedergelassen hatte." },
      { number: 12, text: "Es folgt das Verzeichnis der Nachkommen von Ismaël Ben-Abraham, den die ägyptische Sklavin Hagar Abraham geboren hatte,", heading: "Die Nachkommen Ismaëls" },
      { number: 13, text: "die Namen der Nachkommen Ismaëls nach ihrer Geschlechterfolge: Nebajot, der Erstgeborene, Kedar, Adbeel, Mibsam," },
      { number: 14, text: "Mischma, Duma, Massa," },
      { number: 15, text: "Hadad, Tema, Jetur, Nafisch und Kedma." },
      { number: 16, text: "Das sind die Söhne Ismaëls und ihre Namen in den Niederlassungen und Zeltlagern: Sie waren die Begründer von zwölf Stämmen." },
      { number: 17, text: "Ismaël starb im Alter von 137 Jahren und wurde im Tod mit seinen Stammesgenossen vereint." },
      { number: 18, text: "Sie schlugen ihre Zelte zwischen Hawila* und Schur auf, das östlich von Ägypten am Weg nach Assur liegt. So setzte er sich seinen Brüdern vor die Nase.", footnotes: ["Hawila. Wahrscheinlich irgendwo in Arabien."] },
      { number: 19, text: "Es folgt die Geschichte der Nachkommen von Isaak Ben-Abraham: Abraham war der Vater Isaaks.", heading: "Die Nachkommen Isaaks" },
      { number: 20, text: "Isaak war vierzig Jahre alt*, als er heiratete. Seine Frau hieß Rebekka und war die Tochter des Aramäers Betuël aus dem oberen Mesopotamien, die Schwester Labans.", footnotes: ["vierzig ... heiratete. Die Hochzeit Isaaks fand also drei Jahre nach Saras Tod 2026 v.Chr. statt."] },
      { number: 21, text: "Isaak betete eindringlich für seine Frau zu Jahwe, denn sie bekam keine Kinder. Jahwe erhörte ihn und Rebekka wurde schwanger." },
      { number: 22, text: "Als die Kinder in ihrem Bauch einander wegstießen, sagte sie: \"Wenn es so steht, warum bin ich dann schwanger geworden?\" Sie ging, um Jahwe zu befragen.*", footnotes: ["Jahwe befragen. Vielleicht ging sie zu Abraham, der zu dieser Zeit noch am Leben und auch ein Prophet war, vergleiche 1. Mose 20,7."] },
      { number: 23, text: "Jahwe sagte zu ihr:\"Zwei Völker trägst du jetzt in deinem Leib, / zwei Stämme scheiden sich in deinem Schoß, / ein Volk wird stärker als das andere sein, / und der Ältere wird dem Jüngeren dienen.\"*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 9,12."] },
      { number: 24, text: "Und tatsächlich! Als die Stunde der Geburt kam, brachte sie Zwillinge zur Welt." },
      { number: 25, text: "Der erste, der herauskam, war am ganzen Körper mit rötlichen Haaren bedeckt. Sie nannten ihn Esau, den Behaarten." },
      { number: 26, text: "Danach war sein Bruder herausgekommen, der Esau an der Ferse festhielt. Ihn nannten sie Jakob, den Fersenhalter. Bei ihrer Geburt war Isaak sechzig Jahre alt.*", footnotes: ["sechzig Jahre alt. Die Kinder werden 20 Jahre nach Isaaks Eheschließung 2006 v.Chr. geboren."] },
      { number: 27, text: "Die Kinder wuchsen heran. Esau wurde ein Jäger, ein Mann der freien Steppe. Jakob wurde ein gesitteter Mann, der bei den Zelten blieb." },
      { number: 28, text: "Ihr Vater Isaak hatte eine Vorliebe für Esau, weil er gern Wild aß. Jakob war der Liebling der Mutter." },
      { number: 29, text: "Eines Tages hatte Jakob ein Gericht gekocht, als Esau erschöpft nach Hause kam.", heading: "Esau verkauft sein Erstgeburtsrecht" },
      { number: 30, text: "\"Lass mich doch schnell etwas von dem Roten da hinunterschlingen\", rief Esau, \"dem roten Zeug da, ich bin ganz erschöpft!\" Deshalb nannte man ihn auch Edom, den Roten." },
      { number: 31, text: "Doch Jakob erwiderte: \"Nur wenn du mir dein Erstgeburtsrecht verkaufst!\"" },
      { number: 32, text: "\"Ich sterbe vor Hunger\", erwiderte Esau, \"was nützt mir da mein Erstgeburtsrecht!\"" },
      { number: 33, text: "\"Schwöre es mir!\", verlangte Jakob. Esau schwor es ihm und verkaufte so sein Erstgeburtsrecht an Jakob." },
      { number: 34, text: "Da gab Jakob Esau Brot und eine Schüssel gekochter Linsen. Esau aß und trank, stand auf und ging davon. So missachtete er sein Erstgeburtsrecht." },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Wieder einmal brach eine Hungersnot über das Land herein, wie schon damals zur Zeit Abrahams. Da zog Isaak nach Gerar zu Abimelech, dem Philisterkönig.", heading: "Isaak und Abimelech" },
      { number: 2, text: "Jahwe war ihm nämlich erschienen und hatte gesagt: \"Zieh nicht nach Ägypten, bleib in dem Land, das ich dir sage!" },
      { number: 3, text: "Lebe als Fremder in diesem Land, dann werde ich mit dir sein und dich segnen. Denn dir und deinen Nachkommen werde ich all diese Länder geben. Ich halte den Eid, den ich deinem Vater Abraham geschworen habe." },
      { number: 4, text: "Ich mache deine Nachkommen so zahlreich wie die Sterne am Himmel und gebe ihnen all diese Länder. Und durch deine Nachkommen werden alle Völker der Erde gesegnet sein," },
      { number: 5, text: "weil Abraham auf mich gehört und meine Befehle, Gebote und Weisungen befolgt hat.\"" },
      { number: 6, text: "So blieb Isaak in Gerar." },
      { number: 7, text: "Als nun die Männer am Ort sich nach seiner Frau erkundigten, sagte er: \"Sie ist meine Schwester\", denn er dachte: \"Die Männer hier werden mich wegen Rebekka umbringen, sie ist ja so schön.\"" },
      { number: 8, text: "Als er schon längere Zeit dort war, schaute der Philisterkönig Abimelech einmal aus dem Fenster und sah, wie Isaak mit Rebekka schmuste." },
      { number: 9, text: "Da ließ er ihn zu sich rufen und sagte: \"Sie ist ja doch deine Frau! Wie konntest du nur sagen: 'Sie ist meine Schwester'?\" – \"Ich befürchtete, wegen ihr umgebracht zu werden\", erwiderte Isaak." },
      { number: 10, text: "\"Was hast du uns da angetan?\", rief Abimelech. \"Wie leicht hätte es geschehen können, dass einer meiner Leute mit ihr geschlafen hätte! Dann hättest du uns in schwere Schuld gestürzt!\"" },
      { number: 11, text: "Darauf ließ Abimelech dem ganzen Volk bekannt machen: \"Wer diesen Mann oder seine Frau antastet, wird in jedem Fall mit dem Tod bestraft.\"" },
      { number: 12, text: "Isaak säte in diesem Land Getreide aus und erntete in jenem Jahr das Hundertfache. So segnete Jahwe ihn." },
      { number: 13, text: "Sein Besitz vermehrte sich immer mehr, und er wurde ein sehr reicher Mann." },
      { number: 14, text: "Er hatte Kleinvieh- und Rinderherden und ein zahlreiches Gesinde. Da wurden die Philister neidisch auf ihn." },
      { number: 15, text: "Deshalb schütteten sie alle Brunnen zu,* die von den Leuten seines Vaters Abraham gegraben worden waren, und füllten sie mit Schutt.", footnotes: ["schütteten alle Brunnen zu. Das war in wasserarmen Gegenden eine der schwersten Verletzungen des Eigetumsrechts."] },
      { number: 16, text: "Und Abimelech sagte zu Isaak: \"Zieh von uns weg, denn du bist uns zu mächtig geworden!\"" },
      { number: 17, text: "Da verließ Isaak die Stadt und schlug sein Lager im Tal von Gerar auf." },
      { number: 18, text: "Danach legte er die Brunnen wieder frei, die zur Zeit seines Vaters Abraham gegraben worden waren und die die Philister nach dessen Tod zugeschüttet hatten. Er gab ihnen die gleichen Namen, die sein Vater ihnen gegeben hatte." },
      { number: 19, text: "Isaaks Leute gruben auch im Talgrund und stießen dabei auf Quellwasser." },
      { number: 20, text: "Doch die Hirten von Gerar fingen Streit mit den Hirten Isaaks an und erklärten: \"Das Wasser gehört uns!\" Deshalb nannte Isaak den Brunnen Esek, Zank, weil sie sich mit ihm herumgezankt hatten." },
      { number: 21, text: "Sie gruben einen anderen Brunnen; aber auch um den stritten sie. Da nannte er ihn Sitna, Anklage." },
      { number: 22, text: "Danach zog er von dort weiter und grub noch einen Brunnen. Um den gab es keinen Streit. Deshalb nannte Isaak ihn Rehobot, Weite, und sagte: \"Jetzt hat Jahwe uns freien Raum gegeben, dass wir uns im Land ausbreiten können.\"" },
      { number: 23, text: "Von dort zog er nach Beerscheba hinauf." },
      { number: 24, text: "In derselben Nacht erschien ihm Jahwe und sagte: \"Ich bin der Gott deines Vaters Abraham. Hab keine Angst, denn ich stehe dir bei! Wegen Abraham werde ich dich segnen und deine Nachkommenschaft zahlreich machen.\"" },
      { number: 25, text: "Isaak baute dort einen Altar und rief den Namen Jahwes an. Er schlug sein Lager in der Nähe auf, und seine Leute begannen, einen Brunnen zu graben." },
      { number: 26, text: "Da besuchte ihn Abimelech aus Gerar zusammen mit seinem Ratgeber Ahusat und seinem Heerführer Pichol." },
      { number: 27, text: "\"Warum kommt ihr zu mir?\", fragte Isaak sie. \"Ihr habt mich doch wie einen Feind behandelt und von euch fortgejagt!\"" },
      { number: 28, text: "\"Wir haben deutlich gesehen, dass Jahwe auf deiner Seite steht\", erwiderten sie. \"Deshalb haben wir uns gedacht: 'Es müsste eine eidliche Verpflichtung zwischen uns stehen!' Wir wollen einen Vertrag mit dir schließen," },
      { number: 29, text: "dass du uns keinen Schaden zufügst. Wir haben dir ja auch nichts zuleide getan; wir haben dir nur Gutes erwiesen und dich in Frieden ziehen lassen. Du bist nun einmal von Jahwe gesegnet.\"" },
      { number: 30, text: "Daraufhin ließ Isaak ihnen ein Mahl zubereiten, und sie aßen und tranken." },
      { number: 31, text: "Früh am nächsten Morgen leisteten sie einander den Schwur. Dann ließ Isaak sie in Frieden ziehen." },
      { number: 32, text: "Am selben Tag kamen seine Leute, die den Brunnen gegraben hatten, und meldeten: \"Wir haben Wasser gefunden!\"" },
      { number: 33, text: "Da nannte Isaak den Brunnen Schiba, Schwur. Deshalb heißt die Stadt bis heute Beerscheba, Schwurbrunnen." },
      { number: 34, text: "Als Esau vierzig Jahre alt war, heiratete er zwei Frauen: Jehudit, die Tochter des Hetiters Beeri, und Basemat, die Tochter des Hetiters Elon.", heading: "Esaus Frauen" },
      { number: 35, text: "Das war ein schwerer Kummer für Isaak und Rebekka." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Isaak war alt geworden und konnte nicht mehr sehen. Da rief er eines Tages seinen älteren Sohn Esau zu sich und sagte: \"Mein Sohn!\" – \"Ja, ich bin hier\", erwiderte dieser.", heading: "Das Leben Jakobs (27-36)\nDer Erstgeburtssegen" },
      { number: 2, text: "\"Ich bin alt geworden und weiß nicht, wie lange ich noch lebe." },
      { number: 3, text: "Nimm dein Jagdzeug, deinen Köcher und deinen Bogen und jage ein Stück Wild für mich." },
      { number: 4, text: "Dann mach mir einen Leckerbissen zurecht, wie ich ihn liebe, und bring ihn mir zum Essen herein, damit ich dich segne, bevor ich sterbe.\"" },
      { number: 5, text: "Rebekka hatte das Gespräch zwischen Isaak und seinem Sohn Esau mitgehört. Als Esau nun in die Steppe hinauszog, um ein Stück Wild für seinen Vater zu erjagen," },
      { number: 6, text: "sagte Rebekka zu ihrem Sohn Jakob: \"Pass auf! Ich habe gehört, wie dein Vater zu deinem Bruder Esau sagte:" },
      { number: 7, text: "'Bring mir ein Stück Wild und mach mir ein schmackhaftes Mahl, dass ich esse und dich dann vor Jahwe segne, bevor ich sterbe!'" },
      { number: 8, text: "Nun hör genau zu, mein Sohn, und tu, was ich dir sage!" },
      { number: 9, text: "Hol mir von der Herde zwei gute Ziegenböckchen! Ich werde einen Leckerbissen für deinen Vater daraus machen, so wie er es mag." },
      { number: 10, text: "Das bringst du ihm dann zum Essen, damit er dich vor seinem Tod segnet.\"" },
      { number: 11, text: "\"Aber Esau ist doch überall behaart, und ich habe eine glatte Haut\", erwiderte Jakob seiner Mutter." },
      { number: 12, text: "\"Vielleicht betastet mich mein Vater, dann würde ich als Betrüger vor ihm stehen und einen Fluch statt Segen auf mich bringen.\"" },
      { number: 13, text: "Doch seine Mutter erwiderte: \"Den Fluch nehme ich auf mich, mein Sohn. Tu nur, was ich dir gesagt habe!\"" },
      { number: 14, text: "Jakob holte die Böckchen und brachte sie seiner Mutter. Die machte einen Leckerbissen daraus, wie sein Vater ihn mochte." },
      { number: 15, text: "Dann nahm Rebekka die guten Kleider von Esau, ihrem Ältesten, die sie im Haus hatte, und zog sie ihrem jüngeren Sohn Jakob an." },
      { number: 16, text: "Mit den Fellen der Ziegenböckchen umwickelte sie seine Arme und seinen glatten Hals." },
      { number: 17, text: "Dann gab sie ihm das leckere Fleisch und das Brot, das sie frisch gebacken hatte." },
      { number: 18, text: "So ging er zu seinem Vater hinein und sagte: \"Vater!\" – \"Ja\", sagte Isaak, \"welcher von meinen Söhnen bist du?\"" },
      { number: 19, text: "\"Ich bin Esau, dein Erstgeborener\", erwiderte Jakob, \"ich habe gemacht, was du mir aufgetragen hast. Setz dich doch auf und iss von meinem Wild und segne mich nachher.\"" },
      { number: 20, text: "Doch Isaak fragte: \"Wie hast du so schnell etwas gefunden, mein Sohn?\" – \"Jahwe, dein Gott, hat es mir über den Weg laufen lassen\", erwiderte Jakob." },
      { number: 21, text: "Da sagte Isaak: \"Komm her, mein Sohn! Ich will fühlen, ob du wirklich mein Sohn Esau bist.\"" },
      { number: 22, text: "Jakob trat zu seinem Vater heran. Der betastete ihn und sagte: \"Die Stimme ist die von Jakob, aber die Hände sind die von Esau.\"" },
      { number: 23, text: "Er erkannte Jakob nicht, weil seine Hände behaart waren wie die von seinem Bruder Esau. Und so segnete er ihn." },
      { number: 24, text: "Er fragte noch einmal: \"Bist du wirklich mein Sohn Esau?\" – \"Ja, der bin ich\", erwiderte Jakob." },
      { number: 25, text: "Dann reich es mir her!\", sagte Isaak. \"Ich will vom Wild meines Sohnes essen und ihn dann segnen.\" Jakob reichte es ihm und Isaak aß. Dann brachte er ihm Wein und er trank." },
      { number: 26, text: "\"Darauf sagte Isaak: \"Komm her und küss mich, mein Sohn!\"" },
      { number: 27, text: "Als Jakob nun herantrat und ihn küsste, roch er den Duft seiner Gewänder. Da segnete er ihn. Er sagte:\"Ja, der Duft meines Sohnes / ist wie der Duft eines Feldes, / das Jahwe gesegnet hat." },
      { number: 28, text: "So gebe dir Gott / vom Tau des Himmels / und vom Fett des Erdbodens / Korn und Most im Überfluss." },
      { number: 29, text: "Nationen sollen dir dienen / und Völker sich vor dir verneigen. / Du wirst der Herr über deine Brüder sein! / Die Söhne deiner Mutter müssen sich beugen vor dir! / Wer dir flucht, der sei verflucht, / wer dich segnet, soll gesegnet sein!\"" },
      { number: 30, text: "Als Isaak den Segen über Jakob zu Ende gesprochen hatte und Jakob eben von seinem Vater weggegangen war, kam sein Bruder Esau von der Jagd." },
      { number: 31, text: "Auch er bereitete ein leckeres Mahl, brachte es zu seinem Vater und sagte: \"Mein Vater, setz dich auf und iss von meinem Wild, damit du mich segnen kannst!\"" },
      { number: 32, text: "\"Wer bist denn du?\", sagte Isaak zu ihm. \"Ich bin dein Sohn, dein Erstgeborener, Esau\", bekam er zur Antwort." },
      { number: 33, text: "Da erschrak Isaak sehr und begann heftig zu zittern. \"Wer war denn der, der das Wild gejagt und mir gebracht hat, bevor du kamst? Ich habe ihn gesegnet – und er wird auch gesegnet bleiben.\"" },
      { number: 34, text: "Als Esau das hörte, schrie er voller Bitterkeit laut auf. \"Vater\", rief er, \"segne mich, segne auch mich!\"" },
      { number: 35, text: "Aber Isaak erwiderte: \"Dein Bruder ist gekommen und hat dich mit Hinterlist um deinen Segen gebracht.\"" },
      { number: 36, text: "\"Heißt er deshalb Jakob, weil er mich nun schon zweimal betrogen* hat?\", sagte Esau. \"Erst nahm er mir das Erstgeburtsrecht und jetzt auch noch meinen Segen! Hast du denn keinen Segen mehr für mich übrig?\"", footnotes: ["betrogen. Hebräisch jaakob (Jakob), jaakebeni (betrügen, an der Ferse packen, hintergehen). Jedoch beim Erstgeburtsrecht hatte Jakob nicht betrogen. Siehe auch Hebräer 12,16!"] },
      { number: 37, text: "Isaak erwiderte: \"Ich habe ihn zum Herrn über dich gesetzt, und alle seine Brüder müssen ihm dienen. Mit Korn und Most habe ich ihn versehen. Was kann ich da noch für dich tun, mein Sohn?\"" },
      { number: 38, text: "Esau sagte: \"Hast du nur diesen einen Segen, mein Vater? Segne mich, segne auch mich, Vater!\" Und Esau fing an, laut zu weinen." },
      { number: 39, text: "Da sagte sein Vater Isaak:\"Fern vom Fett der Erde wird dein Wohnsitz sein, / fern vom Tau des Himmels oben." },
      { number: 40, text: "Von deinem Schwert wirst du dich ernähren / und wirst ein Diener deines Bruders sein. / Doch wenn du dich losreißt, / wirfst du sein Joch von deinen Schultern ab.\"" },
      { number: 41, text: "Esau feindete Jakob wegen des Segens an, den dieser von seinem Vater erhalten hatte. Er dachte: \"Mein Vater lebt nicht mehr lange. Wenn dann die Trauerzeit vorbei ist, werde ich meinen Bruder Jakob erschlagen.\"" },
      { number: 42, text: "Rebekka wurde zugetragen, dass ihr älterer Sohn solche Reden führte. Da ließ sie ihren jüngeren Sohn Jakob rufen und sagte zu ihm: \"Dein Bruder Esau will sich an dir rächen und dich erschlagen." },
      { number: 43, text: "Darum hör auf mich, mein Sohn! Flieh zu meinem Bruder Laban nach Haran" },
      { number: 44, text: "und bleib einige Zeit dort, bis sich der Zorn deines Bruders gelegt hat" },
      { number: 45, text: "und er nicht mehr wütend auf dich ist und vergisst, was du ihm angetan hast. Dann werde ich hinschicken und dich wieder holen lassen. Ich will euch doch nicht beide an einem Tag verlieren!\"" },
      { number: 46, text: "Und zu Isaak sagte Rebekka: \"Diese Hetiterinnen* verleiden mir das Leben. Wenn Jakob auch noch eine Frau aus dem Land hier nimmt, was soll mir dann noch mein Leben!\"", footnotes: ["Hetiterinnen. Vergleiche 1. Mose 26,34"] },
    ] },
    { number: 28, verses: [
      { number: 1, text: "Da ließ Isaak Jakob zu sich rufen. Er segnete ihn und sagte: \"Du darfst dir keine Frau aus dem Land Kanaan nehmen.", heading: "Jakobs Flucht nach Haran" },
      { number: 2, text: "Zieh ins obere Mesopotamien zur Sippe Betuëls, des Vaters deiner Mutter, und nimm dir eine Frau von den Töchtern Labans, des Bruders deiner Mutter." },
      { number: 3, text: "El-Schaddai, der allmächtige Gott, wird dich segnen. Er mache dich fruchtbar und lasse dich zahlreich werden, sodass aus dir eine ganze Schar von Völkern wird." },
      { number: 4, text: "Er gebe dir und deinen Nachkommen den Segen Abrahams, damit du das Land in Besitz nimmst, das Gott Abraham gegeben hat und in dem du jetzt noch als Fremder lebst!\"" },
      { number: 5, text: "So ließ Isaak Jakob ziehen, und dieser machte sich auf den Weg ins obere Mesopotamien zu Laban, dem Sohn des Aramäers Betuël, dem Bruder Rebekkas, seiner und Esaus Mutter." },
      { number: 6, text: "Als nun Esau erfuhr, dass Isaak Jakob gesegnet und ins obere Mesopotamien geschickt hatte, damit er sich dort eine Frau suche, und dass er ihm beim Segnen befohlen hatte: \"Du darfst dir keine Frau aus dem Land Kanaan nehmen!\"," },
      { number: 7, text: "und dass Jakob seinem Vater und seiner Mutter gehorcht hatte und bereits aufgebrochen war," },
      { number: 8, text: "da begriff Esau, dass die Frauen Kanaans seinem Vater zuwider waren." },
      { number: 9, text: "Er ging zu Ismaël und nahm zu seinen Frauen noch eine weitere hinzu, nämlich Mahalat, die Tochter Ismaëls, die Schwester Nebajots und Enkelin Abrahams." },
      { number: 10, text: "Jakob hatte sich von Beerscheba auf den Weg nach Haran gemacht." },
      { number: 11, text: "Dabei kam er an einen bestimmten Ort und übernachtete dort, weil die Sonne schon untergegangen war. Er nahm einen der Steine des Platzes, machte ihn zu seinem Kopflager und legte sich schlafen." },
      { number: 12, text: "Im Traum sah er einen Treppenaufgang*, dessen Spitze bis an den Himmel reichte. Engel stiegen auf ihm hinauf und herab.", footnotes: ["Treppenaufgang. Das hebräische Wort, das nur hier vorkommt, könnte am ehesten mit Aufschüttung übersetzt werden. Man sollte sich nicht eine Leiter mit Sprossen, sondern eher Stufen wie bei einem Zikkurat, einem Tempelturm, vorstellen."] },
      { number: 13, text: "Und auf einmal stand Jahwe über ihm und sagte: \"Ich bin Jahwe, der Gott deines Vaters Abraham und der Gott Isaaks. Das Land, auf dem du liegst, will ich dir und deinen Nachkommen geben." },
      { number: 14, text: "Deine Nachkommen werden zahlreich sein wie der Staub auf der Erde. Du wirst dich ausbreiten nach Westen und Osten, Norden und Süden. Durch dich und deine Nachkommenschaft sollen alle Sippen der Erde gesegnet werden." },
      { number: 15, text: "Und ich werde dir beistehen. Ich beschütze dich überall, wo du hingehst, und bringe dich wieder in dieses Land zurück. Ich werde dich nicht verlassen und tue alles, was ich dir versprochen habe.\"" },
      { number: 16, text: "Da erwachte Jakob und sagte: \"Tatsächlich, Jahwe ist an diesem Ort, und ich habe es nicht gewusst.\"" },
      { number: 17, text: "Er fürchtete sich und rief: \"Ehrfurcht gebietet dieser Ort! Hier ist wirklich das Haus Gottes, das Tor des Himmels.\"" },
      { number: 18, text: "Früh am Morgen stand Jakob auf. Er stellte den Stein, der an seinem Kopfende gelegen hatte, als Gedenkstein auf, goss Öl auf seine Spitze" },
      { number: 19, text: "und gab dem Ort den Namen Bet-El, Haus Gottes. Vorher hieß der Ort Lus." },
      { number: 20, text: "Dann legte Jakob ein Gelübde ab: \"Wenn Gott mir beisteht und mich auf meiner Reise behütet, wenn er mir Nahrung und Kleidung gibt" },
      { number: 21, text: "und ich wohlbehalten zu meiner Familie zurückkomme, dann soll Jahwe mein Gott sein." },
      { number: 22, text: "Und hier an dieser Stelle, wo ich den Stein aufgestellt habe, soll ein Haus Gottes stehen. Und von allem, was du mir gibst, werde ich dir treu den zehnten Teil zurückgeben.\"" },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Jakob setzte seine Wanderung fort und zog in das Land im Osten.", heading: "Jakob arbeitet um zwei Frauen" },
      { number: 2, text: "Eines Tages sah er einen Brunnen auf dem freien Feld. Drei Herden Schafe und Ziegen lagerten an ihm, denn aus diesem Brunnen tränkte man sie. Doch auf der Öffnung des Brunnens lag ein schwerer Stein." },
      { number: 3, text: "Die Hirten warteten, bis alle Herden beisammen waren, dann wälzten sie den Stein von der Öffnung, tränkten das Kleinvieh und brachten ihn dann wieder an seinen Platz." },
      { number: 4, text: "\"Meine Brüder, wo seid ihr her?\", fragte Jakob die Hirten. \"Wir sind von Haran\", erwiderten sie." },
      { number: 5, text: "\"Kennt ihr Laban Ben-Nahor?\", fragte er weiter. \"Gewiss\", sagten sie." },
      { number: 6, text: "\"Geht es ihm gut?\" – \"O ja\", antworteten sie. \"Da kommt gerade seine Tochter Rahel mit dem Kleinvieh.\"" },
      { number: 7, text: "Darauf sagte er: \"Aber es ist noch mitten am Tag und viel zu früh, die Herden zusammenzutreiben. Tränkt sie und lasst sie wieder weiden!\"" },
      { number: 8, text: "\"Das geht nicht\", erwiderten die Hirten, \"erst müssen die anderen Herden hier sein. Dann wälzen wir den Stein von der Brunnenöffnung und tränken die Tiere.\"" },
      { number: 9, text: "Während er noch mit ihnen redete, war Rahel schon mit dem Kleinvieh ihres Vaters herangekommen. Sie war nämlich Hirtin." },
      { number: 10, text: "Sobald Jakob Rahel, die Tochter Labans, des Bruders seiner Mutter, und dessen Herde sah, ging er zum Brunnen, wälzte den Stein von dessen Öffnung und tränkte die Tiere seines Onkels." },
      { number: 11, text: "Dann küsste er Rahel und weinte laut." },
      { number: 12, text: "Er sagte ihr, dass er der Neffe ihres Vaters und der Sohn Rebekkas sei. Da lief sie zu ihrem Vater und erzählte es ihm." },
      { number: 13, text: "Als Laban hörte, dass der Sohn seiner Schwester gekommen war, lief er ihm entgegen, umarmte und küsste ihn und führte ihn in sein Haus. Jakob erzählte ihm alles, was geschehen war." },
      { number: 14, text: "Da sagte Laban zu ihm: \"Ja, du bist wirklich mein Fleisch und Blut.\"Jakob war nun schon einen Monat bei ihm," },
      { number: 15, text: "da sagte Laban zu ihm: \"Du sollst nicht umsonst bei mir arbeiten, nur weil du mein Neffe bist. Was willst du als Lohn?\"" },
      { number: 16, text: "Nun hatte Laban zwei Töchter. Die ältere hieß Lea, die jüngere Rahel." },
      { number: 17, text: "Lea hatte ausdruckslose Augen, Rahel hatte eine schöne Gestalt und ein schönes Gesicht." },
      { number: 18, text: "Jakob liebte Rahel und sagte deshalb: \"Gib mir Rahel, deine jüngere Tochter, zur Frau. Dafür will ich sieben Jahre bei dir arbeiten.\"" },
      { number: 19, text: "Laban erwiderte: \"Es ist besser, ich gebe sie dir, als einem Fremden. Bleib also bei mir.\"" },
      { number: 20, text: "So arbeitete Jakob sieben Jahre für Rahel, und weil er sie liebte, kam ihm die Zeit wie ein paar Tage vor." },
      { number: 21, text: "Dann sagte er zu Laban: \"Gib mir nun meine Frau, denn meine Zeit ist um, und ich möchte sie heiraten.\"" },
      { number: 22, text: "Da lud Laban alle Leute des Ortes zur Hochzeitsfeier ein." },
      { number: 23, text: "Und am Abend führte er seine Tochter Lea* ins Brautgemach. Jakob schlief mit ihr.", footnotes: ["Lea. Die Verschleierung der Braut, die Dunkelheit der Nacht und vielleicht auch der getrunkene Wein ließen Jakob den Betrug nicht erkennen."] },
      { number: 24, text: "Als Dienerin hatte Laban ihr seine Sklavin Silpa mitgegeben." },
      { number: 25, text: "Am Morgen stellte Jakob aber fest, dass Lea neben ihm lag. Da stellte er Laban zur Rede: \"Was hast du mir da angetan? Ich habe doch um Rahel für dich gearbeitet! Warum hast du mich betrogen?\"" },
      { number: 26, text: "Laban erwiderte: \"Es ist hierzulande nicht üblich, die Jüngere vor der Älteren wegzugeben." },
      { number: 27, text: "Verbringe jetzt mit dieser die Hochzeitswoche, dann soll dir auch die andere gegeben werden. Dafür wirst du noch einmal sieben Jahre bei mir arbeiten.\"" },
      { number: 28, text: "Jakob ging darauf ein und vollendete die Hochzeitswoche mit Lea. Dann gab Laban ihm auch seine Tochter Rahel zur Frau." },
      { number: 29, text: "Und als Dienerin gab er Rahel seine Sklavin Bilha.*", footnotes: ["Sklavin Bilha. Die eine Sklavin war das mindeste, was eine Tochter erwarten konnte. Sie wurde mitgegeben, falls die Ehe kinderlos blieb."] },
      { number: 30, text: "Da schlief Jakob auch mit Rahel, und er hatte sie lieber als Lea. Dann arbeitete er noch einmal sieben Jahre für Laban." },
      { number: 31, text: "Als Jahwe sah, dass Lea ungeliebt war, machte er sie fruchtbar, während Rahel kinderlos blieb.", heading: "Jakobs Kinder" },
      { number: 32, text: "So wurde Lea schwanger. Sie bekam einen Sohn und sagte: \"Jahwe hat meinen Kummer gesehen, jetzt wird mein Mann mich lieben.\" Deshalb nannte sie ihn Ruben*.", footnotes: ["Ruben. Seht, ein Sohn! Der Name klingt aber auch an hebr. raa (sehen) und beonji (Kummer) an."] },
      { number: 33, text: "Danach wurde sie wieder schwanger und gebar einen zweiten Sohn. Sie sagte: \"Jahwe hat gehört, dass ich ungeliebt bin. So hat er mir auch den gegeben.\" Sie nannte ihn Simeon*.", footnotes: ["Simeon. Von hebr. schama (gehört) abgeleitet."] },
      { number: 34, text: "Wieder wurde sie schwanger und bekam einen Sohn. Da sagte sie: \"Jetzt endlich wird mein Mann sich mir anschließen, denn ich habe ihm drei Söhne geboren.\" Darum nannte sie ihn Levi*.", footnotes: ["Levi. Von hebr. jillawe (anschließen)."] },
      { number: 35, text: "Dann wurde sie noch einmal schwanger und bekam einen Sohn. \"Diesmal will ich Jahwe preisen!\", sagte sie. Darum gab sie ihm den Namen Juda*. Dann bekam sie lange Zeit keine Kinder mehr.", footnotes: ["Juda. Von hebr. ode (huldigen, preisen) abgeleitet."] },
    ] },
    { number: 30, verses: [
      { number: 1, text: "Als Rahel merkte, dass sie keine Kinder für Jakob bekommen konnte, wurde sie auf ihre Schwester eifersüchtig. \"Sorge dafür, dass ich Kinder bekomme!\", sagte sie zu Jakob. \"Wenn nicht, sterbe ich!\"" },
      { number: 2, text: "Da wurde Jakob zornig auf Rahel und sagte: \"Stehe ich etwa an Gottes Stelle, der dir Kinder versagt hat?\"" },
      { number: 3, text: "\"Dann gebe ich dir eben meine Sklavin Bilha. Geh zu ihr und mach sie schwanger! Wenn sie das Kind dann auf meinem Schoß zur Welt bringt, ist es wie mein eigenes.\"" },
      { number: 4, text: "So gab sie ihm ihre Sklavin Bilha zur Frau und er schlief mit ihr." },
      { number: 5, text: "Da wurde Bilha schwanger und gebar Jakob einen Sohn." },
      { number: 6, text: "Rahel sagte: \"Gott hat mir Recht verschafft, er hat meine Bitten gehört und mir einen Sohn geschenkt!\" Darum nannte sie ihn Dan*.", footnotes: ["Dan. Von hebr. dananni (Recht verschaffen) abgeleitet."] },
      { number: 7, text: "Darauf wurde Rahels Sklavin Bilha noch einmal schwanger und schenkte Jakob noch einen Sohn." },
      { number: 8, text: "Da sagte Rahel: \"Einen Gotteskampf habe ich mit meiner Schwester ausgefochten und habe auch gesiegt.\" Sie nannte ihn Naftali*.", footnotes: ["Naftali. Von hebr. naftule Kampf"] },
      { number: 9, text: "Als Lea dann merkte, dass sie keine Kinder mehr bekam, gab sie Jakob ihre Sklavin Silpa zur Frau." },
      { number: 10, text: "Auch Silpa schenkte Jakob einen Sohn." },
      { number: 11, text: "Da sagte Lea: \"Das Glück ist gekommen!\" und nannte ihn Gad, Glück." },
      { number: 12, text: "Als Silpa Jakob einen zweiten Sohn schenkte," },
      { number: 13, text: "sagte Lea: \"Ich Glückliche! Alle Frauen werden mich glücklich preisen!\" Darum nannte sie ihn Ascher*.", footnotes: ["Ascher. Von hebr. oschri (ich Glückliche) abgeleitet."] },
      { number: 14, text: "Zur Zeit der Weizenernte fand Ruben einmal Alraunfrüchte* auf dem Feld und brachte sie seiner Mutter Lea. Da bat Rahel ihre Schwester: \"Gib mir doch ein paar von den Liebesäpfeln, die dein Sohn gefunden hat!\"", footnotes: ["Alraunfrüchte. Die Frucht der Alraune ähnelt einem kleinen Apfel, riecht scharf und galt damals als Mittel zur Förderung der Fruchtbarkeit (\"Liebesapfel\")."] },
      { number: 15, text: "Aber Lea sagte zu ihr: \"Reicht es dir nicht, dass du mir meinen Mann weggenommen hast? Musst du auch noch die Liebesäpfel meines Sohnes haben?\" Rahel erwiderte: \"Wenn du sie mir gibst, soll er heute Nacht bei dir schlafen!\"" },
      { number: 16, text: "Als Jakob abends vom Feld kam, ging Lea ihm entgegen und sagte: \"Heute musst du mit mir schlafen, denn ich habe bezahlt. Ich habe dich mit den Liebesäpfeln meines Sohnes erkauft.\" Da schlief Jakob in dieser Nacht mit ihr;" },
      { number: 17, text: "und Gott erhörte Leas Bitte, sodass sie schwanger wurde und Jakob einen fünften Sohn schenkte." },
      { number: 18, text: "Sie sagte: \"Gott hat mich dafür belohnt, dass ich meine Sklavin meinem Mann gegeben habe.\" Darum nannte sie ihn Issachar, mein Lohn." },
      { number: 19, text: "Als Lea noch einmal schwanger wurde und Jakob einen sechsten Sohn schenkte," },
      { number: 20, text: "sagte sie: \"Gott hat mir ein schönes Geschenk gemacht; diesmal wird mein Mann mich annehmen, denn ich habe ihm sechs Söhne geboren.\" Deshalb gab sie ihm den Namen Sebulon*.", footnotes: ["Sebulon. Vielleicht von hebräisch jisbeleni (mich annehmen) abgeleitet. Die Übersetzung ist unsicher, weil der Begriff nur einmal in der Bibel vorkommt."] },
      { number: 21, text: "Danach gebar sie eine Tochter und gab ihr den Namen Dina." },
      { number: 22, text: "Nun dachte Gott aber auch an Rahel. Er erhörte sie und öffnete ihren Mutterschoß." },
      { number: 23, text: "Sie wurde daraufhin schwanger und brachte einen Sohn zur Welt. Da sagte sie: \"Gott hat meine Schande weggenommen.\"" },
      { number: 24, text: "Sie nannte ihn Josef* und sagte: \"Jahwe gebe mir noch einen anderen Sohn.\"", footnotes: ["Josef. Von hebr. josef (hinzufügen, nochmals tun)."] },
      { number: 26, text: "Gib mir meine Frauen und Kinder, für die ich bei dir gearbeitet habe und lass mich gehen! Du weißt ja selbst, was ich mit meiner Arbeit für dich geleistet habe.\"", heading: "Jakob kommt zu Vermögen" },
      { number: 27, text: "Aber Laban erwiderte: \"Könnte ich doch dein Wohlwollen finden und dich zum Bleiben bewegen! Durch Wahrsagung habe ich erfahren, dass Jahwe mich deinetwegen gesegnet hat." },
      { number: 28, text: "Was willst du als Lohn? Ich gebe dir, was du verlangst.\"" },
      { number: 29, text: "Jakob sagte: \"Du weißt ja, wie ich für dich geschuftet habe und was aus deinem Vieh bei mir geworden ist." },
      { number: 30, text: "Das wenige, das du vor meiner Zeit hattest, hat sich gewaltig vermehrt, und Jahwe hat dich bei jedem meiner Schritte gesegnet. Jetzt muss ich endlich für meine Familie sorgen!\"" },
      { number: 31, text: "Da fragte Laban: \"Was verlangst du als Lohn?\" – \"Du sollst mir gar nichts geben\", erwiderte Jakob, \"wenn du mir Folgendes zugestehst, werde ich auch weiterhin für dein Kleinvieh sorgen:" },
      { number: 32, text: "Ich will heute aus deinen Herden jedes dunkel gesprenkelte und gefleckte Schaf entfernen, sowie jede hell gefleckte und gesprenkelte Ziege*. Das soll mein Lohn sein!", footnotes: ["gesprenkelte Ziege. Schafe waren in der Regel weiß, Ziegen schwarzbraun, gesprenkelte und gefleckte Tiere selten."] },
      { number: 33, text: "Meine Redlichkeit wird für mich zeugen, wenn du morgen kommst, um meinen Lohn anzusehen: Alle Ziegen, die nicht hell gefleckt und gesprenkelt und alle Schaflämmer, die nicht braun sind, sollen als gestohlen gelten, wenn sie bei mir sind.\"" },
      { number: 34, text: "Da sagte Laban: \"Gut, es soll so sein, wie du gesagt hast.\"" },
      { number: 35, text: "Aber er suchte noch am selben Tag alle Ziegen und Ziegenböcke heraus, an denen etwas Helles, und alle Schafe, an denen etwas Dunkles war, und gab sie seinen Söhnen." },
      { number: 36, text: "Dann entfernte er sich mit ihnen von Jakob, und zwar drei Tagereisen weit. Jakob weidete nun die restlichen Tiere Labans." },
      { number: 37, text: "Nun schnitt sich Jakob frische Zweige von Silberpappeln, Mandelbäumen und Platanen und schälte Streifen von der Rinde ab. Diese hellgestreiften Stöcke" },
      { number: 38, text: "legte er in die Tränkrinnen.* Wenn dann die Tiere, die zum Tränken kamen, brünstig wurden", footnotes: ["Zweige ... Tränkrinnen. Dieser Trick wurde im Orient bei der Züchtung angewandt und galt als Kunstgriff eines klugen, versierten Hirten. Doch später erkannte Jakob, dass es Gott selbst war, der eingegriffen hatte (1. Mose 31,7-12)."] },
      { number: 39, text: "und sich besprangen, warfen sie lauter gestreifte, gesprenkelte und gefleckte Junge." },
      { number: 40, text: "Diese Lämmer sonderte Jakob aus und machte alle gestreiften und braunen Tiere zu einer eigenen Herde. So züchtete er sich eine besondere Herde, die er nicht zu den Tieren Labans gab." },
      { number: 41, text: "Jakob legte die Stäbe aber nur dann in die Tränkrinnen, wenn die kräftigen Tiere sich besprangen;" },
      { number: 42, text: "bei den schwächlichen tat er das nicht. So blieben die schwächlichen Tiere bei Laban und Jakob bekam die kräftigen." },
      { number: 43, text: "Auf diese Weise wurde Jakob reicher und reicher und besaß schließlich sehr viele Schafe und Ziegen, dazu Sklaven und Sklavinnen und ebenso Kamele und Esel." },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Da hörte Jakob, was die Söhne Labans über ihn redeten. \"Jakob hat alles an sich gerissen, was unserem Vater gehörte. Sein Reichtum stammt aus unserem Besitz.\"", heading: "Jakobs Flucht" },
      { number: 2, text: "Auch Laban war ihm nicht mehr so zugetan wie früher. Das konnte er ihm ansehen." },
      { number: 3, text: "Da sagte Jahwe zu Jakob: \"Kehre ins Land deiner Vorfahren und zu deinen Verwandten zurück! Ich werde bei dir sein.\"" },
      { number: 4, text: "Da ließ Jakob Rahel und Lea zu sich auf die Weide rufen." },
      { number: 5, text: "Er sagte zu ihnen: \"Ich sehe die Miene eures Vaters und merke, dass er nicht mehr so zu mir ist wie früher. Aber es war der Gott meines Vaters, der mir beistand." },
      { number: 6, text: "Ihr wisst selbst, dass ich mit ganzer Kraft für euren Vater gearbeitet habe." },
      { number: 7, text: "Doch er hat mich betrogen und meinen Lohn zehnmal verändert. Aber Gott hat ihm nicht erlaubt, mir zu schaden." },
      { number: 8, text: "Wenn euer Vater sagte: 'Die Gesprenkelten sollen dein Lohn sein', dann wurden lauter gesprenkelte Lämmer geboren. Und wenn er sagte: 'Nein, die Gestreiften', warf die ganze Herde gestreifte Lämmer." },
      { number: 9, text: "Es war Gott, der eurem Vater das Vieh weggenommen und mir gegeben hat." },
      { number: 10, text: "Während der Brunstzeit der Tiere sah ich einmal im Traum, dass alle Böcke, die die Tiere besprangen, gestreift, gesprenkelt und gescheckt waren." },
      { number: 11, text: "Da sagte der Engel Gottes im Traum zu mir: 'Jakob!' 'Ja!', erwiderte ich." },
      { number: 12, text: "'Sieh genau hin', sagte er, 'schau dir die Böcke an, die die Tiere bespringen, sie sind alle gestreift, gesprenkelt und gescheckt. Ich habe alles gesehen, was Laban dir antut." },
      { number: 13, text: "Ich bin der Gott, der dir in Bet-El begegnet ist, wo du den Stein gesalbt und mir ein Gelübde abgelegt hast. Brich jetzt auf, verlass dieses Land und kehre zu deiner Verwandtschaft zurück!\"" },
      { number: 14, text: "Rahel und Lea antworteten: \"Haben wir denn noch Teil am Erbe unseres Vaters?" },
      { number: 15, text: "Hat er uns nicht wie Fremde behandelt? Er hat uns ja verkauft und das Geld völlig für sich verbraucht." },
      { number: 16, text: "Der ganze Reichtum, den Gott unserem Vater entzogen hat, gehört uns und unseren Kindern. Tu, was Gott dir gesagt hat!\"" },
      { number: 17, text: "Da brach Jakob auf. Er setzte seine Frauen und Kinder auf die Kamele," },
      { number: 18, text: "führte all sein Vieh weg, sein ganzes Hab und Gut und die Tiere, die er in Mesopotamien erworben hatte, um ins Land Kanaan zu seinem Vater Isaak heimzukehren." },
      { number: 19, text: "Als Laban gerade zur Schafschur gegangen war, stahl Rahel den Hausgott* ihres Vaters.", footnotes: ["Hausgott. Hebräisch Terafim, eine geschnitzte Figur oder Figurengruppe, die als Schutzgott des Hauses galt."] },
      { number: 20, text: "Jakob aber bestahl das Herz des Aramäers Laban, indem er ihm seine Flucht verheimlichte." },
      { number: 21, text: "Er entfloh mit allem, was ihm gehörte, überquerte den Euphrat und zog auf das Bergland von Gilead* zu.", footnotes: ["Gilead bezeichnet das mittlere, manchmal auch das ganze Ostjordanland."] },
      { number: 22, text: "Erst am dritten Tag erfuhr Laban, dass Jakob geflohen war." },
      { number: 23, text: "Da nahm er seine Verwandten mit und jagte hinter ihm her. Nach sieben Tagen holte er ihn im Bergland von Gilead ein." },
      { number: 24, text: "Doch da erschien Gott dem Aramäer Laban im Traum und sagte zu ihm: \"Hüte dich, mit Jakob anders als freundlich zu reden!\"" },
      { number: 25, text: "Laban erreichte Jakob, als dieser gerade seine Zelte im Bergland aufgeschlagen hatte. Auch Laban und seine Verwandten bauten ihr Lager dort auf." },
      { number: 26, text: "Laban sagte zu Jakob: \"Warum hast du mein Herz gestohlen und meine Töchter wie Kriegsgefangene weggeschleppt?" },
      { number: 27, text: "Warum bist du heimlich geflohen? Warum hast du mich getäuscht und mir nichts gesagt? Ich hätte dir mit Gesang, mit Tamburin und Zithern das Geleit gegeben!" },
      { number: 28, text: "Du hast mir nicht einmal gestattet, meine Enkel und meine Töchter zum Abschied zu küssen. Das hast du dir nicht gut überlegt!" },
      { number: 29, text: "Ich hätte sehr wohl die Macht, euch übel mitzuspielen, aber der Gott eures Vaters hat mich letzte Nacht gewarnt und mir gesagt: 'Hüte dich, mit Jakob anders als freundlich zu reden!'" },
      { number: 30, text: "Nun gut, du bist nun einmal weggezogen, weil du dich so sehr nach deiner Verwandtschaft sehntest. Aber warum hast du mir auch noch meinen Hausgott gestohlen?\"" },
      { number: 31, text: "Jakob erwiderte: \"Ich hatte Angst, du würdest mir deine Töchter wegnehmen." },
      { number: 32, text: "Bei wem du aber deinen Hausgott findest, der soll nicht am Leben bleiben! Durchsuche alles in Gegenwart unserer Verwandten und nimm, was dir gehört!\" Jakob wusste nicht, dass Rahel ihn gestohlen hatte." },
      { number: 33, text: "Da durchsuchte Laban das Zelt Jakobs, das Zelt Leas und das Zelt der beiden Sklavinnen und fand nichts. Dann ging er in das Zelt Rahels." },
      { number: 34, text: "Sie hatte den Hausgott in die Tasche des Kamelsattels gesteckt und sich darauf gesetzt. Laban tastete das ganze Zelt ab, fand aber nichts." },
      { number: 35, text: "Rahel aber sagte zu ihrem Vater: \"Sei nicht zornig, mein Herr, wenn ich nicht vor dir aufstehe. Ich habe meine Tage und mir geht es nicht gut.\" Laban durchsuchte alles, konnte aber nichts finden." },
      { number: 36, text: "Da wurde Jakob zornig und begann mit Laban zu streiten. \"Was habe ich denn verbrochen?\", sagte er. \"Was habe ich dir angetan, dass du so hitzig hinter mir her bist?" },
      { number: 37, text: "Nun hast du alle meine Sachen durchwühlt. Und was hast du gefunden, das dir gehört? Lege es hierher vor meine und deine Verwandten! Sie sollen entscheiden, wer von uns beiden im Recht ist!" },
      { number: 38, text: "Zwanzig Jahre bin ich bei dir gewesen. Deine Schafe und Ziegen haben nie fehlgeworfen. Nicht einen Schafbock deiner Herde habe ich für mich geschlachtet." },
      { number: 39, text: "Wenn ein Stück von wilden Tieren gerissen wurde, durfte ich dir damit nicht kommen. Ersetzen musste ich es, egal ob es bei Tag oder bei Nacht geraubt worden war!" },
      { number: 40, text: "Am Tag verging ich vor Hitze, und nachts litt ich unter der Kälte. Oft konnte ich nicht schlafen." },
      { number: 41, text: "Zwanzig Jahre habe ich das auf mich genommen; vierzehn Jahre habe ich um deine Töchter gearbeitet und sechs um die Herde; und zehnmal hast du meinen Lohn verändert!" },
      { number: 42, text: "Wenn ich nicht den Gott meines Vaters auf meiner Seite gehabt hätte, den Gott Abrahams und den, den Isaak fürchtet, dann würdest du mich jetzt mit leeren Händen fortschicken! Aber Gott hat gesehen, wie ich mich für dich abgemüht und geschuftet habe, und hat gestern Nacht entschieden.\"" },
      { number: 43, text: "Da antwortete Laban: \"Es sind meine Töchter, meine Kinder und meine Tiere. Alles, was du hier siehst, gehört mir! Aber was kann ich jetzt noch für meine Töchter und die Söhne tun, die sie geboren haben?" },
      { number: 44, text: "Doch komm jetzt, lass uns einen Vertrag schließen, der als Zeuge zwischen mir und dir dienen kann!\"" },
      { number: 45, text: "Da packte Jakob einen Stein und wuchtete ihn als Gedenkstein hoch." },
      { number: 46, text: "Dann forderte er seine Verwandten auf, Steine zu sammeln und sie zu einem Hügel zu schichten. Und auf diesem Steinhügel hielten sie ein gemeinsames Mahl." },
      { number: 47, text: "Laban nannte ihn Jegar-Sahaduta und Jakob Gal-Ed, Zeugenhügel*.", footnotes: ["Zeugenhügel. Gal-Ed ist hebräisch. Jegar-Sahaduta bedeutet dasselbe auf aramäisch."] },
      { number: 48, text: "\"Dieser Steinhügel ist Zeuge für unseren Vertrag\", sagte Laban. Deshalb bekam er den Namen Gal-Ed." },
      { number: 49, text: "Er nannte ihn aber auch Mizpa, Wachtturm, denn er sagte: \"Jahwe möge ein wachsames Auge auf uns haben, wenn wir uns aus dem Gesicht verlieren!" },
      { number: 50, text: "Hüte dich, meine Töchter zu kränken oder noch weitere Frauen zu nehmen! Kein Mensch ist hier dabei, aber Gott ist unser Zeuge!\"" },
      { number: 51, text: "Weiter sagte Laban zu Jakob: \"Dieser Steinhügel und dieser Gedenkstein, den ich zwischen uns errichtet habe," },
      { number: 52, text: "seien Zeugen, dass keiner von uns über diesen Hügel hinaus in böser Absicht zum anderen zieht." },
      { number: 53, text: "Der Gott Abrahams und der Gott Nahors, der Gott ihres Vaters soll den bestrafen, der sich nicht daran hält.\"So leistete Jakob einen Eid bei dem Gott, den sein Vater Isaak fürchtete." },
      { number: 54, text: "Dann schlachtete er dort auf dem Berg ein Opfertier und lud seine Verwandten zur Opfermahlzeit ein. Sie aßen miteinander und verbrachten die Nacht auf dem Berg." },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Früh am nächsten Morgen küsste Laban zum Abschied seine Enkel und seine Töchter und segnete sie. Dann kehrte er in seine Heimat zurück." },
      { number: 2, text: "Als dann auch Jakob weiterzog, begegneten ihm Engel Gottes." },
      { number: 3, text: "\"Hier ist das Lager Gottes!\", sagte er, als er sie sah. Deshalb nannte er jenen Ort Mahanajim, Doppellager." },
      { number: 4, text: "Nun schickte Jakob Boten zu seinem Bruder Esau voraus, der sich im Bergland von Seïr* im Gebiet Edoms aufhielt.", heading: "Jakob nähert sich Esau", footnotes: ["Seïr. Siehe 1. Mose 14,6"] },
      { number: 5, text: "Er befahl ihnen: \"Wenn ihr zu meinem Herrn, zu Esau kommt, sollt ihr sagen: 'Dein Diener Jakob lässt dir sagen: Die ganze Zeit über habe ich mich als Fremder bei Laban aufgehalten." },
      { number: 6, text: "Ich habe Rinder, Esel und Kleinvieh erworben, Sklaven und Sklavinnen. Das wollte ich dir, meinem Herrn, mitteilen, um dein Wohlwollen zu gewinnen.\"" },
      { number: 7, text: "Als die Boten zurückkamen berichteten sie: \"Wir waren bei deinem Bruder, bei Esau. Er ist schon unterwegs und zieht dir mit vierhundert Mann entgegen.\"" },
      { number: 8, text: "Jakob wurde angst und bange. Er teilte die Leute, die er bei sich hatte, in zwei Lager, dazu das Kleinvieh, die Rinder und die Kamele," },
      { number: 9, text: "denn er sagte sich: \"Wenn Esau auf das eine Lager trifft und alles erschlägt, kann doch das andere entkommen.\"" },
      { number: 10, text: "Dann betete Jakob: \"Jahwe, Gott meines Vaters Abraham und Gott meines Vaters Isaak! Du hast zu mir gesagt: 'Kehr in deine Heimat und zu deiner Verwandtschaft zurück; ich werde es dir gut gehen lassen!'" },
      { number: 11, text: "Ich bin zu gering für alle Barmherzigkeit und Treue, die du an mir, deinem Diener, erwiesen hast. Denn nur mit meinem Stab bin ich über diesen Jordan gegangen, und nun bin ich zu zwei Lagern geworden." },
      { number: 12, text: "Rette mich doch vor meinem Bruder, vor Esau. Ich habe Angst vor ihm, dass er nicht etwa kommt und uns alle umbringt, auch die Mütter und die Kinder." },
      { number: 13, text: "Du hast mir doch versprochen: 'Ich will dir viel Gutes tun, und deine Nachkommen sollen werden wie der Sand am Meer, den niemand zählen kann.'\"" },
      { number: 14, text: "Er blieb die Nacht über dort und stellte aus seinem Besitz ein Geschenk für seinen Bruder Esau zusammen:" },
      { number: 15, text: "200 Ziegen und 20 Ziegenböcke, 200 Mutterschafe und 20 Schafböcke," },
      { number: 16, text: "30 Kamelstuten mit ihren Jungen, 40 Kühe, 10 Stiere, 20 Eselinnen und 10 Esel." },
      { number: 17, text: "Jede dieser Herden übergab er einem seiner Leute und sagte: \"Zieht voraus und lasst einen Abstand zwischen den Herden!\"" },
      { number: 18, text: "Dem ersten befahl er: \"Wenn mein Bruder Esau dir entgegenkommt, wird er fragen: 'Wem gehörst du und wohin gehst du? Und wem gehören die Tiere, die du treibst?'," },
      { number: 19, text: "dann sollt ihr sagen: 'Es gehört alles deinem Diener Jakob, und es ist ein Geschenk, das er meinem Herrn Esau macht. Er selbst kommt hinter uns her.'\"" },
      { number: 20, text: "Dieselbe Anweisung gab er auch dem zweiten, dem dritten und allen anderen, die hinter den Herden gingen: \"Genau dasselbe sollt ihr zu Esau sagen, wenn ihr ihn trefft." },
      { number: 21, text: "Und sagt immer: 'Dein Diener Jakob kommt auch noch hinter uns her.'\" Denn er dachte: \"Ich will ihn durch das Geschenk, das vor mir herzieht, versöhnen. Erst dann will ich ihm selbst unter die Augen treten. Vielleicht nimmt er mich freundlich auf.\"" },
      { number: 22, text: "So zog das Geschenk ihm voraus, während er die Nacht über im Lager blieb." },
      { number: 23, text: "Doch mitten in der Nacht stand er auf, nahm seine beiden Frauen, die beiden Sklavinnen und seine elf Söhne und überquerte mit ihnen den Jabbok an einer Furt.", heading: "Jakob ringt mit Gott" },
      { number: 24, text: "Auch alle seine Herden und seinen Besitz brachte er über den Fluss." },
      { number: 25, text: "Nur Jakob selbst blieb zurück. Da rang ein Mann mit ihm, bis die Morgenröte heraufzog." },
      { number: 26, text: "Als jener merkte, dass Jakob sich nicht niederringen ließ, schlug er auf dessen Hüftgelenk, sodass es sich ausrenkte." },
      { number: 27, text: "Dann sagte er: \"Lass mich los, die Morgenröte zieht schon herauf!\" Doch Jakob erwiderte: \"Ich lass dich nicht los, wenn du mich nicht vorher segnest!\"" },
      { number: 28, text: "\"Wie heißt du?\", fragte der Mann. \"Jakob\", erwiderte er." },
      { number: 29, text: "Da sagte er: \"Du sollst nicht mehr Jakob heißen, sondern Israel, Gotteskämpfer! Denn du hast mit Gott und mit Menschen gekämpft und hast gesiegt.\"" },
      { number: 30, text: "Da bat Jakob: \"Sag mir doch, wie du heißt!\" Doch er erwiderte nur: \"Warum fragst du?\"; und er segnete ihn." },
      { number: 31, text: "\"Ich habe Gott ins Gesicht gesehen\", sagte Jakob, \"und ich lebe noch!\" Darum nannte er jenen Ort Pnuël, Gottes Gesicht." },
      { number: 32, text: "Als Jakob Pnuël verließ, ging die Sonne über ihm auf. Er hinkte wegen seiner Hüfte." },
      { number: 33, text: "Deshalb lehnen es die Israeliten bis heute ab, den Muskel zu essen, der über dem Hüftgelenk liegt, weil Jakob an dieser Stelle von Gott geschlagen worden war." },
    ] },
    { number: 33, verses: [
      { number: 1, text: "Als Jakob aufblickte, sah er Esau mit seinen 400 Männern kommen. Da verteilte er die Kinder auf Lea, Rahel und die beiden Sklavinnen.", heading: "Jakob versöhnt sich mit Esau" },
      { number: 2, text: "Dann stellte er die Sklavinnen mit ihren Kindern voran, dahinter Lea und ihre Kinder und zuletzt Rahel mit Josef." },
      { number: 3, text: "Er selbst ging vor ihnen her und warf sich siebenmal zur Erde, bis er zu seinem Bruder kam." },
      { number: 4, text: "Da lief Esau ihm entgegen und umarmte ihn; er fiel ihm um den Hals und küsste ihn; beide weinten." },
      { number: 5, text: "Dann sah Esau die Frauen und die Kinder und fragte: \"Wer sind die dort bei dir?\" – \"Das sind die Kinder, die Gott deinem Diener geschenkt hat\", sagte er." },
      { number: 6, text: "Dann traten die Sklavinnen mit ihren Kindern heran und warfen sich nieder," },
      { number: 7, text: "ebenso Lea mit ihren Kindern und zuletzt Rahel mit Josef." },
      { number: 8, text: "\"Was wolltest du denn mit dem ganzen Lager, auf das ich gestoßen bin?\", fragte Esau. \"Gnade finden vor meinem Herrn!\", erwiderte Jakob." },
      { number: 9, text: "Da sagte Esau: \"Ich habe genug, mein Bruder! Behalte nur, was dir gehört.\"" },
      { number: 10, text: "\"Nein, nein!\", sagte Jakob. \"Wenn ich überhaupt Gnade vor dir gefunden habe, dann nimm mein Geschenk an! Denn ich habe dein Gesicht gesehen, wie man Gottes Angesicht schaut: So freundlich warst du zu mir!" },
      { number: 11, text: "Nimm doch mein Geschenk an! Denn Gott war mir gnädig, und ich habe alles.\" So drängte er seinen Bruder, bis er es annahm." },
      { number: 12, text: "Dann schlug Esau vor: \"Lass uns aufbrechen und weiterziehen! Ich werde dich begleiten.\"" },
      { number: 13, text: "Doch Jakob erwiderte: \"Mein Herr, du siehst ja, dass die Kinder noch zart sind und ich auch säugende Schafe und Rinder bei mir habe. Wenn man sie nur einen Tag zu schnell treiben würde, ginge mir die ganze Herde ein." },
      { number: 14, text: "Mein Herr, zieh du ruhig voraus! Ich werde dir nach Seïr folgen, will das aber ganz gemächlich tun, wie es dem Vieh und meinen Kindern angemessen ist.\"" },
      { number: 15, text: "\"Dann lasse ich wenigstens ein paar von meinen Leuten bei dir\", sagte Esau. \"Wozu das?\", erwiderte Jakob. \"Hauptsache, ich habe Gnade vor dir, meinem Herrn, gefunden.\"" },
      { number: 16, text: "Da machte sich Esau auf den Rückweg nach Seïr." },
      { number: 17, text: "Jakob zog weiter nach Sukkot.* Dort baute er sich ein Haus und Hütten für sein Vieh. Deshalb nannte er den Ort Sukkot, Hütten.", heading: "Jakob in Sichem", footnotes: ["Sukkot. Das ist in westliche statt in südliche Richung nach Seïr (=Edom). Er überquerte dabei erneut den Jabbok und später den Jordan auf dem Weg nach Sichem."] },
      { number: 18, text: "Später zog Jakob in friedlicher Absicht nach Sichem im Land Kanaan. Draußen vor der Stadt schlug er sein Lager auf." },
      { number: 19, text: "Dann kaufte er von den Söhnen Hamors, des Stadtgründers, das Stück Land, auf dem er seine Zelte aufgeschlagen hatte. Er bezahlte ihnen 100 Kesita* dafür.", footnotes: ["Kesita. Geldeinheit/Geldgewicht ist bis heute unbekannt."] },
      { number: 20, text: "Dort errichtete er auch einen Altar und nannte ihn: \"Gott ist der Gott Israels\"." },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Eines Tages wollte Dina, die Tochter von Lea und Jakob, sich unter den Mädchen des Landes umsehen.", heading: "Dinas Vergewaltigung und das Blutbad in Sichem" },
      { number: 2, text: "Als Sichem sie sah – er war der Sohn von Hamor, dem führenden Mann der ganzen Gegend –, fiel er über sie her und vergewaltigte sie." },
      { number: 3, text: "Er hatte aber eine Zuneigung zu Dina gefasst. Deshalb redete er mit ihr und suchte ihr Herz zu gewinnen. Er liebte das Mädchen" },
      { number: 4, text: "und sagte zu seinem Vater Hamor: \"Sorge dafür, dass ich dieses Mädchen heiraten kann!\"" },
      { number: 5, text: "Als Jakob hörte, dass seine Tochter Dina vergewaltigt worden war, verhielt er sich ruhig, bis seine Söhne heimkamen. Sie waren nämlich bei den Tieren auf der Weide." },
      { number: 6, text: "Sichems Vater Hamor kam zu Jakob heraus, um mit ihm über die Sache zu reden." },
      { number: 7, text: "Als die Söhne Jakobs nach Hause kamen und von der Sache hörten, fühlten sich die Männer schwer gekränkt. Sie wurden sehr zornig, denn durch die Vergewaltigung einer Tochter Jakobs hatte Sichem eine Schandtat in Israel verübt. So etwas durfte nicht geschehen." },
      { number: 8, text: "Doch Hamor redete ihnen zu. \"Mein Sohn Sichem hängt an dem Mädchen. Gebt sie ihm doch zur Frau!" },
      { number: 9, text: "Warum sollen wir uns nicht mit euch verschwägern? Gebt uns eure Töchter und ihr heiratet unsere." },
      { number: 10, text: "Siedelt euch unter uns an; das Land steht euch offen! Bewohnt es, bereist es und macht euch darin ansässig!\"" },
      { number: 11, text: "Und Sichem sagte zu Dinas Vater und zu ihren Brüdern: \"Lasst mich Gnade vor euch finden! Ich will euch alles geben, was ihr verlangt." },
      { number: 12, text: "Ihr könnt den Preis für die Braut und die Hochzeitsgabe so hoch machen, wie ihr wollt. Ich werde es bezahlen. Nur gebt mir das Mädchen zur Frau!\"" },
      { number: 13, text: "Doch die Söhne Jakobs gaben Sichem und seinem Vater eine hinterhältige Antwort, weil Sichem ihre Schwester Dina entehrt hatte." },
      { number: 14, text: "\"Wir können unsere Schwester keinem Mann geben, der eine Vorhaut hat. Das wäre eine Schande für uns." },
      { number: 15, text: "Nur unter einer Bedingung können wir eurem Wunsch entsprechen: Ihr müsst so werden wie wir! Alle männlichen Personen müssen sich beschneiden* lassen!", footnotes: ["beschneiden. Vergleiche 1. Mose 17,9-14!"] },
      { number: 16, text: "Dann geben wir euch unsere Töchter und können auch eure Töchter heiraten; dann wollen wir bei euch wohnen bleiben und mit euch zusammen ein Volk bilden." },
      { number: 17, text: "Doch wenn ihr nichts davon wissen wollt, nehmen wir unsere Tochter und gehen.\"" },
      { number: 18, text: "Hamor und sein Sohn waren mit dem Vorschlag einverstanden." },
      { number: 19, text: "Der junge Mann nahm die Sache gleich in die Hand, denn er hatte Gefallen an der Tochter Jakobs. Und im ganzen Haus seines Vaters hörten alle auf ihn." },
      { number: 20, text: "So gingen Hamor und Sichem ans Tor ihrer Stadt und redeten zu den dort versammelten Männern:" },
      { number: 21, text: "\"Diese Männer sind uns friedlich gesinnt. Lassen wir sie doch bei uns im Land wohnen und darin umherziehen. Das Land ist ja weit genug für sie. Wir können uns durch gegenseitige Heirat mit ihnen verbinden." },
      { number: 22, text: "Jedoch sind sie nur dann bereit, bei uns zu bleiben und ein Volk mit uns zu werden, wenn sich alle männlichen Personen unter uns beschneiden lassen, wie es bei ihnen der Fall ist." },
      { number: 23, text: "Wir sollten auf ihren Vorschlag eingehen, damit sie bei uns bleiben. Ihre Herden, ihr Besitz und all ihr Lastvieh wird dann doch uns gehören!\"" },
      { number: 24, text: "Die Männer der Stadt hörten auf Hamor und seinen Sohn Sichem; und alle männlichen Personen, die zur Stadt gehörten, ließen sich beschneiden." },
      { number: 25, text: "Drei Tage später, als sie im Wundfieber lagen, nahmen die Brüder Dinas, die Jakobssöhne Simeon und Levi, ihre Schwerter, überfielen die sorglose Stadt und töteten alle männlichen Bewohner." },
      { number: 26, text: "Sie erschlugen auch Hamor und seinen Sohn Sichem, holten ihre Schwester aus Sichems Haus und nahmen sie mit." },
      { number: 27, text: "Dann plünderten die Söhne Jakobs die Stadt und raubten die Erschlagenen aus, weil sie ihre Schwester entehrt hatten." },
      { number: 28, text: "Sie nahmen ihr Kleinvieh, ihre Rinder und Esel, alles, was in der Stadt und auf dem freien Feld war," },
      { number: 29, text: "und raubten alles, was sie in den Häusern fanden. Auch ihre Kinder und Frauen schleppten sie als Beute weg." },
      { number: 30, text: "Da sagte Jakob zu Simeon und Levi: \"Ihr stürzt mich ins Unglück, denn ihr habt mich bei den Bewohnern des Landes verhasst gemacht, bei den Kanaanitern und Perisitern. Ich habe doch nur eine zählbare Mannschaft. Wenn sie sich gegen mich zusammentun, werden sie mich erschlagen, dann bringen sie mich und meine Familie um.\"" },
      { number: 31, text: "Aber sie erwiderten: \"Durfte er unsere Schwester denn wie eine Hure behandeln?\"" },
    ] },
    { number: 35, verses: [
      { number: 1, text: "Gott sagte zu Jakob: Zieh nach Bet-El hinauf, lass dich dort nieder und baue einen Altar für den Gott, der dir erschienen ist, als du vor deinem Bruder Esau geflohen bist.\"", heading: "Jakob in Bethel" },
      { number: 2, text: "Da befahl Jakob seiner ganzen Familie und allen, die bei ihm waren: \"Schafft die fremden Götter weg, die ihr noch habt! Reinigt euch und zieht frische Sachen an!" },
      { number: 3, text: "Wir werden nach Bet-El hinaufziehen, und ich werde dort einen Altar bauen für den Gott, der mich in meiner Not erhört hat und mir auf meinem ganzen Weg zur Seite stand." },
      { number: 4, text: "Da gaben sie Jakob ihre Götterfiguren und ihre Ohrringe*, und er vergrub sie unter der Terebinthe bei Sichem.", footnotes: ["Ohrringe wurden offenbar als Amulette getragen."] },
      { number: 5, text: "Dann brachen sie auf. Niemand wagte es, sie zu verfolgen, denn auf den umliegenden Städten lag ein Schrecken Gottes." },
      { number: 6, text: "So kam Jakob mit seinen Leuten nach Lus im Land Kanaan, das jetzt Bet-El heißt." },
      { number: 7, text: "Dort baute er einen Altar und nannte die Opferstätte El-Bet-El*, denn hier war ihm Gott erschienen, als er vor seinem Bruder Esau floh.", footnotes: ["El-Bet-El. Das heißt Gott von Bet-El, bzw. Gott vom Haus Gottes."] },
      { number: 8, text: "Während sie dort waren, starb Debora, die Amme Rebekkas. Sie begruben sie unterhalb von Bet-El unter der Steineiche, die davon den Namen Allon Bachut, Klageeiche, erhielt." },
      { number: 9, text: "Da erschien Gott Jakob und segnete ihn. Es war das zweite Mal seit seiner Rückkehr aus Mesopotamien." },
      { number: 10, text: "Gott sagte: \"Du heißt Jakob. Doch von jetzt an sollst du nicht mehr Jakob, sondern Israel genannt werden!\" So gab er ihm den Namen Israel." },
      { number: 11, text: "Weiter sagte Gott zu ihm: \"Ich bin El-Schaddai, der allmächtige Gott. Sei fruchtbar und vermehre dich! Ein Volk, ja eine ganze Schar von Völkern wird von dir abstammen, selbst Könige werden unter deinen direkten Nachkommen sein." },
      { number: 12, text: "Das Land, das ich Abraham und Isaak zugesprochen habe, werde ich dir und deinen Nachkommen geben.\"" },
      { number: 13, text: "Als Gott das Gespräch mit ihm beendet hatte, fuhr er von diesem Ort wieder in den Himmel auf." },
      { number: 14, text: "Jakob stellte einen Gedenkstein dorthin, wo Gott mit ihm geredet hatte. Er goss ein Trankopfer darüber und salbte ihn mit Öl." },
      { number: 15, text: "Die Stelle, wo Gott mit ihm geredet hatte, nannte er Bet-El, Haus Gottes." },
      { number: 16, text: "Dann brachen sie wieder von Bet-El auf. Als sie nur noch ein Stück von Efrata entfernt waren, setzten die Wehen bei Rahel ein. Sie hatte eine sehr schwere Geburt.", heading: "Die schwere Geburt Benjamins" },
      { number: 17, text: "Als ihr die Geburt so schwer wurde, sagte die Hebamme zu ihr: \"Hab keine Angst, es wird wieder ein Sohn!\"" },
      { number: 18, text: "Aber Rahel spürte, dass ihr das Leben entwich und sie sterben würde. Da nannte sie ihn Ben-Oni, Sohn meiner Totenklage. Sein Vater aber nannte ihn Benjamin, Sohn meines Glücks." },
      { number: 19, text: "So starb Rahel und wurde dort am Weg nach Efrata begraben, das jetzt Bethlehem heißt." },
      { number: 20, text: "Jakob errichtete einen Gedenkstein auf ihrem Grab, der noch heute als Grabmal Rahels dort steht." },
      { number: 21, text: "Dann zog Israel weiter und schlug seine Zelte jenseits von Migdal-Eder* auf.", heading: "Jakobs Söhne", footnotes: ["Migdal-Eder heißt Herdenturm. Es war ein Platz mit Wachtturm, von dem aus die Herden überwacht werden konnten. Die Lage dieses Ortes ist nicht mehr festzustellen, vermutlich war es in der Nähe von Jerusalem."] },
      { number: 22, text: "Dort geschah es, dass Ruben mit Bilha, der Nebenfrau seines Vaters, schlief. Und Israel erfuhr davon.Jakob hatte zwölf Söhne." },
      { number: 23, text: "Die Söhne Leas: Ruben, der Erstgeborene Jakobs, Simeon, Levi, Juda, Issachar und Sebulon." },
      { number: 24, text: "Die Söhne Rahels: Josef und Benjamin." },
      { number: 25, text: "Die Söhne Bilhas, der Sklavin Rahels: Dan und Naftali." },
      { number: 26, text: "Die Söhne Silpas, der Sklavin Leas: Gad und Ascher. Alle wurden noch in Mesopotamien geboren." },
      { number: 27, text: "Jakob kam dann zu seinem Vater Isaak nach Mamre bei Kirjat-Arba, das jetzt Hebron heißt. Dort hatten Abraham und Isaak sich niedergelassen.", heading: "Isaaks Tod" },
      { number: 28, text: "Isaak wurde 180 Jahre alt." },
      { number: 29, text: "Er starb nach einem langen und erfüllten Leben und wurde im Tod mit seinen Stammesgenossen vereint. Seine beiden Söhne Esau und Jakob begruben ihn." },
    ] },
    { number: 36, verses: [
      { number: 1, text: "Es folgt das Verzeichnis der Nachkommen* von Esau, der auch Edom heißt.", heading: "Esaus Nachkommen", footnotes: ["Verzeichnis der Nachkommen. Hebräisch toledot, siehe 1. Mose 2,4."] },
      { number: 2, text: "Esau hatte Frauen aus dem Land Kanaan geheiratet. Es waren Ada, die Tochter des Hetiters Elon, Oholibama, eine Tochter Anas und Enkelin des Hiwiters Zibon," },
      { number: 3, text: "und Basemat. Das war eine Tochter Ismaëls und die Schwester von Nebajot." },
      { number: 4, text: "Ada gebar Elifas, Basemat gebar Reguël," },
      { number: 5, text: "und Oholibama gebar Jëusch, Jalam und Korach. Diese Söhne wurden Esau im Land Kanaan geboren." },
      { number: 6, text: "Später zog Esau von seinem Bruder Jakob weg in ein anderes Land. Seine Frauen, seine Söhne und Töchter nahm er mit und alle seine Leute, seine Herden und den ganzen Besitz, den er im Land Kanaan erworben hatte." },
      { number: 7, text: "Ihr Besitz war nämlich viel zu groß, um zusammenbleiben zu können, denn in dem Land, in dem sie als Fremde wohnten, gab es nicht genügend Weiden für ihr Vieh." },
      { number: 8, text: "So ließ sich Esau, also Edom, im Bergland von Seïr* nieder.", footnotes: ["Das Bergland von Seïr erstreckt sich östlich der Araba bis nach Elat (El-Paran) am Roten Meer."] },
      { number: 9, text: "Es folgt das Verzeichnis der Nachkommen von Esau, dem Stammvater der Edomiter, die im Gebirge Seïr leben." },
      { number: 10, text: "Die Namen der Söhne Esaus waren: Elifas, Sohn der Ada, und Reguël, Sohn der Basemat." },
      { number: 11, text: "Elifas wurde der Vater von Teman, Omar, Zefo, Gatam und Kenas." },
      { number: 12, text: "Von seiner Nebenfrau Timna hatte Elifas noch Amalek. Sie alle stammen von Esaus Frau Ada ab." },
      { number: 13, text: "Reguël wurde der Vater von Nahat, Serach, Schamma und Misa. Sie stammen von Esaus Frau Basemat ab." },
      { number: 14, text: "Von Oholibama, der Tochter Anas und Enkelin Zibons, stammen Esaus Söhne Jëusch, Jalam und Korach." },
      { number: 15, text: "Es folgen die Namen der Stammesfürsten, die sich von Esau herleiten. Von Elifas, dem Erstgeborenen Esaus, stammen: Teman, Omar, Zefo, Kenas," },
      { number: 16, text: "Korach, Gatam und Amalek. Sie alle gehen auf Esaus Frau Ada zurück." },
      { number: 17, text: "Von Esaus Sohn Reguël stammen: Nahat, Serach, Schamma und Misa. Sie gehen auf Esaus Frau Basemat zurück." },
      { number: 18, text: "Von Esaus Frau Oholibama stammen Jëusch, Jalam und Korach." },
      { number: 19, text: "Das sind also die Edomiter, Esaus Nachkommen und ihre Stammesfürsten." },
      { number: 20, text: "Es folgen die Namen der dort ansässigen Bewohner, Nachkommen des Horiters Seïr. Seine Söhne hießen Lotan, Schobal, Zibon, Ana," },
      { number: 21, text: "Dischon, Ezer und Dischan. Das waren die Stammesfürsten der Horiter." },
      { number: 22, text: "Lotans Söhne hießen Hori und Heman. Lotans Schwester war Timna." },
      { number: 23, text: "Die Söhne Schobals hießen Alwan, Manahat, Ebal, Schefo und Onam." },
      { number: 24, text: "Die Söhne Zibons waren Aja und Ana. Ana war es, der Jemim* in der Wildnis fand, als er die Esel seines Vaters hütete.", footnotes: ["Jemim. Die Bedeutung des hebräischen Wortes, das nur einmal in der Bibel vorkommt, ist unsicher (heiße Quellen?, Vipern?)."] },
      { number: 25, text: "Anas Sohn hieß Dischon, seine Tochter Oholibama." },
      { number: 26, text: "Die Söhne Dischons hießen Hemdan, Eschban, Jitran und Keran." },
      { number: 27, text: "Die Söhne Ezers waren Bilhan, Saawan und Akan." },
      { number: 28, text: "Die Söhne Dischans waren Uz und Aran." },
      { number: 29, text: "Das sind also die Stammesfürsten der Horiter: Lotan, Schobal, Zibon, Ana," },
      { number: 30, text: "Dischon, Ezer und Dischan, aufgeführt in der Reihenfolge ihrer Stammväter." },
      { number: 31, text: "Folgende Könige herrschten nacheinander über das Land Edom, noch bevor es einen König in Israel gab:" },
      { number: 32, text: "Bela, der Sohn Beors, in der Stadt Dinhaba;" },
      { number: 33, text: "Jobab, der Sohn Serachs, aus der Stadt Bozra;" },
      { number: 34, text: "Huscham aus dem Gebiet des Stammes Teman;" },
      { number: 35, text: "Hadad, der Sohn Bedads, in der Stadt Awit; er besiegte die Midianiter in einer Schlacht auf dem Gebiet von Moab;" },
      { number: 36, text: "Samla aus der Stadt Masreka;" },
      { number: 37, text: "Schaul aus Rehobot am Strom;" },
      { number: 38, text: "Baal-Hanan, der Sohn Achbors;" },
      { number: 39, text: "Hadar in der Stadt Pagu; seine Frau Mehetabel war eine Tochter Matreds und Enkelin Me-Sahabs." },
      { number: 40, text: "Folgende Fürsten der Nachkommen Esaus haben ihren Sippen und Städten den Namen gegeben: Timna, Alwa, Jetet," },
      { number: 41, text: "Oholibama, Ela, Pinon," },
      { number: 42, text: "Kenas, Teman, Mibzar," },
      { number: 43, text: "Magdiël und Iram. Das waren die Fürsten Edoms nach ihren Siedlungsgebieten in dem Land, das sie besaßen. So viel zu Esau, dem Stammvater der Edomiter." },
    ] },
    { number: 37, verses: [
      { number: 1, text: "Jakob hatte seinen Wohnsitz im Land Kanaan, wo schon sein Vater als Fremder gelebt hatte.", heading: "Das Leben Josefs (37-50)\nJosefs Träume" },
      { number: 2, text: "Es folgt die Geschichte der Nachkommen* Jakobs.Josef war noch ein junger Bursche von 17 Jahren, als er mit seinen Brüdern, den Söhnen von Bilha und Silpa, das Kleinvieh hütete. Er hinterbrachte seinem Vater, was die Leute Schlechtes über sie redeten.", footnotes: ["Geschichte der Nachkommen. Hebräisch toledot, siehe 1. Mose 2,4."] },
      { number: 3, text: "Doch Israel hatte Josef lieber als alle seine anderen Söhne, weil er ihm erst im Alter geboren worden war. Deshalb ließ er ihm ein prächtiges Gewand machen." },
      { number: 4, text: "Als seine Brüder sahen, dass ihr Vater ihn mehr liebte als sie alle, hassten sie ihn und konnten kein freundliches Wort mehr mit ihm reden." },
      { number: 5, text: "Einmal hatte Josef einen Traum und erzählte ihn seinen Brüdern. Da wurde ihr Hass noch größer." },
      { number: 6, text: "\"Hört doch, was ich geträumt habe!\", sagte er zu ihnen." },
      { number: 7, text: "\"Wir waren auf dem Feld und banden das Getreide in Garben zusammen. Auf einmal stellte sich meine Garbe auf und blieb stehen. Und zu meiner Überraschung stellten sich eure Garben ringsherum auf und verneigten sich vor meiner.\"" },
      { number: 8, text: "Seine Brüder sagten zu ihm: \"Du möchtest wohl noch König über uns werden und über uns herrschen?\" Wegen seiner Träume und Reden hassten sie ihn noch mehr." },
      { number: 9, text: "Er hatte nämlich noch einen anderen Traum und erzählte ihnen auch den. \"Passt auf! Ich hatte noch einen Traum\", sagte er. \"Ich sah die Sonne, den Mond und elf Sterne. Und auf einmal verneigten sie sich vor mir.\"" },
      { number: 10, text: "Als er dies seinem Vater und seinen Brüdern erzählte, fuhr sein Vater ihn an. \"Was soll dieser Traum!\", rief er. \"Sollen wir uns vielleicht alle vor dir niederwerfen, ich, deine Mutter und deine Brüder?\"" },
      { number: 11, text: "Seine Brüder waren eifersüchtig auf Josef, aber sein Vater vergaß die Sache nicht." },
      { number: 12, text: "Einmal weideten Josefs Brüder das Kleinvieh ihres Vaters in der Nähe von Sichem.", heading: "Josef wird als Sklave verkauft" },
      { number: 13, text: "Da sagte Israel zu Josef: \"Du weißt, dass deine Brüder mit den Herden in der Nähe von Sichem sind. Komm, ich will dich zu ihnen schicken!\" – \"Ich bin bereit\", erwiderte er." },
      { number: 14, text: "\"Schau nach, ob es deinen Brüdern und den Herden gut geht, und bring mir Nachricht!\", sagte sein Vater. Er schickte ihn aus dem Tal von Hebron nach Sichem." },
      { number: 15, text: "Als Josef dort auf dem freien Feld umherirrte, traf ihn ein Mann. \"Was suchst du?\", fragte er ihn." },
      { number: 16, text: "\"Ich suche meine Brüder\", erwiderte er, \"kannst du mir sagen, wo sie mit den Herden sind?\"" },
      { number: 17, text: "\"Sie sind von hier fortgezogen. Ich hörte sie sagen: 'Wir wollen nach Dotan* gehen!'\" Da ging Josef seinen Brüdern nach und fand sie bei Dotan.", footnotes: ["Die Stadt Dotan lag auf einem Hügel in der Jesreel-Ebene, 18 km nördlich von Samaria."] },
      { number: 18, text: "Sie sahen ihn schon von weitem. Und noch bevor er herangekommen war, hatten sie sich verschworen, ihn zu töten." },
      { number: 19, text: "\"Seht, da kommt ja der Meister der Träume!\", sagten sie zueinander." },
      { number: 20, text: "\"Los, wir schlagen ihn tot und werfen ihn in die Zisterne dort! Wir sagen einfach: 'Ein wildes Tier hat ihn gefressen!', dann werden wir schon sehen, was aus seinen Träumen wird.\"" },
      { number: 21, text: "Als Ruben das hörte, wollte er Josef retten. \"Nein, lassen wir ihn leben!\", sagte er." },
      { number: 22, text: "\"Vergießt kein Blut! Werft ihn in die Zisterne dort in der Steppe, aber vergreift euch nicht an ihm!\" Er wollte ihn aus ihrer Gewalt retten und zu seinem Vater zurückbringen." },
      { number: 23, text: "Als Josef bei seinen Brüdern ankam, zogen sie ihm das Obergewand aus, das Prachtstück, das er anhatte." },
      { number: 24, text: "Dann packten sie ihn und warfen ihn in die Zisterne. Sie war leer, ohne Wasser." },
      { number: 25, text: "Dann setzten sie sich zum Essen nieder. Auf einmal sahen sie eine Karawane von Ismaëliten*, die aus Gilead kamen. Ihre Kamele waren mit kostbaren Harzen, mit Tragakant, Mastix und Ladanum* beladen.", footnotes: ["Ismaëliten sind Nachkommen Ismaëls, siehe 1. Mose 16. Weil diese als Nomaden in der Wüste lebten (siehe 1. Mose 25,12-18; Richter 8,24), wurden damals alle Wüstenstämme so bezeichnet.", "Tragakant, Mastix und Ladanum sind Gummiharze, die als Grundstoffe für Medikamente und zur Parfümherstellung dienten. In Ägypten wurden sie vor allem zum Einbalsamieren verwendet."] },
      { number: 26, text: "Da sagte Juda zu seinen Brüdern: \"Was haben wir davon, wenn wir unseren Bruder erschlagen und die Bluttat verheimlichen müssen." },
      { number: 27, text: "Verkaufen wir ihn doch an die Ismaëliten und vergreifen uns nicht an ihm! Schließlich ist er unser Bruder, unser eigenes Fleisch und Blut.\" Seine Brüder hörten auf ihn." },
      { number: 28, text: "Als die midianitischen* Händler herankamen, zogen sie Josef aus der Zisterne. Sie verkauften ihn für 20 Silberstücke an die Ismaëliten, die ihn nach Ägypten mitnahmen.", footnotes: ["Die Midianiter waren ein Nomadenvolk, das in der Araba und in Transjordanien umherzog. Die Ismaëliten (=Wüstennomaden) hier gehörten also speziell zum Stamm der Midianiter."] },
      { number: 29, text: "Als nun Ruben zu der Zisterne zurückkam, war Josef auf einmal nicht mehr da. Da riss er sein Obergewand ein*,", footnotes: ["riss ... ein. Als Zeichen von Trauer und Entsetzen riss man das Kleidungsstück vom Halsausschnitt an mit einem heftigen Ruck etwa eine Handlänge ein."] },
      { number: 30, text: "ging zu seinen Brüdern und rief: \"Der Junge ist nicht mehr da! Was soll ich jetzt bloß machen?\"" },
      { number: 31, text: "Da schlachteten sie einen Ziegenbock und tauchten Josefs Obergewand in das Blut." },
      { number: 32, text: "Dann schickten sie das prächtige Gewand zu ihrem Vater und ließen ihm sagen: \"Das haben wir gefunden. Ist es vielleicht das Gewand deines Sohnes?\"" },
      { number: 33, text: "Er erkannte es und schrie auf: \"Das Gewand meines Sohnes! Ein böses Tier hat ihn gefressen! Zerfleischt, zerfleischt ist Josef!\"" },
      { number: 34, text: "Er riss sein Obergewand ein, band den Sack* um die Hüfte und trauerte lange Zeit um Josef.", footnotes: ["Der Sack war ein grobes, einfaches Trauergewand."] },
      { number: 35, text: "Alle seine Söhne und Töchter kamen, um ihn zu trösten, aber er wollte sich nicht trösten lassen. \"Nein\", sagte er, \"trauernd werde ich zu meinem Sohn ins Totenreich hinunterfahren!\" So weinte sein Vater um ihn." },
      { number: 36, text: "Die Midianiter brachten Josef nach Ägypten und verkauften ihn dort an Potifar, einen Hofbeamten des Pharao, den Befehlshaber der Leibwache." },
    ] },
    { number: 38, verses: [
      { number: 1, text: "Damals trennte sich Juda von seinen Brüdern und zog zu einem Mann aus Adullam*, namens Hira.", heading: "Juda und Tamar", footnotes: ["Adullam lag 26 km westlich von Jerusalem."] },
      { number: 2, text: "Dort sah er die Tochter eines Kanaaniters namens Schua. Er heiratete sie und schlief mit ihr." },
      { number: 3, text: "Sie wurde schwanger und brachte einen Sohn zur Welt. Juda nannte ihn Er." },
      { number: 4, text: "Dann wurde sie wieder schwanger und gebar einen zweiten Sohn; den nannte sie Onan." },
      { number: 5, text: "Ihren dritten Sohn nannte sie Schela. Zur Zeit seiner Geburt wohnten sie in Kesib*.", footnotes: ["Kesib lag 4 km südwestlich von Adullam; heute: Tel el-beda."] },
      { number: 6, text: "Juda verheiratete seinen ältesten Sohn Er mit einer Frau namens Tamar." },
      { number: 7, text: "Doch sein Erstgeborener tat, was Jahwe missfiel, und Jahwe ließ ihn sterben." },
      { number: 8, text: "Da sagte Juda zu Onan: \"Schlafe mit der Frau deines Bruders und vollziehe die Schwagerehe mit ihr. Du bist verpflichtet, deinem Bruder Nachkommen zu verschaffen.\"" },
      { number: 9, text: "Weil Onan wusste, dass das Kind nicht ihm gehören würde, ließ er jedes Mal, wenn er mit Tamar schlief, den Samen auf die Erde ausfließen und verderben. Er wollte seinem Bruder keine Nachkommen verschaffen." },
      { number: 10, text: "Das missfiel Jahwe, und er ließ auch Onan sterben." },
      { number: 11, text: "Da sagte Juda zu seiner Schwiegertochter Tamar: \"Bleib jetzt als Witwe im Haus deines Vaters, bis mein Sohn Schela alt genug ist.\" Denn er befürchtete, dass auch dieser sterben würde wie seine Brüder. So ging Tamar zur Familie ihres Vaters zurück." },
      { number: 12, text: "Jahre vergingen. Da starb Judas Frau, die Tochter Schuas. Als die Trauerzeit vorüber war, ging Juda mit seinem Freund Hira aus Adullam nach Timna* zu den Schafscherern.", footnotes: ["Timna liegt im Hügelland Judäas, etwa 35 km westlich von Jerusalem."] },
      { number: 13, text: "Als Tamar erfuhr, dass ihr Schwiegervater zur Schafschur nach Timna ging," },
      { number: 14, text: "legte sie ihre Witwenkleider ab, verhüllte sich mit einem Schleier und setzte sich an den Eingang von Enajim, das am Weg nach Timna liegt. Denn sie hatte bemerkt, dass Schela erwachsen geworden war und sie ihm doch nicht als Frau gegeben wurde." },
      { number: 15, text: "Als Juda sie so verschleiert erblickte, hielt er sie für eine Hure." },
      { number: 16, text: "Er ging zu ihr hin und sagte: \"Lass mich mit dir schlafen!\" Denn er merkte nicht, dass es seine Schwiegertochter war. \"Was gibst du mir, wenn ich dich lasse?\", erwiderte sie." },
      { number: 17, text: "\"Ich schicke dir ein Ziegenböckchen von meiner Herde\", versprach er. \"Gut\", sagte sie, \"du musst mir nur ein Pfand dalassen.\"" },
      { number: 18, text: "\"Was für ein Pfand willst du denn haben?\", fragte er. \"Dein Rollsiegel mit Schnur* und den Stab* in deiner Hand\", erwiderte sie. Er gab ihr, was sie wollte, und kam zu ihr, und sie wurde von ihm schwanger.", footnotes: ["Rollsiegel waren kleine Hohlzylinder, die an einer Schnur um den Hals getragen wurden. Mit ihnen wurden Tontäfelchen durch Abrollen in den weichen Ton signiert.", "Der Stab besaß einen geschnitzten Knauf mit dem Wahrzeichen des Besitzers."] },
      { number: 19, text: "Dann ging sie von dort weg, legte den Schleier ab und zog die Witwenkleider wieder an." },
      { number: 20, text: "Nun schickte Juda seinen Freund aus Adullam mit dem Ziegenböckchen los, um das Pfand einzulösen. Aber die Frau war nicht mehr zu finden." },
      { number: 21, text: "Er fragte die Leute im Ort: \"Wo ist denn die Geweihte*, die hier in Enajim am Weg saß?\" – \"Hier gibt es keine Geweihte\", sagten sie.", footnotes: ["Geweihte. Eine Tempelprostituierte im Dienst der Fruchtbarkeitsgöttin Astarte."] },
      { number: 22, text: "Da kehrte er zu Juda zurück und sagte: \"Ich habe sie nicht gefunden. Auch die Leute dort kennen keine Geweihte.\"" },
      { number: 23, text: "\"Soll sie die Sachen behalten\", sagte Juda, \"sonst machen wir uns noch zum Gespött. Ich habe ja das Böckchen geschickt, aber du hast sie nicht gefunden.\"" },
      { number: 24, text: "Etwa drei Monate später wurde Juda berichtet: \"Deine Schwiegertochter Tamar hat sich mit einem Mann eingelassen und ist sogar schwanger geworden!\" – \"Führt sie aus dem Ort hinaus!\", befahl Juda. \"Sie soll verbrannt werden.\"" },
      { number: 25, text: "Als man sie hinausführen wollte, schickte sie jemand zu ihrem Schwiegervater und ließ ihm sagen: \"Schau dir dieses Rollsiegel, die Schnur und den Stab genau an! Von dem Mann, dem das gehört, bin ich schwanger.\"" },
      { number: 26, text: "Juda sah sich die Sachen genau an und sagte: \"Sie ist im Recht, die Schuld liegt bei mir. Ich hätte sie meinem Sohn Schela zur Frau geben müssen.\" Er nahm sie bei sich auf, schlief aber nicht wieder mit ihr." },
      { number: 27, text: "Kurz vor der Entbindung stellte sich heraus, dass Tamar Zwillinge bekam." },
      { number: 28, text: "Während der Geburt streckte einer seine Hand heraus. Die Hebamme band einen roten Faden um das Handgelenk und sagte: \"Das ist der Erstgeborene.\"" },
      { number: 29, text: "Der zog seine Hand aber wieder zurück, und sein Bruder kam zuerst heraus. \"Mit was für einem Riss hast du dir den Vortritt verschafft!\", sagte die Hebamme. Deshalb nannte man ihn Perez, Riss." },
      { number: 30, text: "Erst dann kam sein Bruder heraus, an dessen Handgelenk der rote Faden war. Ihn nannte man Serach, Rotglanz." },
    ] },
    { number: 39, verses: [
      { number: 1, text: "Josef war von den Ismaëliten nach Ägypten gebracht worden. Sie verkauften ihn an einen ägyptischen Hofbeamten des Pharao namens Potifar. Er war der Befehlshaber der Leibwache.", heading: "Josef bei Potifar" },
      { number: 2, text: "Doch Jahwe stand Josef bei, sodass ihm alles gelang, was er tat. Er durfte im Haus seines ägyptischen Herrn bleiben." },
      { number: 3, text: "Und weil der Ägypter sah, dass Jahwe Josef beistand und ihm alles gelingen ließ," },
      { number: 4, text: "schenkte er ihm seine Gunst und machte ihn zu seinem persönlichen Diener. Er übergab ihm die Aufsicht über sein Hauswesen und vertraute ihm die Verwaltung seines ganzen Besitzes an." },
      { number: 5, text: "Und von diesem Zeitpunkt an segnete Jahwe das Haus des Ägypters. Wegen Josef ruhte der Segen Jahwes auf allem, was er besaß, im Haus und auf dem Feld." },
      { number: 6, text: "So überließ Potifar Josef alles, was er hatte, und kümmerte sich um nichts mehr, außer um sein eigenes Essen.Doch Josef war ein außergewöhnlich schöner Mann." },
      { number: 7, text: "So kam es, dass die Frau seines Herrn ein Auge auf ihn warf. \"Schlaf mit mir!\", sagte sie zu ihm." },
      { number: 8, text: "Doch er weigerte sich und erwiderte: \"Sieh doch, mein Herr verlässt sich auf mich und kümmert sich um nichts mehr, was im Haus vorgeht, und hat mir alles anvertraut, was ihm gehört." },
      { number: 9, text: "In diesem Haus gilt er nicht mehr als ich. Nichts hat er mir vorenthalten als nur dich, seine Frau. Wie könnte ich da ein so großes Unrecht begehen! Ich würde mich an Gott versündigen!\"" },
      { number: 10, text: "Obwohl sie Tag für Tag auf Josef einredete, mit ihr zu schlafen und ihr zu Willen zu sein, hörte er nicht auf sie." },
      { number: 11, text: "Einmal hatte Josef im Haus zu tun, und niemand von der Dienerschaft war dort." },
      { number: 12, text: "Da fasste sie ihn am Gewand. \"Komm mit mir ins Bett!\", drängte sie. Doch er riss sich los und flüchtete hinaus. Das Gewand blieb in ihrer Hand zurück." },
      { number: 13, text: "Als ihr bewusst wurde, dass er fort war, aber sein Gewand in ihrer Hand zurückgelassen hatte," },
      { number: 14, text: "rief sie die Dienerschaft herbei und sagte: \"Seht euch das an! Er hat uns diesen Hebräer ins Haus gebracht, der nun seinen Mutwillen mit uns treibt! Er ist zu mir gekommen und wollte mit mir schlafen. Da habe ich laut geschrien." },
      { number: 15, text: "Als er meinen Aufschrei hörte, ließ er sein Gewand bei mir liegen und rannte hinaus.\"" },
      { number: 16, text: "Sie ließ Josefs Gewand neben sich liegen, bis sein Herr nach Hause kam." },
      { number: 17, text: "Ihm erzählte sie dieselbe Geschichte: \"Der hebräische Sklave, den du uns ins Haus gebracht hast, ist zu mir gekommen, um seinen Mutwillen mit mir zu treiben." },
      { number: 18, text: "Als ich zu schreien anfing, ließ er sein Gewand neben mir liegen und rannte hinaus.\"" },
      { number: 19, text: "Als Potifar hörte, was sie seinem Sklaven vorwarf, packte ihn der Zorn." },
      { number: 20, text: "Er ließ Josef ergreifen und ins Gefängnis bringen. So kam Josef ins königliche Gefängnis." },
      { number: 21, text: "Aber Jahwe in seiner Treue stand Josef bei. Er sorgte dafür, dass der Gefängnisverwalter ihm sein Wohlwollen schenkte.", heading: "Josef im Gefängnis" },
      { number: 22, text: "Er übertrug Josef die Aufsicht über alle Gefangenen und alles, was man dort zu tun hatte." },
      { number: 23, text: "Der Gefängnisverwalter vertraute ihm völlig und gab ihm freie Hand, denn Jahwe stand Josef bei und ließ ihm alles gelingen, was er unternahm." },
    ] },
    { number: 40, verses: [
      { number: 1, text: "Bald darauf ließen sich der Mundschenk des Königs von Ägypten und sein Bäcker* etwas gegen ihren Herrn, den Pharao, zuschulden kommen.", heading: "Traumdeutung im Gefängnis", footnotes: ["Bäcker. Die Ägypter waren Feinschmecker und kannten 57 verschiedene Brotsorten und 38 verschiedene Arten von Kuchen."] },
      { number: 2, text: "Der wurde über seine beiden Beamten zornig" },
      { number: 3, text: "und ließ sie in das Gefängnis bringen, in dem auch Josef war. Der Befehlshaber der Leibwache hatte dort die Oberaufsicht." },
      { number: 4, text: "Dieser beauftragte Josef mit ihrer Bedienung. Als sie einige Zeit in Haft waren," },
      { number: 5, text: "hatte jeder von ihnen in derselben Nacht einen Traum, der für ihn von Bedeutung war." },
      { number: 6, text: "Als Josef am Morgen zu ihnen kam, bemerkte er gleich, dass sie schlecht aussahen." },
      { number: 7, text: "\"Warum lasst ihr heute den Kopf hängen?\", fragte er die Beamten des Pharao." },
      { number: 8, text: "\"Wir haben beide einen Traum gehabt\", erwiderten sie, \"aber es gibt niemand, der ihn deuten kann.\" Da sagte Josef: \"Deutungen sind Gottes Sache. Erzählt mir doch!\"" },
      { number: 9, text: "Da erzählte der oberste Mundschenk seinen Traum: \"Ich sah einen Weinstock vor mir." },
      { number: 10, text: "Er hatte drei Ranken. Kaum wuchs er, da trieb er auch schon seine Blüte, und seine Trauben reiften heran." },
      { number: 11, text: "Ich hatte den Becher des Pharao in der Hand, nahm die Trauben, presste sie in den Becher aus und gab ihn dem Pharao in die Hand.\"" },
      { number: 12, text: "Da sagte Josef zu ihm: \"Die Deutung ist so: Die drei Ranken sind drei Tage." },
      { number: 13, text: "In drei Tagen wird der Pharao dich herausholen und wieder in dein Amt einsetzen. Du wirst dem Pharao den Becher reichen wie früher, als du noch Mundschenk bei ihm warst." },
      { number: 14, text: "Aber vergiss mich nicht, wenn es dir gut geht. Erweise mir die Freundlichkeit und mache den Pharao auf mich aufmerksam, damit ich aus diesem Haus herauskomme." },
      { number: 15, text: "Man hat mich nämlich aus dem Land der Hebräer entführt, und auch hier habe ich nichts getan, wofür ich eingesperrt werden müsste.\"" },
      { number: 16, text: "Als der Oberbäcker merkte, dass Josef eine gute Deutung gegeben hatte, sagte er: \"Auch ich sah in meinem Traum etwas Ähnliches: Ich hatte drei Körbe mit Weißbrot auf meinem Kopf." },
      { number: 17, text: "Im obersten Korb lagen Backwaren für den Pharao. Da kamen Vögel und fraßen den Korb leer.\"" },
      { number: 18, text: "Josef sagte: \"Die Deutung ist so: Die drei Körbe sind drei Tage." },
      { number: 19, text: "In drei Tagen wird der Pharao dich herausholen und an einen Baum hängen lassen, und die Vögel werden dein Fleisch von dir wegfressen.\"" },
      { number: 20, text: "Am dritten Tag darauf hatte der Pharao Geburtstag. Er gab ein Fest für alle seine Beamten und lud dabei den obersten Mundschenk und den Oberbäcker vor." },
      { number: 21, text: "Den obersten Mundschenk setzte er wieder in sein Amt ein, sodass er ihm den Becher reichen durfte." },
      { number: 22, text: "Den Oberbäcker ließ er hängen. Es war genauso, wie Josef es ihnen gedeutet hatte." },
      { number: 23, text: "Aber der oberste Mundschenk dachte nicht mehr an Josef, er vergaß ihn." },
    ] },
    { number: 41, verses: [
      { number: 1, text: "So vergingen zwei Jahre. Da träumte der Pharao, dass er plötzlich am Nil stand.", heading: "Die Träume des Pharao" },
      { number: 2, text: "Aus dem Strom stiegen sieben schöne, wohlgenährte Kühe und weideten im Riedgras." },
      { number: 3, text: "Auf einmal stiegen sieben andere Kühe aus dem Strom, hässlich und mager, und stellten sich neben sie." },
      { number: 4, text: "Und die hässlichen, mageren Kühe fraßen die sieben schönen, wohlgenährten auf. Da erwachte der Pharao." },
      { number: 5, text: "Er schlief aber wieder ein und hatte noch einen Traum. Er sah, wie sieben dicke, volle Ähren auf einem einzigen Halm wuchsen." },
      { number: 6, text: "Nach ihnen wuchsen sieben andere Ähren auf, mager und vom Ostwind versengt." },
      { number: 7, text: "Und die mageren Ähren verschlangen die sieben dicken und vollen Ähren. Da erwachte der Pharao und merkte, dass es ein Traum war." },
      { number: 8, text: "Am Morgen war er sehr beunruhigt und ließ alle Gelehrten und Magier* Ägyptens rufen. Er erzählte ihnen, was er geträumt hatte, doch keiner von ihnen konnte es ihm deuten.", footnotes: ["Die Magier waren sternkundige Priester, die auch die Hieroglyphenschrift Ägyptens beherrschten. Sie standen in dem Ruf, die Zukunft voraussagen zu können."] },
      { number: 9, text: "Da sagte der oberste Mundschenk zum Pharao: \"Ich muss heute an meine Verfehlung erinnern." },
      { number: 10, text: "Als der Pharao über seine Diener aufgebracht war, ließ er mich im Gefängnis des Befehlshabers der Leibwache festsetzen, mich und den Oberbäcker." },
      { number: 11, text: "Dort hatte jeder von uns in einer Nacht einen Traum, der für ihn von Bedeutung war." },
      { number: 12, text: "Nun war dort ein junger Hebräer bei uns, ein Sklave des Befehlshabers der Leibwache. Ihm erzählten wir unsere Träume, und er deutete sie jedem von uns." },
      { number: 13, text: "Und so, wie er es uns gedeutet hatte, traf es auch ein: Ich wurde wieder in mein Amt eingesetzt und der andere wurde gehängt.\"" },
      { number: 14, text: "Da schickte der Pharao nach Josef. Man holte ihn schnell aus dem Gefängnis. Er ließ sich Haar und Bart scheren und wechselte die Kleidung. Dann trat er vor den Pharao." },
      { number: 15, text: "Der sagte zu Josef: \"Ich habe etwas geträumt, aber niemand kann mir sagen, was es bedeutet. Nun wurde mir von dir berichtet, dass du einen Traum nur hören musst, um ihn zu deuten.\"" },
      { number: 16, text: "\"Nein, nicht ich\", erwiderte Josef, \"Gott wird eine Antwort geben, die dem Pharao zum Guten ist.\"" },
      { number: 17, text: "Da sagte der Pharao: \"In meinem Traum stand ich am Nil" },
      { number: 18, text: "und sah sieben schöne, wohlgenährte Kühe aus dem Strom steigen und im Riedgras weiden." },
      { number: 19, text: "Auf einmal stiegen sieben andere Kühe aus dem Strom, dürr und sehr hässlich. Sie waren bis auf die Knochen abgemagert. Ich habe in ganz Ägypten noch nie so hässliche gesehen." },
      { number: 20, text: "Und die mageren, hässlichen Kühe fraßen die sieben wohlgenährten auf." },
      { number: 21, text: "Als sie diese verschlungen hatten, merkte man nichts davon, dass sie in ihren Bauch gekommen waren. Sie waren so hässlich wie zuvor. Da wachte ich auf." },
      { number: 22, text: "Danach sah ich im Traum, wie sieben dicke, volle Ähren auf einem einzigen Halm wuchsen." },
      { number: 23, text: "Nach ihnen wuchsen sieben andere Ähren auf, mager und vom Ostwind versengt." },
      { number: 24, text: "Und die mageren Ähren verschlangen die sieben schönen Ähren. Ich habe es den Magiern erzählt, aber keiner konnte mir sagen, was es bedeutet.\"" },
      { number: 25, text: "Da sagte Josef zum Pharao: \"Die beiden Träume bedeuten dasselbe. Gott hat dem Pharao mitgeteilt, was er tun will." },
      { number: 26, text: "Es ist eigentlich ein einziger Traum. Die sieben schönen Kühe und die sieben schönen Ähren bedeuten sieben Jahre." },
      { number: 27, text: "Auch die sieben mageren und hässlichen Kühe, die nach ihnen kamen, bedeuten sieben Jahre, genauso wie die sieben kümmerlichen, vom Ostwind versengten Ähren: Es werden sieben Hungerjahre sein." },
      { number: 28, text: "Wie ich es dem Pharao schon gesagt habe: Gott hat ihn sehen lassen, was er tun will." },
      { number: 29, text: "In den nächsten sieben Jahren wird in ganz Ägypten Überfluss herrschen." },
      { number: 30, text: "Aber dann kommen sieben Hungerjahre, wo aller Überfluss in Ägypten vergessen sein wird. Die Hungersnot wird das Land erschöpfen." },
      { number: 31, text: "Man wird nichts mehr von dem Überfluss merken, der vorher im Land war. Die Hungersnot wird sehr schwer sein." },
      { number: 32, text: "Dass der Pharao zweimal die gleiche Botschaft im Traum erhalten hat, bedeutet: Gott ist fest entschlossen, seinen Plan unverzüglich auszuführen.\"" },
      { number: 33, text: "\"Deshalb rate ich dem Pharao, sich nach einem einsichtigen und weisen Mann umzusehen, dem man die Verantwortung über Ägypten übertragen kann.", heading: "Josefs Rat" },
      { number: 34, text: "Dann sollte der Pharao in den sieben Jahren des Überflusses den fünften Teil der Ernte als Steuer erheben. Dazu sollte er Aufseher über das Land einsetzen," },
      { number: 35, text: "die das Getreide in den guten Jahren einsammeln und in den Städten als Nahrungsmittel speichern." },
      { number: 36, text: "Dann ist ein Vorrat da für die sieben Jahre des Hungers, die über Ägypten kommen werden, und das Land wird nicht an Hunger zugrunde gehen.\"" },
      { number: 37, text: "Die Rede gefiel dem Pharao und allen seinen Beratern.", heading: "Josef wird Herr über Ägypten" },
      { number: 38, text: "Er sagte zu ihnen: \"Werden wir noch so einen Mann wie diesen finden, in dem der Geist Gottes wohnt?\"" },
      { number: 39, text: "Zu Josef sagte er: \"Nachdem dich Gott das alles hat wissen lassen, gibt es keinen, der so einsichtig und weise wäre wie du." },
      { number: 40, text: "Du also sollst über mein Haus gesetzt sein, und deinem Wort soll sich mein ganzes Volk beugen; nur um den Thron will ich höher sein als du." },
      { number: 41, text: "Hiermit stelle ich dich über das ganze Land Ägypten!\"" },
      { number: 42, text: "Mit diesen Worten zog der Pharao seinen Siegelring vom Finger und steckte ihn Josef an. Dann ließ er ihn in feinstes ägyptisches Leinen kleiden und legte ihm eine goldene Halskette um." },
      { number: 43, text: "Er ließ ihn auf seinen zweiten Wagen steigen und vor ihm her ausrufen: \"Abrek, Achtung!*\" So machte er ihn zum Herrn über ganz Ägypten.", footnotes: ["Abrek. Vielleicht: Achtung! Die genaue Bedeutung des Begriffs ist bis heute unbekannt."] },
      { number: 44, text: "\"Ich bin und bleibe der Pharao\", sagte er zu Josef, \"aber ohne deine Erlaubnis soll keiner in Ägypten Hand oder Fuß rühren.\"" },
      { number: 45, text: "Er verlieh Josef den Namen Zafenat-Paneach* und gab ihm Asenat, die Tochter des Priesters von Heliopolis*, zur Frau. So wurde Josef Herr über ganz Ägypten.", footnotes: ["Zafenat-Paneach. Das heißt vielleicht: \"Gott spricht: Er lebt!\", oder nach einer anderen Deutung: \"Retter des Weltkreises\".", "Heliopolis, Sonnenstadt. Die Stadt lag 16 km nordöstlich des modernen Kairo. Dort stand ein Tempel für die Verehrung des Sonnengottes Ra."] },
      { number: 46, text: "Josef war dreißig Jahre alt, als er in den Dienst des Pharao, des Königs von Ägypten, trat. Bald darauf verließ er den Königshof und bereiste das ganze Land.", heading: "Josefs Macht über Ägypten" },
      { number: 47, text: "Die sieben Jahre des Überflusses brachten dem Land überreiche Ernten." },
      { number: 48, text: "Josef ließ während dieser Jahre alle Nahrungsmittel in die Städte bringen, das heißt, den Ertrag der Felder, die in ihrem Umkreis lagen." },
      { number: 49, text: "Josef speicherte Getreide wie Sand am Meer. Die Menge überstieg jedes Maß, sodass man mit Zählen und Messen aufhörte." },
      { number: 50, text: "Bevor die Hungerjahre herankamen, gebar Asenat, die Tochter des Priesters von Heliopolis, Josef zwei Söhne." },
      { number: 51, text: "Den Ältesten nannte Josef Manasse, Vergessen-Macher. \"Denn Gott\", sagte er, \"hat mich alle Not und den Verlust meines Vaterhauses vergessen lassen.\"" },
      { number: 52, text: "Den zweiten nannte er Efraïm, Fruchtbar-Macher. \"Denn Gott hat mich im Land meines Elends fruchtbar gemacht\", sagte er." },
      { number: 53, text: "Dann waren die sieben Jahre des Überflusses vorüber," },
      { number: 54, text: "und die Hungerjahre begannen, wie es Josef vorausgesagt hatte. In allen Ländern ringsherum herrschte Hungersnot, nur im Land Ägypten gab es Brot." },
      { number: 55, text: "Als nun der Hunger in Ägypten begann und die Menschen zum Pharao nach Brot schrien, ließ dieser verkünden: \"Wendet euch an Josef und tut, was er euch sagt!\"" },
      { number: 56, text: "Die Hungersnot erstreckte sich über das ganze Land. Da öffnete Josef die Kornspeicher und verkaufte den Ägyptern Getreide. Die Hungersnot aber wurde immer drückender in Ägypten." },
      { number: 57, text: "Und alle Welt kam, um bei Josef Getreide zu kaufen, denn auch in den anderen Ländern herrschte der Hunger." },
    ] },
    { number: 42, verses: [
      { number: 1, text: "Als Jakob erfuhr, dass es in Ägypten Getreide gab, sagte er zu seinen Söhnen: \"Was seht ihr euch einander an?", heading: "Josefs Brüder kommen nach Ägypten" },
      { number: 2, text: "Ich habe gehört, dass es in Ägypten Getreide gibt. Zieht hin und kauft uns welches, damit wir nicht verhungern!\"" },
      { number: 3, text: "Da zogen die zehn Brüder Josefs nach Ägypten." },
      { number: 4, text: "Nur Benjamin, den direkten Bruder Josefs, schickte Jakob nicht mit, denn er fürchtete, dass ihm etwas zustoßen könnte." },
      { number: 5, text: "So waren auch die Söhne Jakobs unter denen, die in Ägypten Getreide kaufen wollten, denn die Hungersnot herrschte auch in Kanaan." },
      { number: 6, text: "Josef war der Machthaber im Land; er war es, der den Getreideverkauf an das Volk überwachte. Als nun die Brüder Josefs kamen, warfen sie sich vor ihm auf den Boden." },
      { number: 7, text: "Er erkannte sie sofort, ließ sich aber nichts anmerken und redete hart mit ihnen. \"Wo kommt ihr her?\", fragte er sie. \"Aus dem Land Kanaan\", erwiderten sie. \"Wir möchten Getreide kaufen.\"" },
      { number: 8, text: "Josef erkannte zwar seine Brüder, aber sie begriffen nicht, wer er war." },
      { number: 9, text: "Da musste er daran denken, was er von ihnen geträumt hatte, und fuhr sie an: \"Spione seid ihr! Ihr seid nur gekommen, um das Land auszukundschaften!\"" },
      { number: 10, text: "\"Nein, Herr!\", riefen sie. \"Deine Diener sind nur gekommen, um Nahrungsmittel zu kaufen." },
      { number: 11, text: "Wir alle sind Söhne eines einzigen Mannes, ehrliche Leute. Deine Diener sind keine Spione!\"" },
      { number: 12, text: "\"Das glaube ich nicht!\", sagte er. \"Ihr wollt nur das Land auskundschaften!\"" },
      { number: 13, text: "Sie erwiderten: \"Deine Diener sind zwölf Brüder, Söhne eines einzigen Mannes aus dem Land Kanaan. Der Jüngste blieb bei unserem Vater und einer – er ist nicht mehr da.\"" },
      { number: 14, text: "\"Nein, ihr seid Spione, wie ich es gesagt habe!" },
      { number: 15, text: "Ich werde eure Behauptung prüfen! Und ich schwöre euch beim Leben des Pharao, dass ihr hier nicht wieder herauskommt, wenn ihr nicht euren jüngsten Bruder herbeischafft!" },
      { number: 16, text: "Einer von euch soll euren Bruder holen! Ihr anderen bleibt so lange gefangen. Dann wird man ja sehen, ob ihr die Wahrheit gesagt habt! Und wenn nicht: Beim Pharao, dann seid ihr doch Spione!\"" },
      { number: 17, text: "Dann ließ er sie für drei Tage ins Gefängnis schaffen." },
      { number: 18, text: "Doch am dritten Tag sagte er zu ihnen: \"Wenn ihr tut, was ich euch sage, bleibt ihr am Leben, denn ich fürchte Gott." },
      { number: 19, text: "Wenn ihr wirklich aufrichtig seid, dann lasst einen von euch hier im Gefängnis zurück. Ihr anderen kehrt heim und nehmt das Getreide für den Hunger in euren Häusern mit." },
      { number: 20, text: "Aber ihr müsst mir euren jüngsten Bruder herbringen, damit sich zeigt, ob ihr die Wahrheit gesagt habt, und ihr nicht sterben müsst!\" Sie gingen darauf ein," },
      { number: 21, text: "sagten aber zueinander: \"Das büßen wir für unseren Bruder. Wir sahen, welche Angst er hatte, als er um Erbarmen flehte. Aber wir haben nicht darauf gehört. Deshalb sind wir jetzt in diese Bedrängnis gekommen.\"" },
      { number: 22, text: "Ruben entgegnete ihnen: \"Ich habe euch doch gesagt: 'Vergreift euch nicht an dem Jungen!' Aber ihr wolltet nicht hören! Jetzt müssen wir für sein Blut büßen.\"" },
      { number: 23, text: "Sie ahnten nicht, dass Josef sie verstand, denn er hatte durch einen Dolmetscher mit ihnen gesprochen." },
      { number: 24, text: "Er wandte sich von ihnen ab und weinte. Als er wieder sprechen konnte, ließ er Simeon festnehmen und vor ihren Augen fesseln." },
      { number: 25, text: "Dann befahl er, ihre Säcke mit Getreide zu füllen und jedem sein Geld, das er bezahlt hatte, wieder oben hinein zu legen. Außerdem sollte man ihnen Verpflegung für die Reise mitgeben. Als das geschehen war," },
      { number: 26, text: "luden die Brüder das Getreide auf ihre Esel und zogen davon." },
      { number: 27, text: "Als einer von ihnen an dem Platz, wo sie übernachten wollten, seinen Sack öffnete, um dem Esel Futter zu geben, da sah er obenauf sein Geld liegen." },
      { number: 28, text: "\"Mein Geld ist zurückgegeben worden!\", berichtete er seinen Brüdern. \"Seht, hier im Sack!\" Da verließ sie der Mut. Erschrocken sahen sie sich an und sagten: \"Was hat Gott uns da angetan?\"" },
      { number: 29, text: "So kamen sie zu ihrem Vater Jakob zurück und berichteten ihm alles, was passiert war. Sie sagten:" },
      { number: 30, text: "\"Der Mann, der in Ägypten die Macht hat, fuhr uns hart an und behandelte uns wie Spione." },
      { number: 31, text: "Wir sagten zwar zu ihm: 'Wir sind ehrliche Leute, keine Spione." },
      { number: 32, text: "Zwölf Brüder sind wir, Söhne unseres Vaters. Einer von uns ist nicht mehr, und der Jüngste ist bei unserem Vater im Land Kanaan.'" },
      { number: 33, text: "Aber der Mann sagte zu uns: 'Ich werde sehen, ob ihr ehrliche Leute seid. Lasst einen eurer Brüder bei mir; ihr anderen kehrt heim und nehmt mit, was ihr für den Hunger in euren Häusern braucht." },
      { number: 34, text: "Aber euren jüngsten Bruder müsst ihr mir herbringen! Dann sehe ich, dass ihr keine Spione, sondern ehrliche Leute seid. Und dann werde ich euch euren anderen Bruder zurückgeben, und ihr könnt euch ungehindert im Land bewegen.'\"" },
      { number: 35, text: "Als sie ihre Säcke ausschütten wollten, fand jeder den Geldbeutel oben im Sack. Und als sie sahen, dass es ihre Beutel waren, erschraken sie und ihr Vater auch." },
      { number: 36, text: "Jakob rief: \"Ihr raubt mir meine Kinder! Josef ist weg, Simeon ist weg und Benjamin wollt ihr mir wegnehmen! Nichts bleibt mir erspart!\"" },
      { number: 37, text: "Da sagte Ruben zu seinem Vater: \"Wenn ich ihn dir nicht wiederbringe, darfst du meine beiden Söhne töten. Vertraue ihn mir an! Ich bringe ihn dir zurück!\"" },
      { number: 38, text: "\"Mein Sohn wird nicht mit euch ziehen\", sagte Jakob. \"Sein Bruder* ist tot, und ich habe nur noch ihn. Sollte ihm unterwegs etwas zustoßen, würdet ihr mein graues Haar mit Kummer ins Totenreich bringen.\"", footnotes: ["Bruder. Gemeint ist der von der gleichen Mutter geborene Josef."] },
    ] },
    { number: 43, verses: [
      { number: 1, text: "Der Hunger lastete schwer auf dem Land.", heading: "Juda bürgt für Benjamin" },
      { number: 2, text: "Das Getreide, das sie aus Ägypten geholt hatten, war inzwischen völlig aufgezehrt. Da sagte ihr Vater zu ihnen: \"Geht noch einmal hin und kauft uns etwas zu essen!\"" },
      { number: 3, text: "Juda entgegnete: \"Der Mann hat uns ernstlich verwarnt und gesagt: 'Kommt mir nicht unter die Augen ohne euren Bruder!'" },
      { number: 4, text: "Wenn du unseren Bruder mitgehen lässt, ziehen wir hin und kaufen Nahrung für dich;" },
      { number: 5, text: "wenn nicht, bleiben wir hier, denn der Mann hat gesagt: 'Kommt mir nicht unter die Augen ohne euren Bruder!'\"" },
      { number: 6, text: "Da sagte Israel: \"Warum habt ihr mir das Leid angetan und ihm verraten, dass ihr noch einen Bruder habt?\"" },
      { number: 7, text: "Sie erwiderten: \"Der Mann erkundigte sich genau nach uns und unserer Familie. 'Lebt euer Vater noch?', wollte er wissen. 'Habt ihr noch einen Bruder?' Da haben wir ihm gesagt, wie es sich verhält. Wir konnten doch nicht ahnen, dass er sagen würde: 'Bringt euren Bruder her!'\"" },
      { number: 8, text: "Da sagte Juda zu seinem Vater Israel: \"Schick den Jungen mit mir, damit wir aufbrechen können und nicht alle sterben müssen, wir und du und unsere Kinder." },
      { number: 9, text: "Ich selbst will Bürge für ihn sein. Von mir sollst du ihn zurückfordern. Mein Leben lang will ich vor dir schuldig sein, wenn ich ihn nicht lebend zu dir zurückbringe!" },
      { number: 10, text: "Hätten wir nicht so lange gezögert, wären wir schon zweimal wieder da.\"" },
      { number: 11, text: "Da sagte Israel, ihr Vater, zu ihnen: \"Wenn es also sein muss, nehmt ihn mit. Aber nehmt dem Mann ein Geschenk vom Besten unseres Landes mit: ein wenig Mastix, Tragakant und Ladanum*, ein wenig Traubenhonig*, Pistazien und Mandeln!", footnotes: ["Zu Mastix, Tragakant und Ladanum siehe 1. Mose 37,25.", "Traubenhonig war ein dick eingekochter Sirup, der mit Wasser vermischt auch als Wein getrunken wurde."] },
      { number: 12, text: "Nehmt auch den doppelten Geldbetrag mit und bringt das Geld, das sich oben in euren Säcken fand, eigenhändig zurück. Vielleicht war es ein Versehen." },
      { number: 13, text: "Und dann nehmt euren Bruder mit und kehrt zu dem Mann zurück!" },
      { number: 14, text: "El-Schaddai, der allmächtige Gott, lasse euch Erbarmen bei dem Mann finden, dass er euren anderen Bruder und Benjamin wieder mit euch heimkehren lässt. Und ich – wenn ich kinderlos sein soll, muss ich eben kinderlos sein.\"" },
      { number: 15, text: "Dann packten die Männer das doppelte Geld und die Geschenke ein und reisten mit Benjamin nach Ägypten. So kamen sie zu Josef.", heading: "Zweite Reise nach Ägypten" },
      { number: 16, text: "Als Josef Benjamin bei ihnen sah, sagte er zu seinem Hausverwalter: \"Lass die Männer ins Haus kommen, lass schlachten und zurichten, denn sie sollen bei mir zu Mittag essen!\"" },
      { number: 17, text: "Der gehorchte und führte die Männer zum Haus Josefs." },
      { number: 18, text: "Als sie merkten, dass sie dorthin geführt wurden, bekamen sie Angst und sagten zueinander: \"Das ist wegen des Geldes, das wieder in unsere Säcke geraten ist. Sie werden über uns herfallen, uns die Esel wegnehmen und uns zu Sklaven machen.\"" },
      { number: 19, text: "Darum wandten sie sich an den Verwalter Josefs und sprachen ihn noch vor dem Tor an." },
      { number: 20, text: "\"Bitte Herr\", sagten sie zu ihm, \"wir sind das vorige Mal wirklich nur hergekommen, um Getreide zu kaufen." },
      { number: 21, text: "Als wir dann aber in die Herberge kamen und unsere Säcke öffneten, fanden wir das ganze Geld, das wir bezahlt hatten, oben im Sack liegen. Darum haben wir es wieder mitgebracht" },
      { number: 22, text: "und dazu neues Geld, um Nahrungsmittel zu kaufen. Wir wissen nicht, wer uns das Geld wieder in die Säcke gelegt hat.\"" },
      { number: 23, text: "Doch er sagte: \"Friede sei mit euch! Habt keine Angst! Euer Gott, der Gott eures Vaters, hat euch einen Schatz in eure Säcke gegeben! Euer Geld habe ich erhalten.\" Dann brachte er Simeon zu ihnen" },
      { number: 24, text: "und führte sie alle miteinander in Josefs Haus. Er ließ ihnen Wasser bringen, damit sie ihre Füße waschen konnten, und ihren Eseln ließ er Futter geben." },
      { number: 25, text: "Sie legten inzwischen die Geschenke zurecht, bis Josef am Mittag käme, denn sie hatten gehört, dass sie dort essen sollten." },
      { number: 26, text: "Als Josef nach Hause kam, brachten sie ihm die Geschenke und warfen sich vor ihm auf den Boden." },
      { number: 27, text: "Josef erkundigte sich nach ihrem Wohlergehen und fragte dann: \"Geht es eurem alten Vater wohl, von dem ihr gesprochen habt? Lebt er noch?\"" },
      { number: 28, text: "Sie sagten: \"Es geht deinem Diener, unserem Vater, gut. Ja, er lebt noch.\" Und noch einmal warfen sie sich vor ihm nieder." },
      { number: 29, text: "Da erblickte er seinen Bruder Benjamin, den Sohn seiner eigenen Mutter. \"Ist das euer jüngster Bruder, von dem ihr gesprochen habt?\", fragte er und sagte: \"Gott segne dich, mein Sohn!\"" },
      { number: 30, text: "Dann lief er schnell hinaus, denn beim Anblick seines Bruders wurde er sehr bewegt und war nahe daran zu weinen. Er ging in sein Privatzimmer und weinte dort." },
      { number: 31, text: "Dann wusch er sich das Gesicht und kam zurück. Er nahm sich zusammen und befahl: \"Tragt das Essen auf!\"" },
      { number: 32, text: "Man trug das Essen auf, getrennt für ihn, für sie und für die anwesenden Ägypter. Ägypter essen nicht an einem Tisch mit Hebräern, denn das gilt ihnen als Gräuel." },
      { number: 33, text: "Die Brüder kamen vor Josef zu sitzen, genau nach ihrem Alter geordnet. Da sahen sie sich staunend an." },
      { number: 34, text: "Josef ließ ihnen von den Gerichten servieren, die auf seinem eigenen Tisch aufgetragen wurden. Die Portion Benjamins war fünfmal größer als die der anderen. Sie tranken mit ihm, bis sie in ausgelassener Stimmung waren." },
    ] },
    { number: 44, verses: [
      { number: 1, text: "Später befahl Josef seinem Hausverwalter: \"Füll die Säcke der Männer mit Getreide. Gib ihnen, so viel sie tragen können, und lege ihr Geld wieder oben hinein.", heading: "Der Silberkelch" },
      { number: 2, text: "In den Sack des Jüngsten legst du noch meinen Kelch dazu, den silbernen!\" Der Verwalter machte es genau, wie Josef es ihm befohlen hatte." },
      { number: 3, text: "Am Morgen, als es hell wurde, schickte man die Männer mit ihren Eseln nach Hause." },
      { number: 4, text: "Sie waren noch nicht weit von der Stadt entfernt, als Josef seinem Hausverwalter befahl: \"Los, jag ihnen nach! Wenn du sie eingeholt hast, sag ihnen: 'Warum habt ihr Gutes mit Bösem vergolten und den Kelch gestohlen?" },
      { number: 5, text: "Es ist doch der, aus dem mein Herr zu trinken pflegt und aus dem er Wahrsagungen* empfängt! Da habt ihr wirklich etwas Böses getan!'\"", footnotes: ["Wahrsagungen. Damit ist nicht gesagt, dass Josef wirklich Wahrsagerei betrieb, doch sollte er den Brüdern als echter ägyptischer Herrscher erscheinen, der so etwas zu tun pflegte."] },
      { number: 6, text: "Als der Verwalter sie erreicht hatte, stellte er sie mit diesen Worten zur Rede." },
      { number: 7, text: "\"Warum sagst du so etwas, Herr?\", erwiderten sie. \"Niemals hätten wir, deine Diener, so etwas getan!" },
      { number: 8, text: "Wir haben dir doch selbst das Geld, das wir oben in unseren Säcken fanden, aus Kanaan zurückgebracht! Wie kämen wir darauf, aus dem Haus deines Herrn Silber oder Gold zu stehlen?" },
      { number: 9, text: "Derjenige von deinen Dienern, bei dem der Kelch gefunden wird, soll sterben. Und uns alle kannst du dann zu deinen Sklaven machen, Herr!\"" },
      { number: 10, text: "\"Nun gut\", sagte der Verwalter, \"es sei, wie ihr gesagt habt. Aber nur der, bei dem sich der Kelch findet, soll mein Sklave sein. Ihr anderen geht frei aus.\"" },
      { number: 11, text: "Da hob jeder schnell seinen Sack auf die Erde und öffnete ihn." },
      { number: 12, text: "Der Verwalter durchsuchte sie. Beim Ältesten fing er an, und beim Jüngsten hörte er auf. Im Sack Benjamins fand sich der Kelch." },
      { number: 13, text: "Da rissen sie entsetzt ihre Obergewänder ein, beluden ihre Esel und kehrten in die Stadt zurück." },
      { number: 14, text: "So kam Juda mit seinen Brüdern ins Haus Josefs, der dort auf sie gewartet hatte. Sie warfen sich vor ihm auf die Erde." },
      { number: 15, text: "Josef herrschte sie an: \"Was habt ihr euch dabei gedacht? Wusstet ihr nicht, dass ein Mann wie ich wahrsagen kann?\"" },
      { number: 16, text: "\"Was sollen wir sagen, Herr?\", erwiderte Juda. \"Wie können wir uns nur rechtfertigen? Wir haben keine Worte! Gott hat die Schuld deiner Diener gefunden. Wir alle sind jetzt deine Sklaven, nicht nur der, bei dem der Kelch gefunden wurde!\"" },
      { number: 17, text: "Doch er erwiderte: \"Auf keinen Fall! Nur der, bei dem der Kelch gefunden wurde, soll mein Sklave sein; ihr anderen könnt in Frieden zu eurem Vater hinaufziehen.\"" },
      { number: 18, text: "Da trat Juda vor und sagte: \"Bitte, mein Herr, lass mich doch ein Wort zu dir reden und werde nicht zornig über deinen Diener, denn du bist mächtig wie der Pharao." },
      { number: 19, text: "Mein Herr fragte seine Diener: 'Habt ihr noch einen Vater oder Bruder?'" },
      { number: 20, text: "Und wir haben geantwortet: 'Ja, wir haben einen alten Vater und einen kleinen Bruder, der ihm noch im Alter geboren wurde. Dessen Bruder ist tot. So ist dies der einzige, der ihm von seiner Mutter geblieben ist. Und sein Vater hängt sehr an ihm.'" },
      { number: 21, text: "Da sagtest du zu deinen Dienern: 'Bringt ihn her zu mir. Ich will ihn mit eigenen Augen sehen!'" },
      { number: 22, text: "Aber wir sagten zu meinem Herrn: 'Es wäre der Tod für unseren Vater, wenn er den Jungen hergeben müsste. Er kann nicht von ihm weg.'" },
      { number: 23, text: "Doch du sagtest zu deinen Dienern: 'Ohne ihn dürft ihr mir nicht wieder unter die Augen kommen!'" },
      { number: 24, text: "Als wir dann zu deinem Diener, meinem Vater, heimgekommen waren, berichteten wir ihm alle Worte meines Herrn." },
      { number: 25, text: "Als unser Vater dann zu uns sagte: 'Kauft uns noch einmal etwas Brotgetreide!'," },
      { number: 26, text: "wandten wir ein: 'Wir können so nicht reisen! Wir brechen erst auf, wenn unser jüngster Bruder bei uns ist, denn ohne ihn dürfen wir dem Mann nicht unter die Augen kommen.'" },
      { number: 27, text: "Da sagte mein Vater zu uns: 'Ihr wisst, dass meine Frau mir nur zwei Söhne geboren hat." },
      { number: 28, text: "Der eine ist fort von mir; ein Raubtier muss ihn zerrissen haben, und ich habe ihn bis heute nicht wieder gesehen." },
      { number: 29, text: "Wenn ihr nun auch den anderen von mir wegnehmt, und es stößt ihm unterwegs etwas zu, dann würdet ihr mein graues Haar mit Kummer ins Totenreich bringen.'" },
      { number: 30, text: "Wenn ich nun zu deinem Diener, meinem Vater, zurückkäme und der Junge, an dem er so hängt, wäre nicht mehr bei uns," },
      { number: 31, text: "dann würde er sterben, wenn er sähe, dass der Junge nicht mehr da ist. Dann hätten deine Diener das graue Haar unseres Vaters mit Kummer ins Totenreich gebracht." },
      { number: 32, text: "Denn dein Diener hat bei meinem Vater für den Jungen gebürgt und gesagt: 'Wenn ich ihn nicht zu dir zurückbringe, will ich mein Leben lang vor meinem Vater schuldig sein.'" },
      { number: 33, text: "Erlaube mir doch, anstelle des Jungen als dein Sklave hier zu bleiben. Aber ihn lass mit seinen Brüdern heimkehren!" },
      { number: 34, text: "Denn wie könnte ich ohne ihn zu meinem Vater zurückkommen! Dann müsste ich das Unglück, das meinen Vater trifft, mit ansehen.\"" },
    ] },
    { number: 45, verses: [
      { number: 1, text: "Da konnte Josef sich vor seinen Leuten nicht länger beherrschen. Schnell schickte er sie alle hinaus. So stand niemand mehr bei ihm, als er sich seinen Brüdern zu erkennen gab.", heading: "Josef gibt sich zu erkennen" },
      { number: 2, text: "Er weinte so laut, dass die Ägypter es hörten; auch am Hof des Pharao hörte man bald davon." },
      { number: 3, text: "\"Ich bin Josef!\", sagte er zu seinen Brüdern. \"Lebt mein Vater noch?\" Seine Brüder aber brachten kein Wort heraus; fassungslos standen sie vor ihm." },
      { number: 4, text: "Da sagte Josef zu seinen Brüdern: \"Kommt doch her!\" Und als sie herantraten, sagte er: \"Ich bin Josef, euer Bruder, den ihr nach Ägypten verkauft habt." },
      { number: 5, text: "Erschreckt nicht und macht euch deswegen keine Vorwürfe! Denn Gott hat mich vor euch hierher geschickt, um viele Leben zu erhalten." },
      { number: 6, text: "Denn die Hungersnot ist schon zwei Jahre im Land, und noch fünf Jahre lang wird es kein Pflügen und Ernten geben." },
      { number: 7, text: "Doch Gott hat mich vor euch her geschickt, um euch Fortbestand auf der Erde zu geben und euch als eine große Schar von Geretteten am Leben zu erhalten." },
      { number: 8, text: "Nicht ihr habt mich hierher gebracht, sondern Gott. Er hat mich zum Vater* für den Pharao gemacht, zum Herrn für seinen Hof und zum Herrscher über das ganze Land Ägypten.", footnotes: ["Vater meint hier offenbar einen Berater des Pharao."] },
      { number: 9, text: "Macht euch schnell auf den Weg zu meinem Vater und sagt ihm:'So spricht dein Sohn Josef: Gott hat mich zum Herrn von ganz Ägypten gemacht. Komm her zu mir, lass dich nicht aufhalten!" },
      { number: 10, text: "Du sollst im Gebiet von Goschen* wohnen, ganz in meiner Nähe. Bring deine Kinder und Enkel mit, deine Schafe, deine Rinder und alles, was du hast.", footnotes: ["Goschen war ein sehr fruchtbares Gebiet östlich vom Nildelta."] },
      { number: 11, text: "Ich will dich dort versorgen, damit du mit deiner Familie nicht in Armut gerätst, denn die Hungersnot dauert noch fünf Jahre.'" },
      { number: 12, text: "Ihr seht es doch mit eigenen Augen, dass ich es bin, der mit euch redet, und auch du, mein Bruder Benjamin!" },
      { number: 13, text: "Ihr müsst meinem Vater von meiner Stellung hier in Ägypten erzählen. Berichtet ihm alles, was ihr gesehen habt! Und beeilt euch und bringt meinen Vater zu mir her!\"" },
      { number: 14, text: "Dann fiel er seinem Bruder Benjamin um den Hals, und beide weinten." },
      { number: 15, text: "Danach küsste er unter Tränen auch seine anderen Brüder. Erst dann fanden diese ihre Sprache wieder und redeten mit ihm." },
      { number: 16, text: "\"Josefs Brüder sind gekommen!\" Als diese Nachricht den Hof des Pharao erreichte, löste sie bei ihm und seinen Beamten Freude aus." },
      { number: 17, text: "Der Pharao sagte zu Josef: \"Sag deinen Brüdern, sie sollen ihre Tiere beladen, ins Land Kanaan reisen" },
      { number: 18, text: "und euren Vater und eure Familien herholen. Ich will euch das Beste geben, was Ägypten zu bieten hat, ihr sollt die besten Erzeugnisse des Landes genießen." },
      { number: 19, text: "Du bist berechtigt, sie anzuweisen: 'Nehmt euch Wagen aus Ägypten für eure Frauen und Kinder mit und lasst euren Vater aufsteigen und kommt!" },
      { number: 20, text: "Bedauert nicht den Verlust eures Hausrats, denn das Beste, was Ägypten zu bieten hat, soll euch gehören.'\"" },
      { number: 21, text: "Die Söhne Israels machten es so. Nach Weisung des Pharao gab Josef ihnen Wagen und Verpflegung für die Reise mit." },
      { number: 22, text: "Jedem schenkte er ein Festgewand. Doch Benjamin gab er fünf Festgewänder und 300 Silberstücke dazu." },
      { number: 23, text: "Seinem Vater schickte er zehn Esel, beladen mit dem Besten Ägyptens, und zehn Eselinnen, beladen mit Getreide, Brot und anderen Nahrungsmitteln für die Reise." },
      { number: 24, text: "Dann verabschiedete er seine Brüder, und sie zogen los. \"Streitet euch nicht auf dem Weg!\", rief er ihnen nach." },
      { number: 25, text: "Sie zogen also von Ägypten hinauf und kamen nach Kanaan zu ihrem Vater Jakob." },
      { number: 26, text: "\"Josef lebt!\", riefen sie. \"Er ist sogar der Herr über ganz Ägypten!\" Aber sein Herz blieb kalt. Er glaubte ihnen nicht." },
      { number: 27, text: "Da erzählten sie ihm ausführlich alles, was Josef ihnen aufgetragen hatte. Und als ihr Vater die Wagen sah, die Josef mitgeschickt hatte, um ihn zu holen, kam wieder Leben in ihn." },
      { number: 28, text: "\"Genug!\", rief er. \"Mein Sohn Josef lebt noch! Ich will hin und ihn sehen, bevor ich sterbe!\"" },
    ] },
    { number: 46, verses: [
      { number: 1, text: "Israel brach auf mit allem, was er hatte. Als er nach Beerscheba kam, schlachtete er einige Tiere und brachte sie dem Gott seines Vaters Isaak als Opfer.", heading: "Jakobs Übersiedlung nach Ägypten" },
      { number: 2, text: "In der Nacht sprach Gott zu ihm in einer Vision: \"Jakob! Jakob!\" – \"Ja?\", antwortete er." },
      { number: 3, text: "\"Ich bin Gott, der Gott deines Vaters. Hab keine Angst, nach Ägypten zu ziehen, denn ich lasse dich dort zu einem großen Volk werden." },
      { number: 4, text: "Ich selbst ziehe mit dir nach Ägypten und werde dich auch wieder hier heraufbringen. Und Josef wird dir die Augen zudrücken.\"" },
      { number: 5, text: "Dann brach Jakob von Beerscheba auf. Seine Söhne setzten ihn und ihre Kinder und Frauen auf die Wagen, die der Pharao mitgeschickt hatte, um sie zu holen." },
      { number: 6, text: "Mit ihren Herden und allem, was sie in Kanaan erworben hatten, kamen sie nach Ägypten, Jakob und seine ganze Familie," },
      { number: 7, text: "seine Söhne und Töchter, seine Enkel und Enkelinnen. Seine ganze Nachkommenschaft brachte Israel mit nach Ägypten." },
      { number: 8, text: "Es folgen die Namen der Söhne Israels, die nach Ägypten kamen: Zunächst Jakob selbst und sein Sohn Ruben, der Erstgeborene." },
      { number: 9, text: "Dann dessen Söhne Henoch, Pallu, Hezron und Karmi." },
      { number: 10, text: "Simeon und seine Söhne Jemuël, Jamin, Ohad, Jachin, Zohar und Schaul, der Sohn einer Kanaaniterin." },
      { number: 11, text: "Levi und seine Söhne Gerschon, Kehat und Merari." },
      { number: 12, text: "Juda und seine Söhne Er, Onan, Schela, Perez und Serach; die beiden ersten waren schon in Kanaan gestorben; Perez hatte zwei Söhne: Hezron und Hamul." },
      { number: 13, text: "Issachar und seine Söhne Tola, Puwa, Jaschub und Schimron." },
      { number: 14, text: "Sebulon und seine Söhne Sered, Elon und Jachleel." },
      { number: 15, text: "Das sind die Nachkommen, die Lea dem Jakob noch in Mesopotamien geboren hatte, dazu eine Tochter: Dina. Es waren also 33 Söhne und Töchter." },
      { number: 16, text: "Die Söhne Gads waren Zifjon, Haggi, Schuni, Ezbon, Eri, Arod und Areli." },
      { number: 17, text: "Die Söhne Aschers: Jimna, Jischwa, Jischwi und Beria, dazu seine Tochter Serach; Beria hatte zwei Söhne: Heber und Malkiël." },
      { number: 18, text: "Das sind die Nachkommen der Sklavin Silpa, die Laban seiner Tochter Lea mitgegeben hatte: 16 Personen." },
      { number: 19, text: "Von Jakobs Frau Rahel stammen Josef und Benjamin." },
      { number: 20, text: "Von Josef stammen Manasse und Efraïm, die ihm Asenat, die Tochter des Priesters Potifera aus Heliopolis, in Ägypten geboren hatte." },
      { number: 21, text: "Die Söhne Benjamins waren Bela, Becher, Aschbel, Gera, Naaman, Ehi, Rosch, Muppim, Huppim und Ard." },
      { number: 22, text: "Die Nachkommen Rahels waren also 14 Personen." },
      { number: 23, text: "Dans Sohn hieß Huschim." },
      { number: 24, text: "Naftalis Söhne waren Jachzeel, Guni, Jezer und Schillem." },
      { number: 25, text: "Das sind die Nachkommen der Sklavin Bilha, die Laban seiner Tochter Rahel mitgegeben hatte: sieben Personen." },
      { number: 26, text: "Die Gesamtzahl der Personen, die mit Jakob nach Ägypten kamen und von ihm abstammten, betrug ohne die Frauen der Söhne Jakobs 66 Personen." },
      { number: 27, text: "Dazu kommen die Söhne Josefs, die ihm in Ägypten geboren wurden, zwei Personen. Insgesamt waren 70 Personen* von der Familie Jakobs nach Ägypten gekommen.", footnotes: ["70 Personen. Zu den 66 Personen kommen also noch die beiden Söhne Josefs und Jakob und Josef selbst hinzu. Die LXX, fügt in Vers 20 noch weitere fünf Personen hinzu: einen Sohn und einen Enkel von Manasse und zwei Söhne und einen Enkel von Ephraim, sodass nach der LXX, auf die Stephanus sich in Apostelgeschichte 7,14 bezieht, die Familie Jakobs 75 Personen umfasste."] },
      { number: 28, text: "So kam Jakob in das Gebiet von Goschen. Er hatte Juda zu Josef vorausgeschickt, damit dieser die entsprechenden Anweisungen gebe und sie nach Goschen ziehen könnten." },
      { number: 29, text: "Josef ließ seinen Wagen anspannen und zog seinem Vater Israel nach Goschen entgegen. Als er ihn zu Gesicht bekam, fiel er ihm um den Hals und weinte lange." },
      { number: 30, text: "\"Nun will ich gerne sterben!\", sagte Israel zu ihm, \"nachdem ich dich wiedergesehen habe und weiß, dass du noch am Leben bist.\"" },
      { number: 31, text: "Dann sagte Josef zu seinen Brüdern und ihren Familien: \"Ich gehe jetzt zum Pharao und werde ihm sagen: 'Die ganze Familie meines Vaters, die im Land Kanaan lebte, ist zu mir gekommen." },
      { number: 32, text: "Die Männer sind Schafhirten, Viehzüchter seit eh und je. Sie haben ihren ganzen Besitz, ihre Schafe, Ziegen und Rinder mitgebracht.'" },
      { number: 33, text: "Wenn der Pharao euch dann zu sich rufen lässt und euch nach eurer Tätigkeit fragt," },
      { number: 34, text: "sagt ihm: 'Deine Diener sind von Jugend an Viehzüchter gewesen wie unsere Vorfahren.' Dann könnt ihr hier in Goschen bleiben. Den Ägyptern sind Kleinviehhirten nämlich ein Gräuel.\"" },
    ] },
    { number: 47, verses: [
      { number: 1, text: "Josef ging zum Pharao und berichtete ihm: \"Mein Vater und meine Brüder sind aus dem Land Kanaan hier eingetroffen. Sie haben ihren ganzen Besitz, ihr Kleinvieh und ihre Rinder mitgebracht und sind in Goschen angekommen.\"" },
      { number: 2, text: "Er hatte fünf Männer aus dem Kreis seiner Brüder mitgebracht und stellte sie dem Pharao vor." },
      { number: 3, text: "Der fragte sie: \"Was ist eure Tätigkeit?\" – \"Deine Diener sind Kleinviehhirten wie schon unsere Vorfahren.\"" },
      { number: 4, text: "Weiter sagten sie: \"Wir möchten als Gäste im Land bleiben, denn in Kanaan gibt es wegen der Dürre keine Weiden mehr für unsere Herden. Erlaube uns doch, im Gebiet von Goschen zu siedeln!\"" },
      { number: 5, text: "Da sagte der Pharao zu Josef: \"Dein Vater und deine Brüder sind also zu dir gekommen." },
      { number: 6, text: "Ägypten steht dir offen. Lass sie im besten Teil des Landes wohnen. Sie können in Goschen bleiben. Und wenn tüchtige Leute unter ihnen sind, dann setze sie als Oberhirten für mein eigenes Vieh ein.\"" },
      { number: 7, text: "Dann brachte Josef auch seinen Vater Jakob hinein und stellte ihn dem Pharao vor. Und Jakob segnete den Pharao." },
      { number: 8, text: "Dieser fragte ihn: \"Wie hoch ist eigentlich die Zahl deiner Lebensjahre?\"" },
      { number: 9, text: "\"130 Jahre lebe ich als Fremder auf dieser Erde\", erwiderte Jakob. \"Die Zeit meines Lebens war kurz und mühselig und reicht nicht an die Lebensjahre meiner Väter heran, die ebenso heimatlos auf der Erde lebten.\"" },
      { number: 10, text: "Mit einem Segenswunsch verabschiedete sich Jakob vom Pharao." },
      { number: 11, text: "Josef wies seinem Vater und seinen Brüdern Wohnsitze an und gab ihnen Grundbesitz im Land Ägypten, im besten Teil des Landes in der Gegend von Ramses*, wie der Pharao befohlen hatte.", footnotes: ["Ramses war Stadt im östlichen Nildelta, etwa 30 km südlich von Tanis/Zoan."] },
      { number: 12, text: "Er sorgte dafür, dass seine Angehörigen entsprechend ihrer Kopfzahl Nahrungsmittel bekamen." },
      { number: 13, text: "Im ganzen Land gab es kein Brot, und die Hungersnot wurde immer schlimmer. Auch das Land Ägypten war vom Hunger erschöpft, Kanaan ebenso.", heading: "Josefs Verwaltung von Ägypten" },
      { number: 14, text: "Durch das Getreide, das Josef verkaufte, brachte er schließlich alles Geld zusammen, das in beiden Ländern in Umlauf war, und übergab es dem Pharao." },
      { number: 15, text: "Als dann in Ägypten und Kanaan das Geld ausgegangen war, kamen die Ägypter zu Josef und sagten: \"Schaff uns Brot her! Oder sollen wir hier vor deinen Augen verhungern? Wir haben kein Geld mehr.\"" },
      { number: 16, text: "Da sagte Josef: \"Bringt mir statt Geld euer Vieh, dann gebe ich euch dafür Getreide.\"" },
      { number: 17, text: "Da brachten sie ihr Vieh zu Josef, ihre Pferde, ihre Schaf- und Rinderherden, ihre Esel; und Josef versorgte sie das ganze Jahr über mit Nahrung." },
      { number: 18, text: "Im folgenden Jahr kamen sie wieder und sagten: \"Wir können es dir, unserem Herrn, nicht verschweigen: Unser Geld ist ausgegangen, unser Vieh ist in deinem Besitz. Wir haben nur noch uns selbst und unsere Felder." },
      { number: 19, text: "Sollen wir hier vor deinen Augen sterben – so wie unser Ackerland stirbt? Kaufe uns und unsere Felder für den Pharao, dann wollen wir auf unserem Ackerland für ihn arbeiten. Aber gib uns Getreide, damit wir leben können und Saatgut für unsere Felder haben, und damit das Ackerland nicht verödet.\"" },
      { number: 20, text: "So kaufte Josef das ganze Land auf und machte es zum Eigentum des Pharao. Weil die Hungersnot so groß war, musste jeder Ägypter sein Ackerland verkaufen." },
      { number: 21, text: "Von einem Ende Ägyptens bis zum anderen ließ Josef das Volk dazu in die Städte kommen*.", footnotes: ["Volk ... kommen. Offenbar, um die Grundstücksangelegenheiten zu regeln und Saatgut zu erhalten. Die LXX liest hier: ... machte Josef das Volk zu dessen Sklaven."] },
      { number: 22, text: "Nur das Land der Priester kaufte er nicht auf, denn die Priester lebten von einem festen Einkommen, das der Pharao für sie festgesetzt hatte; deshalb mussten sie ihr Land nicht verkaufen." },
      { number: 23, text: "Zum Volk sagte Josef: \"Heute habe ich euch und euer Ackerland für den Pharao erworben. Hier habt ihr Saatgut, bestellt eure Felder!" },
      { number: 24, text: "Von der Ernte müsst ihr den fünften Teil an den Pharao abgeben*, die anderen vier Teile sind für neues Saatgut und zur Ernährung für euch und eure Familien bestimmt.\"", footnotes: ["fünften Teil ... abgeben. Josef machte die Bevölkerung nicht zu Sklaven, sondern zu Pächtern. 20 Prozent Abgaben waren keinesfalls überhöht, andernorts lagen sie bei 40 Prozent oder sogar 60 Prozent."] },
      { number: 25, text: "Sie sagten: \"Du hast uns das Leben erhalten! Wenn wir Gunst vor dir finden, wollen wir gern Sklaven des Pharao sein.\"" },
      { number: 26, text: "Josef machte es zum Gesetz, dass ein Fünftel der Ernte dem Pharao abzuliefern war. Das gilt bis zum heutigen Tag. Nur das Land der Priester kam nicht an den Pharao." },
      { number: 27, text: "So wohnte Israel* also in Ägypten. Die Israeliten machten sich im Gebiet von Goschen ansässig, waren fruchtbar und vermehrten sich sehr.", heading: "Jakobs letzter Wille", footnotes: ["Israel. Der Name, den Jakob von Gott erhalten hatte, geht hier schon auf seine Nachkommen über."] },
      { number: 28, text: "Jakob lebte noch 17 Jahre in Ägypten. Er wurde 147 Jahre alt." },
      { number: 29, text: "Als das Ende nahte, ließ er seinen Sohn Josef rufen und sagte zu ihm: \"Erweise mir die Gunst und schwöre bei meiner Nachkommenschaft*, dass du mit Liebe und Treue an mir handelst und mich nicht in Ägypten begräbst!", footnotes: ["Nachkommenschaft. Siehe Fußnote zu 1. Mose 24,2."] },
      { number: 30, text: "Wenn ich im Tod mit meinen Vorfahren vereint bin, dann bring mich aus Ägypten weg und begrabe mich bei meinen Vorfahren!\" Josef versprach ihm: \"Ich werde tun, was du gesagt hast!\"" },
      { number: 31, text: "\"Schwöre es mir!\", sagte Jakob, und Josef schwor es ihm. Dann verneigte sich Israel ehrfürchtig zum Kopfende seines Bettes hin.*", footnotes: ["Es sollte deutlich werden, dass er sich vor Gott (siehe 1. Könige 1,47-48) verneigt, nicht vor seinem Sohn Josef."] },
    ] },
    { number: 48, verses: [
      { number: 1, text: "Einige Zeit danach sagte man Josef: \"Dein Vater ist krank.\" Da nahm er seine beiden Söhne Manasse und Efraïm und machte sich auf den Weg.", heading: "Jakobs Segen" },
      { number: 2, text: "Als Jakob gesagt wurde: \"Dein Sohn Josef kommt zu dir\", nahm er alle seine Kraft zusammen und setzte sich im Bett auf." },
      { number: 3, text: "Er sagte zu Josef: \"El-Schaddai, der allmächtige Gott, erschien mir in Lus im Land Kanaan. Er segnete mich" },
      { number: 4, text: "und sagte: 'Ich will dich fruchtbar machen und vermehren. Zu einer ganzen Schar von Völkern sollst du werden. Und dieses Land werde ich deiner Nachkommenschaft für alle Zeiten zum Besitz geben.'" },
      { number: 5, text: "Deine beiden Söhne, die dir hier in Ägypten geboren wurden, bevor ich ins Land kam, nehme ich als meine Söhne an. Efraïm und Manasse sollen genauso viel gelten wie Ruben und Simeon." },
      { number: 6, text: "Aber die Kinder, die dir später geboren werden, gelten als deine Nachkommen. Sie bekommen jedoch Anteil am Landbesitz ihrer älteren Brüder." },
      { number: 7, text: "Und ich – als ich aus Mesopotamien ins Land Kanaan zurückkam, starb Rahel kurz vor Efrata. Und ich begrub sie dort am Weg nach Efrata, das jetzt Bethlehem heißt.\"" },
      { number: 8, text: "Israel bemerkte Josefs Söhne und fragte: \"Wen hast du da mitgebracht?\"" },
      { number: 9, text: "\"Das sind die Söhne, die Gott mir hier geschenkt hat\", erwiderte Josef. \"Bring sie her\", sagte Jakob, \"ich will sie segnen!\"" },
      { number: 10, text: "Seine Augen waren altersschwach geworden, und er konnte nicht mehr sehen. Josef ließ seine Söhne zu ihm herantreten und Israel küsste und umarmte sie." },
      { number: 11, text: "Dann sagte er zu Josef: \"Ich hätte nie geglaubt, dich wiederzusehen, und nun hat Gott mich sogar deine Nachkommen sehen lassen!\"" },
      { number: 12, text: "Josef nahm sie von seinen Knien weg und beugte sich nieder, mit dem Gesicht bis zur Erde." },
      { number: 13, text: "Dann nahm er Efraïm an die rechte Hand – von Jakob aus gesehen links – und Manasse an die linke – von Jakob aus gesehen rechts – und brachte sie so zu seinem Vater." },
      { number: 14, text: "Doch Israel kreuzte seine Hände und legte seine rechte Hand auf Efraïms Kopf – obwohl er der Jüngere war – und die linke auf den Kopf Manasses, obwohl dies der Erstgeborene war." },
      { number: 15, text: "Dann segnete er Josef und sagte:\"Gott, vor dem meine Väter Abraham und Isaak lebten, / Gott, der mein Leben lang und bis heute mein Hirt ist," },
      { number: 16, text: "der Engel, der mich von allem Übel erlöst hat, / segne die Jungen. / In ihnen lebe mein Name weiter / und der meiner Väter Abraham und Isaak. Zahlreich sollen sie werden / mitten im Land!\"" },
      { number: 17, text: "Josef hatte gesehen, dass sein Vater die rechte Hand auf Efraïms Kopf legte. Das missfiel ihm und er nahm sie, um sie auf Manasses Kopf zu legen." },
      { number: 18, text: "\"Nicht so, mein Vater!\", sagte er. \"Dies ist der Erstgeborene. Leg deine rechte Hand auf ihn!\"" },
      { number: 19, text: "Aber sein Vater weigerte sich und sagte: \"Ich weiß es, mein Sohn, ich weiß es. Auch er wird zu einem Volk werden, auch er wird groß sein. Aber sein jüngerer Bruder wird noch größer werden als er. Seine Nachkommen werden zu einer Menge von Völkern.\"" },
      { number: 20, text: "So segnete er sie an jenem Tag und sagte zu Josef: \"Mit dir wird Israel sich segnen und sagen: 'Gott mache dich wie Efraïm und Manasse!'\" So stellte er Efraïm vor Manasse." },
      { number: 21, text: "Dann sagte Israel zu Josef: \"Ich sterbe jetzt. Doch Gott wird bei euch sein und euch zurückführen in das Land eurer Väter." },
      { number: 22, text: "Und ich gebe dir ein Stück Land* über deine Brüder hinaus, das ich den Amoritern* mit Schwert und Bogen* weggenommen habe.\"", footnotes: ["ein Stück Land. Wörtlich: Schulter, hebräisch: schechäm. Es meint das Stück Land bei Sichem, das Jakob nach 1. Mose 33,18 gehörte und wo Josef nach Josua 24,32 später endgültig bestattet wurde.", "Amoriter. Siehe Fußnote zu 1. Mose 14,7.", "Schwert und Bogen. Davon wird sonst nichts berichtet. Wahrscheinlich ist es hier im übertragenen Sinn zu verstehen: mit eigener Kraft."] },
    ] },
    { number: 49, verses: [
      { number: 1, text: "Dann rief Jakob alle seine Söhne zu sich und sagte:\"Versammelt euch, damit ich verkünde, / was euch begegnet in künftiger Zeit.", heading: "Jakob segnet seine zwölf Söhne" },
      { number: 2, text: "Kommt und hört, ihr Jakobssöhne, / hört auf euren Vater Israel!" },
      { number: 3, text: "Ruben, du mein Erstgeborener, / meine Stärke und der Erstling meiner Kraft! / Erster an Hoheit und Erster an Macht." },
      { number: 4, text: "Du brodeltest wie Wasser. / Du sollst nicht der Erste sein, / denn du bestiegst das Bett deines Vaters, / da hast du es entweiht, / du, der mein Lager bestieg!" },
      { number: 5, text: "Die Brüder Simeon und Levi, / ihre Waffen sind Werkzeuge der Gewalt." },
      { number: 6, text: "Mit ihren Plänen habe ich nichts zu tun, / meine Ehre ist nicht eins mit ihrer Schar, / denn im Zorn haben sie Männer gemordet, / mutwillig Stiere gelähmt." },
      { number: 7, text: "Verflucht sei ihr zorniges Wüten, / weil es roh und grausam ist! / Ich teile sie unter Jakob auf, / ich zerstreue sie in Israel." },
      { number: 8, text: "Dich, Juda, preisen deine Brüder, / weil du den Feind im Nacken packst! / Dir beugen sich die Söhne deines Vaters." },
      { number: 9, text: "Du gleichst dem jungen Löwen, Juda. / Vom Raub kommst du, mein Sohn, herauf. / Er kauert hingestreckt, / dem Löwen und der Löwin gleich. / Wer wagt ihn aufzustören?" },
      { number: 10, text: "Nie weicht das Zepter von Juda, / der Herrscherstab von seinem Schoß, / bis der kommt, dem er gehört. / Und ihm werden die Völker gehorchen." },
      { number: 11, text: "Am Weinstock bindet er sein Reittier fest, / sein Eselsfohlen an der Edelrebe*. Sein Gewand wäscht er in Wein, / in Traubenblut den Mantel.", footnotes: ["an der Edelrebe. Der achtlose Umgang mit kostbaren Dingen ist ein Zeichen von Wohlstand."] },
      { number: 12, text: "Die Augen sind dunkler als Wein, / die Zähne weißer als Milch." },
      { number: 13, text: "Sebulon wohnt nah am Meer, / an der Küste bei den Schiffen, / den Rücken an Sidon* gelehnt.", footnotes: ["Sidon war eine Stadt in Phönizien, heute Saida im Libanon."] },
      { number: 14, text: "Issachar ist ein knochiger Esel, / der zwischen seinen Sattelkörben liegt.*", footnotes: ["Sattelkörben liegt. Packesel legten sich oft störrisch mitsamt den beiden Sattelkörben nieder."] },
      { number: 15, text: "Er sah die schöne Ruhe / und dieses freundliche Land, / da beugte er seine Schulter zum Tragen / und leistete Zwangsarbeit." },
      { number: 16, text: "Dan wird Richter sein in seinem Volk / wie nur einer von Israels Stämmen." },
      { number: 17, text: "Dan ist wie eine Schlange am Weg, / eine Hornotter am Pfad. / Sie beißt das Pferd in die Fesseln, / sein Reiter stürzt rücklings herab." },
      { number: 18, text: "– Ich warte auf deine Hilfe, Jahwe! –" },
      { number: 19, text: "Gad wird von Räuberscharen umdrängt, / doch er bedrängt ihre Ferse." },
      { number: 20, text: "Aschers Nahrung ist die beste, die es gibt, / er liefert Speise für den Tisch des Königs." },
      { number: 21, text: "Naftali, die flüchtige Hirschkuh, / versteht sich auf gefällige Rede." },
      { number: 22, text: "Ein junger Fruchtbaum ist Josef, / ein junger Fruchtbaum am Quell, / seine Zweige ranken über die Mauer." },
      { number: 23, text: "Da reizten ihn die Bogenschützen, / feindselig beschossen sie ihn." },
      { number: 24, text: "Aber sein Bogen bleibt fest, / mit rascher Hand schießt er zurück, / gelenkt von den Händen des Mächtigen, / von Jakobs Gott, / dem Hirten und dem Stein von Israel," },
      { number: 25, text: "vom Gott deines Vaters, der dir hilft, / dem Allmächtigen, der dich segnet. / Er segnet dich mit Regen aus dem Himmel / und mit Wasser aus der Tiefe, / mit Überfluss aus Mutterbrüsten / und Fruchtbarkeit vom Mutterschoß." },
      { number: 26, text: "Der Segen deines Vaters übertrifft den Segen der uralten Berge / und das Begehrenswerte der ewigen Hügel. / Dieser Segen sei auf Josefs Haupt, / dem Auserwählten seiner Brüder." },
      { number: 27, text: "Benjamin ist wie ein reißender Wolf: / Am Morgen frisst er die Beute, / am Abend teilt er den Raub.\"" },
      { number: 28, text: "Diese alle sind die Stämme Israels, und das ist es, was ihr Vater zu ihnen sagte, als er sie segnete. Jeden von ihnen bedachte er mit dem Segen, der ihm zukam." },
      { number: 29, text: "Dann befahl er ihnen: \"Wenn ich zu meinem Volk eingeholt worden bin, begrabt mich bei meinen Vätern in der Höhle, die auf dem Feld des Hetiters Efron liegt;" },
      { number: 30, text: "in der Höhle auf dem Feld Machpela östlich von Mamre im Land Kanaan auf dem Grundstück, das Abraham als Grabstätte für seine Familie von dem Hetiter Efron erworben hat." },
      { number: 31, text: "Dort wurden Abraham und seine Frau Sara begraben; dort liegen Isaak und Rebekka, und auch Lea habe ich dort beigesetzt." },
      { number: 32, text: "Das Feld und die Höhle darauf sind unser rechtmäßiges Eigentum, das wir von den Hetitern erworben haben.\"" },
      { number: 33, text: "Nachdem Jakob seinen Söhnen diese Anweisungen gegeben hatte, zog er seine Füße aufs Bett herauf. Er starb und wurde im Tod mit seinen Vorfahren vereint." },
    ] },
    { number: 50, verses: [
      { number: 1, text: "Josef warf sich über seinen Vater, weinte um ihn und küsste ihn.", heading: "Jakobs Begräbnis" },
      { number: 2, text: "Dann befahl er den Ärzten, die ihm dienten, seinen Vater Israel einzubalsamieren." },
      { number: 3, text: "Das dauerte wie üblich vierzig Tage. Ganz Ägypten trauerte siebzig Tage um Israel." },
      { number: 4, text: "Als die Trauerzeit vorüber war, bat Josef die königlichen Hofbeamten: \"Wenn ihr mir eine Gunst erweisen wollt, dann richtet dem Pharao aus:" },
      { number: 5, text: "'Mein Vater hat mich schwören lassen, ihn im Land Kanaan beizusetzen, in dem Grab, das er für sich vorbereitet hat. Lass mich hinziehen und meinen Vater dort begraben! Dann komme ich wieder zurück.'\"" },
      { number: 6, text: "Der Pharao ließ ihm antworten: \"Zieh hin und begrabe deinen Vater, wie du es ihm geschworen hast!\"" },
      { number: 7, text: "Josef machte sich auf den Weg. Die hohen Beamten des Pharao und die führenden Männer Ägyptens begleiteten ihn." },
      { number: 8, text: "Dazu kam das ganze Haus Josefs, alle seine Brüder und die Familie seines Vaters. Nur ihre Kinder und ihre Schafe und Rinder ließen sie in Goschen zurück." },
      { number: 9, text: "Sogar Streitwagen und Reiter zogen mit ihm hinauf. Es wurde ein gewaltiges Heerlager." },
      { number: 10, text: "Als sie bis nach Goren-Atad* in der Nähe des Jordan gekommen waren, hielten sie eine sehr große und würdige Trauerfeier. Sieben Tage lang ließ Josef die Totenklage für seinen Vater dauern.", footnotes: ["Goren-Atad heißt Stechdorn-Tenne, seine Ortslage ist unbekannt."] },
      { number: 11, text: "Die Einheimischen, die Bewohner des Landes Kanaan, beobachteten die Trauerfeier in Goren-Atad und sagten: \"Eine würdige Trauer ist das für Ägypten!\" Darum nannten sie den Platz Abel-Mizrajim, Trauer der Ägypter." },
      { number: 12, text: "So erfüllten Jakobs Söhne den letzten Wunsch ihres Vaters." },
      { number: 13, text: "Sie brachten ihn ins Land Kanaan und begruben ihn in der Höhle des Grundstücks von Machpela. Abraham hatte dieses Grundstück gegenüber von Mamre als eigene Grabstätte von dem Hetiter Efron gekauft." },
      { number: 14, text: "Nachdem Josef seinen Vater beigesetzt hatte, kehrte er mit seinen Brüdern und allen, die mit ihm gezogen waren, nach Ägypten zurück." },
      { number: 15, text: "Nach dem Tod ihres Vaters gerieten Josefs Brüder in Sorge: \"Was ist, wenn Josef sich nun feindlich gegen uns stellt und uns das Böse heimzahlt, das wir ihm angetan haben?\"", heading: "Bestätigung der Vergebung" },
      { number: 16, text: "So ließen sie Josef sagen: \"Dein Vater hat uns vor seinem Tod aufgetragen:" },
      { number: 17, text: "'Bittet Josef: Vergib doch die Sünde und das Verbrechen deiner Brüder; vergib, dass sie dir Böses angetan haben!' Deshalb bitten wir dich: Vergib uns das Verbrechen! Wir dienen doch demselben Gott wie unser Vater!\" Als Josef das hörte, weinte er." },
      { number: 18, text: "Danach kamen die Brüder selbst zu Josef, fielen vor ihm nieder und sagten: \"Wir sind deine Sklaven!\"" },
      { number: 19, text: "Aber Josef erwiderte: \"Habt keine Angst! Bin ich denn an Gottes Stelle?" },
      { number: 20, text: "Ihr hattet zwar Böses mit mir vor, aber Gott hat es zum Guten gewendet, um zu erreichen, was heute geschieht: ein großes Volk am Leben zu erhalten." },
      { number: 21, text: "Habt also keine Angst! Ich werde euch und eure Kinder versorgen.\" So beruhigte er sie und redete ihnen zu Herzen." },
      { number: 22, text: "Josef blieb mit allen Nachkommen seines Vaters in Ägypten. Er wurde 110 Jahre alt", heading: "Josefs Ende" },
      { number: 23, text: "und sah noch Efraïms Söhne und Enkel. Auch die Söhne von Machir Ben-Manasse, wurden auf Josefs Knien geboren*.", footnotes: ["auf ... geboren. Das heißt, sie wurden von Josef adoptiert."] },
      { number: 24, text: "Josef sagte zu seinen Brüdern: \"Ich muss sterben, aber Gott wird euch nicht vergessen. Er wird euch aus diesem Land wieder in das Land bringen, das er Abraham, Isaak und Jakob zugeschworen hat.\"" },
      { number: 25, text: "Dann ließ Josef die Söhne Israels schwören: \"Wenn Gott sich euer annimmt, dann nehmt meine Gebeine von hier mit!\"" },
      { number: 26, text: "Josef starb im Alter von 110 Jahren. Man balsamierte ihn ein und legte ihn in einen Sarg in Ägypten." },
    ] },
  ],
};